window.PROOFS = {"meta":{"source":"https://github.com/openai/math","commit":"adc7f1241","families":372,"papers":722,"leanFamilies":127,"leanPapers":162,"tiers":{"A":39,"B":145,"C":188},"built":2},"disciplines":["Number theory","Algebraic and complex geometry","Real and complex analysis","Convex and metric geometry","Theoretical computer science","Dynamical systems and ergodic theory","Combinatorics","Algebra","Probability and statistical mechanics","Mathematical logic","Group theory","Mathematical physics","Operator algebras","Topology","Functional analysis","Differential geometry","Partial differential equations"],"families":[{"id":"001","t":"Milne's rationality conjecture","d":"Proves Milne's rationality conjecture for abelian varieties over ℚ̅ with good reduction: specialized Hodge classes pair rationally with complementary divisor products, independently of cohomology theory. Together with result 032, every specialized Hodge class is represented by a single rational algebraic cycle simultaneously in all prime-to-p and crystalline realizations, for every residue characteristic p.","disc":0,"tier":"C","effort":"S","widget":"Text card on Hodge classes on abelian varieties and reduction mod p; nothing finite to compute.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Milne's rationality conjecture for abelian varieties","dir":"Milnes-rationality-conjecture-for-abelian-varieties-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"002","t":"The full Birch–Swinnerton-Dyer formula in Selmer coranks zero and one","d":"Proves the full Birch–Swinnerton-Dyer leading-term formula for every elliptic curve over ℚ whose full q-power Selmer group has corank zero or one for some prime q, including finiteness of the Tate–Shafarevich group. With result 006, this gives full BSD for a density-one set of quadratic twists of every elliptic curve over ℚ.","disc":0,"tier":"C","effort":"S","widget":"Text card on BSD: rank, Sha and the leading-term formula, perhaps with a table of curves.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Exact Birch–Swinnerton-Dyer Formula from Low Selmer Corank","dir":"Exact-Birch-Swinnerton-Dyer-Formula-from-Low-Selmer-Corank-October-3-2026","pdf":"exact-bsd-low-selmer-corank.pdf","lean":false},{"t":"The Selmer converse for elliptic curves at every prime","dir":"The-Selmer-converse-for-elliptic-curves-at-every-prime-September-24-2026","pdf":"main.pdf","lean":false},{"t":"The two-primary Birch–Swinnerton-Dyer formula in Selmer corank at most one","dir":"The-two-primary-Birch-Swinnerton-Dyer-formula-in-Selmer-corank-at-most-one-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"003","t":"The quasi-Riemann hypothesis","d":"Proves that every Dirichlet L-function, including ζ(s), is zero-free in Re s>7/8, resolving the quasi-Riemann hypothesis. The same half-plane is zero-free for every finite-order Hecke L-function over ℚ(√(-3)). A companion gives a different proof of the zero-free half-plane Re s>11/12.","disc":0,"tier":"B","effort":"M","widget":"Plot |L(s,chi)| and zeros of zeta/Dirichlet L-functions over the critical strip with the proven zero-free half-plane Re s>7/8 shaded against RH's line 1/2.","related":[],"conj":true,"page":null,"lean":2,"papers":[{"t":"The Quasi-Riemann Hypothesis: A Zero-Free Half-Plane Re s> 7/8 ","dir":"The-Quasi-Riemann-Hypothesis-September-30-2026","pdf":"paper.pdf","lean":true},{"t":"The Quasi-Riemann Hypothesis (alternate 11/12 proof)","dir":"The-Quasi-Riemann-Hypothesis-October-5-2026","pdf":"paper2.pdf","lean":false},{"t":"Uniform exclusion of Landau–Siegel zeros","dir":"Uniform-exclusion-of-Landau-Siegel-zeros-October-1-2026","pdf":"paper.pdf","lean":true}]},{"id":"004","t":"Hilbert's tenth problem over ℚ","d":"Proves that no algorithm decides whether an integer-coefficient polynomial in an arbitrary number of variables has a rational zero, resolving Hilbert's tenth problem over ℚ negatively.","disc":0,"tier":"C","effort":"S","widget":"Text card on why deciding rational solvability of polynomial equations is impossible, beside the integer (Matiyasevich) case.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Hilbert’s tenth problem over the rational numbers","dir":"Hilberts-tenth-problem-over-the-rational-numbers-September-24-2026","pdf":"main.pdf","lean":false},{"t":"A pointwise 2-converse for elliptic curves with rational two-torsion","dir":"A-pointwise-2-converse-for-elliptic-curves-with-rational-two-torsion-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"005","t":"Irrationality of Catalan's constant","d":"Proves that Catalan's constant G=∑_(j≥0)(-1)ʲ/(2j+1)² is irrational.","disc":0,"tier":"A","effort":"M","widget":"Watch rational approximations to Catalan's constant G converge and see the cleared-denominator linear forms shrink, with the paper's exact barrier certificate replayed live.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Catalan's constant is irrational","dir":"Catalans-constant-is-irrational-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"006","t":"Goldfeld's conjecture","d":"Proves Goldfeld's conjecture for quadratic twists of every elliptic curve over ℚ: analytic ranks zero and one each have density 1/2, and the mean analytic rank tends to 1/2. Both statements order signed squarefree twist parameters by absolute value.","disc":0,"tier":"C","effort":"M","widget":"Text card: quadratic twists of an elliptic curve split 50/50 between analytic rank 0 and 1; at most a root-number parity tally.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Goldfeld's analytic density conjecture and the 2-converse for elliptic curves","dir":"Goldfelds-analytic-density-conjecture-and-the-2-converse-for-elliptic-curves-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"The mean analytic rank of quadratic twists of elliptic curves","dir":"The-mean-analytic-rank-of-quadratic-twists-of-elliptic-curves-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"007","t":"Two-point Chowla and the corrected binary Elliott conjecture","d":"Proves the ordinary two-point Chowla conjecture, with a bound O(X/(log X)ᶜ) for Liouville correlation sums along fixed nonproportional affine forms, where c>0 is absolute. More generally, proves the binary corrected Elliott conjecture for complex multiplicative functions bounded by one when one factor is uniformly nonpretentious against each fixed Dirichlet character times nⁱᵗ for |t|≤ X.","disc":0,"tier":"B","effort":"S","widget":"Plot the Liouville function's two-point correlation sum sum lambda(n)lambda(n+h) (and along other affine forms) up to X 10⁷ against X/(log X)ᶜ, showing the cancellation the theorem proves.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Ordinary two-point correlations of multiplicative functions","dir":"Ordinary-two-point-correlations-of-multiplicative-functions-September-24-2026","pdf":"final.pdf","lean":false}]},{"id":"008","t":"The Deligne–Drinfeld conjecture","d":"Proves that the rational Grothendieck–Teichmüller Lie algebra, with the Ihara bracket, is freely generated by one element in each odd weight 3,5,7,…, resolving the Deligne–Drinfeld conjecture.","disc":0,"tier":"C","effort":"S","widget":"Text card on the Grothendieck–Teichmüller Lie algebra and its free odd generators.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The Deligne-Drinfeld conjecture","dir":"The-Deligne-Drinfeld-conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"009","t":"Bogomolov–Pop and Milnor K-theoretic reconstruction","d":"Reconstructs function fields of transcendence degree at least two over algebraically closed constants from K^(M)₁/ℓ, K^(M)₂/ℓ, and their product. These data recover the perfect closure and constants when ℓ differs from the characteristic, and the original field and its named base in equal characteristic. Also proves Bogomolov–Pop reconstruction from abelian-by-central pro-ℓ Galois data away from the characteristic.","disc":0,"tier":"C","effort":"S","widget":"Text card on recovering a function field from its mod-l Milnor K-groups (anabelian reconstruction).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Reconstruction of Function Fields from Mod-ℓ Milnor K-Theory","dir":"Reconstruction-of-Function-Fields-from-Mod-ell-Milnor-K-Theory-October-5-2026","pdf":"mod-ell-bogomolov-pop.pdf","lean":false},{"t":"Reconstruction from Milnor K-theory modulo the characteristic","dir":"Reconstruction-from-Milnor-K-theory-modulo-the-characteristic-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"The Bogomolov-Pop reconstruction theorem","dir":"The-Bogomolov-Pop-reconstruction-theorem-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"010","t":"Fontaine–Mazur modularity at the prime 2 and 2-adic pro-modularity","d":"Every continuous odd absolutely irreducible two-dimensional 2-adic representation of G_(ℚ) unramified outside finitely many primes occurs in a completed Hecke algebra at some odd tame level. Also proves classical modularity up to Tate twist for irreducible odd representations with these finiteness conditions that are de Rham at 2 with distinct Hodge–Tate weights, resolving the dyadic Fontaine–Mazur case without residual restrictions.","disc":0,"tier":"C","effort":"S","widget":"Card explaining modularity of 2-adic Galois representations.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Unrestricted pro-modularity at the prime two","dir":"Unrestricted-pro-modularity-at-the-prime-two-October-4-2026","pdf":"two-adic-promodularity.pdf","lean":false},{"t":"The Dimension of the Two-Adic Hecke Algebra at Odd Level","dir":"The-Dimension-of-the-Two-Adic-Hecke-Algebra-at-Odd-Level-October-5-2026","pdf":"two-adic-hecke.pdf","lean":false},{"t":"Fontaine–Mazur modularity at the prime 2","dir":"Fontaine-Mazur-modularity-at-the-prime-2-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"011","t":"The Ford–Konyagin–Luca conjecture on prime predecessors","d":"Proves that the normalized ordered logarithms of the prime factors of p-1, counted with multiplicity, converge jointly to the Poisson–Dirichlet law PD(1) as p ranges uniformly over primes up to x and x→∞. This resolves the Ford–Konyagin–Luca conjecture. It also proves that infinitely many integers n have more than n^(1-ε) totient preimages, for every ε>0.","disc":0,"tier":"B","effort":"S","widget":"Sample primes p, factor p-1, and compare the ordered log-sizes of its prime factors against the Poisson-Dirichlet PD(1) law; also explore large totient fibers.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Weighted dilation graphs, smooth shifted primes and totient fibers","dir":"Weighted-Dilation-Graphs-Smooth-Shifted-Primes-and-Totient-Fibers-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"The Poisson-Dirichlet law for prime predecessors","dir":"The-Poisson-Dirichlet-Law-for-Prime-Predecessors-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Prime Predecessors with an Even Number of Prime Factors","dir":"Prime-Predecessors-with-an-Even-Number-of-Prime-Factors-September-17-2026","pdf":"paper.pdf","lean":false}]},{"id":"012","t":"Independent largest prime factors of consecutive integers","d":"Resolves the Erdős–Pomerance joint Dickman conjecture: the logarithmic sizes of the largest prime factors of n and n+1 are asymptotically independent in ordinary natural density. In particular, the integers satisfying P⁺(n)<P⁺(n+1) have density 1/2.","disc":0,"tier":"B","effort":"S","widget":"Scatter log P+(n)/log n against log P+(n+1)/log(n+1) for n up to 10⁷ and watch the joint histogram approach a product of two Dickman densities; live tally of P+(n)<P+(n+1).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The joint Dickman law for consecutive integers","dir":"The-joint-Dickman-law-for-consecutive-integers-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"013","t":"Ostmann's inverse Goldbach conjecture","d":"Proves that no finite modification of the primes can be written as A+B with A,B⊆ℤ_(≥0) each containing at least two elements. This resolves Ostmann's inverse Goldbach conjecture on additive indecomposability.","disc":0,"tier":"B","effort":"M","widget":"Pick two small sets A, B and watch A+B against the primes: a sandbox showing why sumsets develop structure (residue classes, gaps) that the primes lack.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The additive indecomposability of the primes","dir":"the-additive-indecomposability-of-the-primes-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"014","t":"Restricted geometric Langlands, generic Ramanujan and Arthur parameters","d":"Proves the restricted geometric Langlands equivalence for connected reductive groups on smooth projective connected curves over 𝔽̅_(q) under the four stated Lie-theoretic characteristic hypotheses. Over arbitrary algebraically closed fields of characteristic p>0, the same conclusion holds assuming additionally that p is very good for the group and p∤ |W_(G)|. Over global function fields, proves Ramanujan at every place for globally generic cuspidal representations of split adjoint absolutely simple exceptional groups, without characteristic or ramification-depth restrictions, and at every unramified place for cuspidal representations of split adjoint absolutely simple groups with a generic unramified component. Assuming the finite-level Ramanujan–Arthur decomposition, constructs global Arthur enhancements of occurring cuspidal excursion parameters for split connected semisimple groups at full finite level, recovering the given parameters by diagonal specialization on the entire Weil group, including inertia.","disc":0,"tier":"C","effort":"S","widget":"Text card on restricted geometric Langlands over finite fields.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Global Arthur Enhancements of Cuspidal Excursion Parameters","dir":"Global-Arthur-Enhancements-of-Cuspidal-Excursion-Parameters-October-5-2026","pdf":"manuscript.pdf","lean":false},{"t":"Rationality of the Canonical Unramified Arthur Filtration","dir":"Rationality-of-the-Canonical-Unramified-Arthur-Filtration-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Ramanujan-Arthur Decompositions of Cuspidal Functions at Full Finite Level","dir":"Ramanujan-Arthur-Decompositions-of-Cuspidal-Functions-at-Full-Finite-Level-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Temperedness at ramified places for globally generic exceptional groups","dir":"Temperedness-at-ramified-places-for-globally-generic-exceptional-groups-October-5-2026","pdf":"ramified-ramanujan.pdf","lean":false},{"t":"The Restricted Geometric Langlands Equivalence in Positive Characteristic","dir":"The-Restricted-Geometric-Langlands-Equivalence-in-Positive-Characteristic-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Constructible tame Hecke eigensheaves in positive characteristic","dir":"Constructible-tame-Hecke-eigensheaves-in-positive-characteristic-October-5-2026","pdf":"constructible-tame-hecke-eigensheaves-positive-characteristic.pdf","lean":false},{"t":"Tame Hecke Eigensheaves with Several Marked Points","dir":"Tame-Hecke-Eigensheaves-with-Several-Marked-Points-October-5-2026","pdf":"Tame-Hecke-Eigensheaves-with-Several-Marked-Points.pdf","lean":false},{"t":"Frobenius Structures on Tame Hecke Eigensheaves","dir":"Frobenius-Structures-on-Tame-Hecke-Eigensheaves-October-5-2026","pdf":"tame-hecke-frobenius.pdf","lean":false}]},{"id":"015","t":"Torus-packet equidistribution in prime, quartic, and sextic degrees","d":"Proves Haar equidistribution without escape of mass for complete volume-weighted torus packets from totally real fields: arbitrary lattices and prescribed local types in fixed prime degree at least five, arbitrary-order Picard packets in primitive quartic fields, and maximal-order ideal-class packets in primitive sextic fields. Here primitive means having no proper intermediate field; the relevant order or field discriminant tends to infinity.","disc":0,"tier":"B","effort":"L","widget":"Animate CM/Heegner-type torus orbits on the modular surface filling it uniformly as the discriminant grows (degree-2 analogue of the packets).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Equidistribution of Prime-Degree Torus Packets with Arbitrary Local Type","dir":"Equidistribution-of-Prime-Degree-Torus-Packets-with-Arbitrary-Local-Type-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Equidistribution of primitive quartic torus packets for arbitrary orders","dir":"Equidistribution-of-Primitive-Quartic-Torus-Packets-for-Arbitrary-Orders-October-5-2026","pdf":"quartic-torus-packets.pdf","lean":false},{"t":"Equidistribution of Primitive Sextic Torus Packets","dir":"Equidistribution-of-Primitive-Sextic-Torus-Packets-October-5-2026","pdf":"primitive-sextic-torus-packets.pdf","lean":false}]},{"id":"016","t":"Zilber–Pink in abelian varieties and the Siegel threefold","d":"Proves the abelian Zilber–Pink conjecture over ℚ̅: every irreducible subvariety has finitely many maximal atypical subvarieties relative to its smallest containing torsion coset. It also proves the full curve case in the Siegel threefold 𝒜₂ for Hodge-generic curves defined over ℚ̅, without boundary or reduction assumptions.","disc":0,"tier":"C","effort":"S","widget":"Card on unlikely intersections in abelian varieties and A2.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The abelian Zilber–Pink conjecture","dir":"The-Abelian-Zilber-Pink-Conjecture-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"The E×CM component of Zilber–Pink for curves in A2","dir":"The-E-times-CM-Component-of-Zilber-Pink-for-Curves-in-A2-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Quaternionic division points on curves in the Siegel threefold","dir":"Quaternionic-Division-Points-on-Curves-in-the-Siegel-Threefold-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Elliptic squares and Zilber–Pink for curves in A2","dir":"Elliptic-Squares-and-Zilber-Pink-for-Curves-in-A2-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"017","t":"The irrationality exponent of π is 2","d":"Proves that the irrationality exponent of π is exactly 2: for every ε>0 and all sufficiently large denominators q, every rational p/q satisfies |π-p/q|≥ q^(-2-ε). This also proves convergence of the Flint–Hills series ∑_(n≥1)1/(n³sin² n), with angles in radians.","disc":0,"tier":"B","effort":"S","widget":"Explore continued fractions of pi: plot q²|pi - p/q| for convergents and the partial sums of the Flint-Hills series sum 1/(n³ sin² n).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The irrationality exponent of pi is 2","dir":"The-irrationality-exponent-of-pi-is-2-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"018","t":"The Margulis–Platonov conjecture over global fields","d":"Proves the Margulis–Platonov conjecture over every global field, including function fields of characteristic two. For an absolutely almost simple simply connected algebraic group G over k, every noncentral abstract normal subgroup of G(k) is the inverse image of an open normal subgroup in the finite product of its anisotropic nonarchimedean local groups.","disc":0,"tier":"C","effort":"S","widget":"Text card on normal subgroups of arithmetic groups (Margulis–Platonov).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Margulis–Platonov conjecture over global function fields","dir":"The-Margulis-Platonov-conjecture-over-global-function-fields-October-5-2026","pdf":"margulis-platonov-global-function-fields.pdf","lean":false},{"t":"The Margulis–Platonov conjecture over number fields","dir":"The-Margulis-Platonov-conjecture-over-number-fields-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"019","t":"The p-adic section conjecture","d":"Proves that rational points on every smooth proper geometrically connected curve of genus at least two over a finite extension of ℚₚ correspond bijectively to conjugacy classes of sections of its full arithmetic étale fundamental group. It also proves Grothendieck's section conjecture over ℚ for the modular curves X₀(N) and X₁(N) of genus at least two.","disc":0,"tier":"C","effort":"S","widget":"Text card on anabelian geometry: rational points vs Galois sections for curves over p-adic fields and modular curves.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Étale covers with a prescribed exterior sheet","dir":"Etale-covers-with-a-prescribed-exterior-sheet-September-24-2026","pdf":"main.pdf","lean":false},{"t":"The p-adic section conjecture","dir":"The-p-adic-section-conjecture-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"020","t":"Squarefree quartics and power-free polynomial values","d":"Proves the squarefree-values conjecture for irreducible integer quartics with no fixed prime-square divisor: squarefree values on positive integers have the predicted positive Euler-product density. More generally, establishes the (d-2)-power-free density for irreducible integer polynomials of degrees four through eight under the necessary local condition; together with Browning's higher-degree theorem, this covers every d≥4.","disc":0,"tier":"B","effort":"S","widget":"Pick an irreducible quartic like n⁴+2, count squarefree values up to N and watch the fraction converge to the predicted Euler-product density.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Squarefree values of quartics and power-free values of polynomials","dir":"Squarefree-values-of-quartics-and-power-free-values-of-polynomials-September-24-2026","pdf":"manuscript.pdf","lean":true}]},{"id":"021","t":"A quadratic bound for Jacobsthal's function","d":"Answers Jacobsthal's quadratic-bound question: every interval of Ck² consecutive integers contains an integer coprime to any prescribed positive integer with at most k distinct prime divisors, for an absolute constant C. The bound is uniform over prime sets and interval positions and removes the classical logarithmic loss.","disc":0,"tier":"B","effort":"S","widget":"Compute Jacobsthal's function j(n) for products of the first k primes and plot j/k² to see the quadratic scale.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A quadratic bound for Jacobsthal's function","dir":"A-quadratic-bound-for-Jacobsthals-function-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"022","t":"The weak inhomogeneous Duffin–Schaeffer conjecture","d":"Proves that for every real shift γ and finite-valued ψ:ℕ→[0,∞), divergence of ∑_(q)φ(q)ψ(q)/q implies ‖qx-γ‖<ψ(q) for infinitely many q, for almost every x. Here φ is Euler's totient and the norm is distance to the nearest integer. Numerators are unrestricted; no monotonicity or Diophantine condition on γ is needed.","disc":0,"tier":"B","effort":"M","widget":"Plot ||qx-gamma|| against psi(q) for a chosen x and shift gamma and watch hits accumulate (or not) as q grows.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Weak Inhomogeneous Duffin–Schaeffer Conjecture","dir":"The-weak-inhomogeneous-Duffin-Schaeffer-conjecture-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"023","t":"Patterson’s first moment for cubic Gauss sums","d":"Proves unconditionally the all-primary-prime form of Patterson’s first-moment asymptotic: normalized cubic Gauss sums over primary Eisenstein primes of norm at most X, including both conjugates, have an explicit positive main term of order X^(5/6)/log X. Every fixed nonzero prime-angle Fourier mode has smaller order.","disc":0,"tier":"B","effort":"M","widget":"Compute cubic Gauss sums over Eisenstein primes and watch the normalized angles and the first moment build up against the predicted X^(5/6)/log X main term.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An unconditional first moment for cubic Gauss sums","dir":"An-unconditional-first-moment-for-cubic-Gauss-sums-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"024","t":"An asymptotic formula for the number of totients","d":"Gives an asymptotic equivalent for the number V(x) of distinct totient values up to x, with a positive bounded phase-dependent factor determined by convergent arithmetic approximations. In particular, V(cx)/V(x)→ c for every fixed c>0, answering Erdős and Hall’s scaling question.","disc":0,"tier":"B","effort":"M","widget":"Count distinct totient values V(x) up to 10⁷ and plot V(cx)/V(x) against c, plus V(x) against the paper's asymptotic with its oscillating phase factor.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An asymptotic formula for the number of totients","dir":"An-asymptotic-formula-for-the-number-of-totients-September-25-2026","pdf":"An-asymptotic-formula-for-the-number-of-totients-September-25-2026.pdf","lean":false}]},{"id":"025","t":"Erdős’s short Egyptian-fraction conjecture","d":"Every rational a/b with 1≤ a<b is a sum of O(loglog b) distinct positive unit fractions. The worst-case minimum number of terms has the same order, resolving Erdős’s conjecture on short Egyptian fractions.","disc":0,"tier":"B","effort":"M","widget":"Enter a/b and see greedy vs. shortest Egyptian-fraction expansions (exact search for small b), plotted against log log b.","related":[],"conj":true,"page":null,"lean":1,"papers":[{"t":"Short Egyptian fractions","dir":"Short-Egyptian-fractions-September-25-2026","pdf":"Short-Egyptian-fractions-September-25-2026.pdf","lean":true}]},{"id":"026","t":"Positive lower density of large prime gaps","d":"For every fixed C>0, a positive proportion of consecutive prime gaps exceed Clog pₙ, throughout every sufficiently large initial segment of the primes. The proportion may depend on C. Consequently, the indices where pₙ/n increases have positive lower density, answering Erdős and Prachar.","disc":0,"tier":"B","effort":"S","widget":"Scroll through primes, mark gaps exceeding C log p, and plot the running proportion for adjustable C.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Positive lower density of large prime gaps","dir":"Positive-lower-density-of-large-prime-gaps-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"027","t":"Integral density on curve character varieties","d":"Resolves the determinant-one curve case of Litt's integral-density question. For every smooth connected complex algebraic curve and every rank, integral points become Zariski dense in every component of its SLᵣ character variety over the full ring of integers of one number field. Prescribed quasi-unipotent boundary conjugacy classes are allowed, including nonsemisimple classes.","disc":0,"tier":"C","effort":"S","widget":"Text card on integral points in SLᵣ character varieties of curves.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Integral points on character varieties of curves","dir":"Integral-points-on-character-varieties-of-curves-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"028","t":"The Gaussian moat conjecture","d":"Proves the Gaussian moat conjecture: no infinite walk through distinct Gaussian primes can have uniformly bounded steps. More strongly, for every distance bound D, the graph joining Gaussian primes at distance at most D has uniformly bounded finite component sizes, depending only on D, including primes on the coordinate axes.","disc":0,"tier":"B","effort":"M","widget":"Draw Gaussian primes in a window, pick a step bound D, and colour the connected components of the D-step graph to see moats appear.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Bounded-Step Walks on Gaussian Primes","dir":"Bounded-Step-Walks-on-Gaussian-Primes-September-26-2026","pdf":"paper.pdf","lean":true}]},{"id":"029","t":"Artin's primitive root conjecture: infinitude for every base","d":"Proves the infinitude assertion in Artin's primitive root conjecture for every integer a that is neither -1 nor a square. For each such base, at least cₐ x/(log x)² primes in every sufficiently large interval (x,2x) have primitive root a, with cₐ>0.","disc":0,"tier":"B","effort":"S","widget":"Pick a base a, count primes up to x with primitive root a, and compare against Artin's predicted density.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Primitive roots for every admissible integer base","dir":"Primitive-roots-for-every-admissible-integer-base-October-4-2026","pdf":"primitive-roots-all-integer-bases.pdf","lean":false},{"t":"Simultaneous primitive roots: a conditional lower bound for prime bases","dir":"Simultaneous-primitive-roots-a-conditional-lower-bound-for-prime-bases-October-4-2026","pdf":"simultaneous-primitive-roots-conditional-lower-bound-prime-bases.pdf","lean":false}]},{"id":"030","t":"Modularity over imaginary quadratic fields","d":"Proves the modularity conjecture for elliptic curves over imaginary quadratic fields: every elliptic curve over every imaginary quadratic field is modular, with matching local parameters at every place.","disc":0,"tier":"C","effort":"S","widget":"Text card: every elliptic curve over an imaginary quadratic field is modular.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Modularity of elliptic curves over imaginary quadratic fields","dir":"Modularity-of-elliptic-curves-over-imaginary-quadratic-fields-October-4-2026","pdf":"paper.pdf","lean":false}]},{"id":"031","t":"Uchida's conjecture for open Galois homomorphisms","d":"Proves Uchida's conjecture: every continuous open homomorphism between Galois groups of possibly infinite solvably closed Galois extensions of number fields comes from a unique equivariant field embedding in the opposite direction. No restriction on the kernel or separate cyclotomic-compatibility assumption is needed.","disc":0,"tier":"C","effort":"S","widget":"Text card on Uchida/Neukirch-type anabelian reconstruction of number fields from Galois groups.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Open Homomorphisms of Global Solvably Closed Galois Groups","dir":"Open-Homomorphisms-of-Global-Solvably-Closed-Galois-Groups-October-5-2026","pdf":"open-homomorphisms-solvably-closed-galois-groups.pdf","lean":false}]},{"id":"032","t":"The rational Hodge conjecture for CM abelian varieties and products of K3 surfaces","d":"Proves the rational Hodge conjecture for every complex CM abelian variety, in every dimension and codimension. Through Milne's theorems, this also gives the Tate conjecture for all abelian varieties over finite fields and the Hodge standard conjecture for abelian varieties in every characteristic. Companion results prove rational Hodge for arbitrary products of projective complex K3 surfaces and algebraicity of the Kuga–Satake correspondence for every such surface.","disc":1,"tier":"C","effort":"S","widget":"Text card on Hodge classes on CM abelian varieties and K3 products.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"The rational Hodge conjecture for CM abelian varieties","dir":"The-rational-Hodge-conjecture-for-CM-abelian-varieties-September-30-2026","pdf":"paper.pdf","lean":false},{"t":"The rational Hodge conjecture for products of K3 surfaces","dir":"The-rational-Hodge-conjecture-for-products-of-K3-surfaces-October-4-2026","pdf":"hodge-conjecture-products-k3.pdf","lean":false},{"t":"Algebraicity of Kuga–Satake Correspondences for K3 Surfaces","dir":"Algebraicity-of-Kuga-Satake-Correspondences-for-K3-Surfaces-October-3-2026","pdf":"manuscript.pdf","lean":false},{"t":"Algebraic Kuga–Satake correspondences and Hodge conjectures on a K3 quadratic locus","dir":"Algebraic-Kuga-Satake-correspondences-and-Hodge-conjectures-on-a-K3-quadratic-locus-September-30-2026","pdf":"paper.pdf","lean":false},{"t":"Weil classes and Hodge classes on abelian powers","dir":"Weil-classes-and-Hodge-classes-on-abelian-powers-September-30-2026","pdf":"paper.pdf","lean":false},{"t":"Abelian covers, Gale correspondences, and the Hodge conjecture for powers","dir":"Abelian-covers-Gale-correspondences-and-the-Hodge-conjecture-for-powers-September-30-2026","pdf":"paper.pdf","lean":false},{"t":"Algebraicity of Weil classes on split abelian eightfolds","dir":"Algebraicity-of-Weil-classes-on-split-abelian-eightfolds-September-18-2026","pdf":"paper.pdf","lean":false},{"t":"A Conditional Reduction for Algebraic Kuga–Satake Correspondences","dir":"A-Conditional-Reduction-for-Algebraic-Kuga-Satake-Correspondences-September-10-2026","pdf":"paper.pdf","lean":false}]},{"id":"033","t":"Campana's orbifold Iitaka conjecture and logarithmic subadditivity","d":"Proves Campana's orbifold Iitaka subadditivity conjecture for smooth Fujiki-class-𝒞 manifolds with rational simple-normal-crossing boundaries. For projective fibrations f:U→ V of smooth complex quasi-projective varieties with connected fibers, general fiber F, and barκ(V)≥0, proves Popa's inequality barκ(U)≥κ(F)+max{barκ(V),Var(f)}, where variation measures the whole geometric generic fiber.","disc":1,"tier":"C","effort":"S","widget":"Text card on Iitaka subadditivity of Kodaira dimension.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Orbifold and logarithmic Iitaka subadditivity","dir":"Orbifold-and-logarithmic-Iitaka-subadditivity-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Logarithmic Kodaira dimension and whole-fiber variation","dir":"Logarithmic-Kodaira-dimension-and-whole-fiber-variation-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"The reverse logarithmic Kodaira inequality and additivity","dir":"The-reverse-logarithmic-Kodaira-inequality-and-additivity-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Projective Hodge lines and ordinary Iitaka subadditivity","dir":"Projective-Hodge-lines-and-ordinary-Iitaka-subadditivity-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"B-semiampleness for compact log-smooth Kähler fibrations","dir":"B-semiampleness-for-compact-log-smooth-Kahler-fibrations-September-10-2026","pdf":"paper.pdf","lean":false}]},{"id":"034","t":"Log abundance and effective Iitaka fibrations","d":"Using logarithmic Iitaka subadditivity, proves log abundance in every dimension for normal compact Kähler log canonical pairs with effective rational boundary: an analytically nef ℚ-Cartier adjoint is semiample. It also proves projective log abundance over every algebraically closed field of characteristic zero and the effective Iitaka fibration conjecture for smooth projective varieties of nonnegative Kodaira dimension in that setting. A further result resolves the finite-rational-coefficient index conjecture for connected projective semi-log-canonical log Calabi–Yau pairs over such fields in each fixed dimension and for each fixed finite set of rational boundary coefficients, with a uniform index independent of the number of components.","disc":1,"tier":"C","effort":"S","widget":"Card on abundance and Iitaka fibrations in birational geometry.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Log abundance for compact Kähler spaces under logarithmic Iitaka subadditivity","dir":"Log-abundance-for-compact-Kahler-spaces-under-logarithmic-Iitaka-subadditivity-October-4-2026","pdf":"main.pdf","lean":false},{"t":"Uniform indices for semi-log-canonical log Calabi–Yau pairs","dir":"Uniform-indices-for-semi-log-canonical-log-Calabi-Yau-pairs-October-5-2026","pdf":"uniform-slc-index.pdf","lean":false},{"t":"Conditional good minimal models for compact Kähler fourfolds","dir":"Conditional-good-minimal-models-for-compact-Kahler-fourfolds-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Log abundance in characteristic zero","dir":"Log-abundance-in-characteristic-zero-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Minimal metrics and interior injectivity for nef adjoints","dir":"Minimal-metrics-and-interior-injectivity-for-nef-adjoints-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Fourfold nonvanishing by minimal metrics and moving jets","dir":"Fourfold-nonvanishing-by-minimal-metrics-and-moving-jets-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Lifting sections from the reduced support of an adjoint","dir":"Lifting-sections-from-the-reduced-support-of-an-adjoint-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Schnell fiber spaces and good canonical models","dir":"Schnell-fiber-spaces-and-good-canonical-models-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Uniform log Iitaka fibrations and bounded moduli denominators","dir":"Uniform-log-Iitaka-fibrations-and-bounded-moduli-denominators-October-4-2026","pdf":"uniform-log-iitaka.pdf","lean":false},{"t":"Uniform Pluricanonical Iitaka Fibrations","dir":"Uniform-Pluricanonical-Iitaka-Fibrations-October-3-2026","pdf":"paper.pdf","lean":false},{"t":"Relative denominators and effective systems for log Calabi-Yau fibrations","dir":"Relative-denominators-and-effective-systems-for-log-Calabi-Yau-fibrations-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Arithmetic Stein-degree bounds for log Calabi–Yau pairs","dir":"Arithmetic-Stein-degree-bounds-for-log-Calabi-Yau-pairs-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Uniform effective log Iitaka fibrations for fourfolds","dir":"Uniform-effective-log-Iitaka-fibrations-for-fourfolds-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Abundance after nonvanishing for compact Kähler fourfolds","dir":"Abundance-after-nonvanishing-for-compact-Kahler-fourfolds-September-27-2026","pdf":"paper.pdf","lean":false}]},{"id":"035","t":"Threefold log abundance in numerical dimension one in characteristic p>3","d":"Proves log abundance for projective log canonical threefold pairs over algebraically closed fields of characteristic p>3 when the effective boundary is rational and the ℚ-Cartier adjoint is nef of numerical dimension one. The adjoint is semiample, without requiring the original variety to be terminal or ℚ-factorial.","disc":1,"tier":"C","effort":"S","widget":"Card only: abundance for threefolds in characteristic p>3.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Log abundance in numerical dimension one for threefolds in positive characteristic","dir":"Log-abundance-in-numerical-dimension-one-for-threefolds-in-positive-characteristic-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Abundance in numerical dimension one for terminal threefolds in positive characteristic","dir":"Abundance-in-numerical-dimension-one-for-terminal-threefolds-in-positive-characteristic-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"036","t":"Numerical semiampleness and generalized minimal models","d":"Proves numerical semiampleness for nef adjoints K_(X)+B+M with K_(X)+B pseudo-effective and M nef rational, for projective klt rational pairs over algebraically closed characteristic-zero fields and smooth compact Kähler rational klt simple-normal-crossing pairs, using Bott–Chern cohomology in the latter case. Separately, projective generalized log canonical rational pairs over such fields admit minimal models for pseudo-effective adjoints and Mori fiber spaces otherwise, with nef b-data fixed.","disc":1,"tier":"C","effort":"S","widget":"Text card on minimal model program / semiampleness.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Numerical semiampleness of nef adjoint classes on compact Kähler manifolds","dir":"Numerical-semiampleness-of-nef-adjoint-classes-on-compact-Kahler-manifolds-October-4-2026","pdf":"numerical-generalized-abundance.pdf","lean":false},{"t":"Numerical Semiampleness of Nef Adjoint Divisors","dir":"Numerical-Semiampleness-of-Nef-Adjoint-Divisors-October-3-2026","pdf":"paper.pdf","lean":false},{"t":"Minimal models and Mori fibre spaces for generalized log canonical Q-pairs","dir":"Minimal-models-and-Mori-fibre-spaces-for-generalized-log-canonical-Q-pairs-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Minimal models in numerical dimension one","dir":"Minimal-models-in-numerical-dimension-one-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"037","t":"The sharp ordinary-double-point volume gap","d":"Proves the ordinary-double-point volume-gap conjecture: every singular complex algebraic klt germ of dimension n≥2, with zero boundary, has normalized volume at most 2(n-1)ⁿ. Equality holds precisely for an analytic ordinary double point.","disc":1,"tier":"C","effort":"S","widget":"Text card on normalized volume of klt singularities, with the ordinary double point x1²+...+xₙ₊₁²=0 as the extremal example and the formula 2(n-1)ⁿ tabulated.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The ordinary-double-point gap in every dimension","dir":"The-ordinary-double-point-gap-in-every-dimension-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"The normalized-volume gap in dimension four","dir":"The-normalized-volume-gap-in-dimension-four-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"038","t":"Fujita's freeness conjecture","d":"Proves Fujita's freeness conjecture at its sharp bound in every dimension: for a smooth projective complex variety X of dimension n and an ample line bundle L, the adjoint K_(X)+mL is globally generated for every integer m≥ n+1.","disc":1,"tier":"C","effort":"S","widget":"Text card on adjoint line bundles and global generation.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Fujita's freeness conjecture","dir":"Fujitas-freeness-conjecture-September-23-2026","pdf":"Fujitas-freeness-conjecture-September-23-2026.pdf","lean":false}]},{"id":"039","t":"Nagata's conjecture and maximal Seshadri constants","d":"Proves Nagata's strict inequality ∑ᵢ mᵢ<d√r for every nonzero effective plane curve of degree d through r≥10 very general complex points, with arbitrary multiplicities mᵢ. It also proves maximal multipoint Seshadri constants (Lⁿ/r)^(1/n) for every smooth polarized projective variety of dimension n≥2 and all sufficiently large r: at very general points over ℂ, and at the geometric generic tuple over any algebraically closed field of positive characteristic.","disc":1,"tier":"B","effort":"M","widget":"Explore plane curves of degree d through r general points and compare sum of multiplicities to d*sqrt(r) via expected-dimension counts.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Nagata's conjecture for plane curves","dir":"Nagatas-Conjecture-for-Plane-Curves-September-23-2026","pdf":"main.pdf","lean":true},{"t":"Maximal Seshadri constants on arbitrary polarized surfaces","dir":"Maximal-Seshadri-Constants-on-Arbitrary-Polarized-Surfaces-September-23-2026","pdf":"main.pdf","lean":true},{"t":"Maximal Multipoint Seshadri Constants in Higher Dimensions","dir":"Maximal-Multipoint-Seshadri-Constants-in-Higher-Dimensions-October-5-2026","pdf":"main.pdf","lean":false},{"t":"Maximal multipoint Seshadri constants in positive characteristic","dir":"Maximal-multipoint-Seshadri-constants-in-positive-characteristic-October-5-2026","pdf":"seshadri-positive-characteristic.pdf","lean":false}]},{"id":"040","t":"Bloch's conjecture for complex surfaces","d":"Proves Bloch's conjecture: for every smooth connected projective complex surface S with p_(g)(S)=0, the Albanese map CH₀(S)⁰→Alb(S)(ℂ) on integral degree-zero zero-cycles is an isomorphism. This combines the new p_(g)=q=0 theorem with the classical theorem of Bloch, Kas, and Lieberman.","disc":1,"tier":"C","effort":"S","widget":"Card on zero-cycles on surfaces with p_(g)=0.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Bloch’s conjecture for surfaces with p_g=0","dir":"Blochs-Conjecture-for-Surfaces-with-pg-equals-q-equals-0-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"041","t":"Hyperkähler SYZ and projective-space bases","d":"Proves the strong hyperkähler SYZ conjecture: every holomorphic line bundle with nonzero nef isotropic first Chern class on a compact irreducible holomorphic symplectic Kähler manifold is semiample. It also proves that every projective Lagrangian fibration with normal projective base has projective space as its base, in every dimension and deformation type.","disc":1,"tier":"C","effort":"S","widget":"Card only: SYZ semiampleness and projective-space bases of Lagrangian fibrations.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Projective-space bases of Lagrangian fibrations","dir":"Projective-Space-Bases-of-Lagrangian-Fibrations-September-23-2026","pdf":"main.pdf","lean":false},{"t":"The strong hyperkähler SYZ conjecture","dir":"The-Strong-Hyperkahler-SYZ-Conjecture-September-23-2026","pdf":"main.pdf","lean":false}]},{"id":"042","t":"Oka classification for K3 surfaces and other compact complex surfaces","d":"Proves that every complex K3 surface is Oka, including nonprojective surfaces. More generally, every connected minimal compact complex surface of Kodaira dimension zero is Oka; a connected minimal compact complex surface of class VII is Oka exactly when it is a Hopf or Enoki surface.","disc":1,"tier":"C","effort":"S","widget":"Text card: K3 surfaces are Oka manifolds.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Every complex K3 surface is Oka","dir":"Every-complex-K3-surface-is-Oka-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"043","t":"P=W for fixed-determinant moduli spaces","d":"Proves Pₖ=W₂ₖ=W₂ₖ₊₁ on the full rational cohomology of smooth coprime fixed-determinant, trace-free Higgs moduli spaces and their character varieties for composite ranks over smooth projective complex curves of genus at least two. This includes variant cohomology and, together with the known prime-rank theorems, establishes the fixed-determinant P=W conjecture in every coprime rank.","disc":1,"tier":"C","effort":"S","widget":"Text card on P=W (perverse vs weight filtrations) for Higgs moduli / character varieties.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"P=W in composite rank for fixed determinant","dir":"P-equals-W-in-composite-rank-for-fixed-determinant-September-24-2026","pdf":"P-equals-W-in-composite-rank-for-fixed-determinant-September-24-2026.pdf","lean":false}]},{"id":"044","t":"The equivariant cohomological Hikita conjecture for quivers","d":"Proves the equivariant cohomological Hikita correspondence for every finite quiver, including loops and multiple arrows, with arbitrary dimension and framing vectors and commuting flavor torus. When every semistable point is stable and the gauge action is free, the equivariant cohomology of the Nakajima variety is canonically the coordinate ring of the scheme-theoretic cocharacter-fixed locus of its flavor-deformed Coulomb branch.","disc":1,"tier":"C","effort":"S","widget":"Text card on Nakajima quiver varieties and Coulomb branches (Hikita).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The equivariant cohomological Hikita conjecture for arbitrary quivers","dir":"The-equivariant-cohomological-Hikita-conjecture-for-arbitrary-quivers-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"046","t":"Counterexamples to Shafarevich holomorphic convexity","d":"Constructs a smooth projective complex fourfold with large fundamental group whose universal cover contains no positive-dimensional compact analytic subvariety but is neither Stein nor holomorphically convex. A separate smooth projective complex surface already disproves unrestricted Shafarevich holomorphic convexity in dimension two.","disc":1,"tier":"C","effort":"S","widget":"Text card on universal covers that are neither Stein nor holomorphically convex.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A projective fourfold with large fundamental group and non-Stein universal cover","dir":"A-projective-fourfold-with-large-fundamental-group-and-non-Stein-universal-cover-October-5-2026","pdf":"large-fundamental-group-non-stein.pdf","lean":false},{"t":"A surface counterexample to Shafarevich holomorphic convexity","dir":"A-surface-counterexample-to-Shafarevich-holomorphic-convexity-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"047","t":"Complex counterexamples to cancellation and affine fibrations","d":"Constructs an integral complex affine fourfold X≇𝔸⁴ with X×𝔸¹≅𝔸⁵, disproving affine-space cancellation over ℂ in dimension four. It also disproves the Dolgachev–Weisfeiler affine-fibration conjecture: smooth surjections X→𝔸¹ and 𝔸⁵→𝔸² have every residue-field fiber isomorphic to affine three-space but are not Zariski-locally trivial.","disc":1,"tier":"A","effort":"M","widget":"Show the explicit five-variable polynomial H defining the fourfold X and let the reader step through the polynomial identities that build five coordinates on X x A¹.","related":[],"conj":true,"page":null,"lean":1,"papers":[{"t":"An explicit failure of complex affine-space cancellation","dir":"An-explicit-failure-of-complex-affine-space-cancellation-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"048","t":"A characteristic-zero counterexample to Lipman–Zariski","d":"Constructs a singular normal affine complex surface with free rank-two tangent sheaf, disproving the characteristic-zero Lipman–Zariski conjecture.","disc":1,"tier":"C","effort":"S","widget":"Card only: a singular surface whose tangent sheaf is free, disproving Lipman-Zariski.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A singular normal affine surface with free tangent sheaf","dir":"A-singular-normal-affine-surface-with-free-tangent-sheaf-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"049","t":"A stable-coordinate counterexample in four variables","d":"Constructs a polynomial in four complex variables that is not a coordinate but becomes one after adjoining a single variable, disproving the Stable Coordinate conjecture in four variables. Every fiber is affine three-space, yet none of its embeddings is rectifiable, also disproving the Abhyankar–Sathaye conjecture even when all fibers are affine spaces.","disc":1,"tier":"A","effort":"M","widget":"Inspect the explicit four-variable polynomial f, apply the paper's polynomial coordinate changes step by step, and watch the identities (stable-coordinate relation, determinant identity xy-z(z+1)=p(H+u)) check out symbolically; plot real slices of fibres.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A stable coordinate that is not a coordinate in four variables","dir":"A-stable-coordinate-that-is-not-a-coordinate-in-four-variables-October-5-2026","pdf":"stable-coordinate-four-variables.pdf","lean":false},{"t":"An explicit noncoordinate polynomial with affine three-space zero fibre","dir":"An-explicit-noncoordinate-polynomial-with-affine-three-space-zero-fibre-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"050","t":"A counterexample to Griffiths' positivity conjecture","d":"Constructs ample rank-two bundles on ℙ¹×ℙ¹ with no smooth Hermitian metric of strictly Griffiths-positive curvature, disproving Griffiths' positivity conjecture already on the quadric surface.","disc":1,"tier":"C","effort":"S","widget":"Text card on Griffiths positivity of vector bundles on P1xP1.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Ample rank-two bundles on the quadric surface without Griffiths-positive metrics","dir":"ample-rank-two-bundles-on-the-quadric-surface-without-griffiths-positive-metrics-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"051","t":"Kobayashi's canonical-ampleness conjecture","d":"Every compact connected Kähler manifold of positive complex dimension with no nonconstant entire curve has ample canonical bundle and is therefore projective. This proves Kobayashi's canonical-ampleness conjecture in the smooth compact Kähler setting.","disc":1,"tier":"C","effort":"S","widget":"Text card: hyperbolic Kähler manifolds have ample canonical bundle.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Canonical ampleness of compact hyperbolic Kähler manifolds","dir":"Canonical-ampleness-of-compact-hyperbolic-Kahler-manifolds-September-23-2026","pdf":"canonical-ampleness.pdf","lean":false}]},{"id":"052","t":"Tangent-bundle splittings and universal covers","d":"A splitting of the tangent bundle of a compact Kähler manifold into two integrable holomorphic subbundles induces a compatible product decomposition of its universal cover, proving the two-summand form of Beauville's splitting conjecture. On smooth rationally connected projective manifolds, both summands are automatically integrable, establishing Höring's conjecture and the corresponding product decomposition.","disc":1,"tier":"C","effort":"S","widget":"Text card on tangent-bundle splittings and product universal covers.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Universal-cover splitting for compact Kähler manifolds","dir":"Universal-cover-splitting-for-compact-Kahler-manifolds-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Integrability of split tangent bundles on rationally connected manifolds","dir":"Integrability-of-split-tangent-bundles-on-rationally-connected-manifolds-September-23-2026","pdf":"main.pdf","lean":false}]},{"id":"053","t":"A counterexample to Pixton's original completeness conjecture","d":"Constructs a tautological relation on a moduli space of stable pointed curves that vanishes in rational Chow, hence in rational cohomology, but lies outside Pixton's original relation span. This disproves the Chow and rational-cohomological forms of his original completeness conjecture.","disc":1,"tier":"C","effort":"S","widget":"Card on tautological relations on moduli of curves.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A high-arity counterexample to Pixton completeness in Chow","dir":"A-high-arity-counterexample-to-Pixton-completeness-in-Chow-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"054","t":"Counterexamples to Kuznetsov's rationality conjecture","d":"For every sufficiently large admissible Hassett discriminant, a very general smooth complex cubic fourfold is irrational despite having both an untwisted geometric K3 category and an integral Hodge-theoretic K3 association. This disproves Kuznetsov's rationality conjecture and the sufficiency of the associated-K3 criterion for rationality; the discriminant threshold is ineffective.","disc":1,"tier":"C","effort":"S","widget":"Card only: irrational cubic fourfolds with geometric K3 categories.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Irrational cubic fourfolds with geometric K3 categories","dir":"Irrational-cubic-fourfolds-with-geometric-K3-categories-September-24-2026","pdf":"Irrational-cubic-fourfolds-with-geometric-K3-categories-September-24-2026.pdf","lean":false}]},{"id":"055","t":"Toda's Gepner conjecture and large-volume stability","d":"Proves Toda's Gepner conjecture for every smooth complex quintic threefold, constructing a numerical Bridgeland stability condition with the prescribed phase shift 2/5. Also constructs numerical Bridgeland stability conditions at every sufficiently large volume on all smooth projective complex threefolds with trivial canonical bundle, with the exact ordinary and square-root-Todd central charges.","disc":1,"tier":"C","effort":"S","widget":"Text card on Bridgeland stability on the quintic threefold.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Gepner stability condition on every smooth quintic threefold","dir":"A-Gepner-stability-condition-on-every-smooth-quintic-threefold-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Prescribed large-volume charges on threefolds with trivial canonical bundle","dir":"Prescribed-large-volume-charges-on-threefolds-with-trivial-canonical-bundle-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"056","t":"Termination of fourfold minimal model programs","d":"Proves termination of every existing generalized log canonical flip sequence on globally Weil ℚ-factorial compact Kähler fourfolds, with rational boundary, fixed rational analytically nef b-data, and projective small flip diagrams with the prescribed ample signs. Also proves termination of arbitrary permitted minimal model programs for projective log canonical fourfolds with rational boundary in characteristic zero.","disc":1,"tier":"C","effort":"S","widget":"Text card on minimal model program flips and termination in dimension four.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Termination of generalized log canonical flips on compact Kähler fourfolds","dir":"Termination-of-generalized-log-canonical-flips-on-compact-Kahler-fourfolds-October-5-2026","pdf":"termination-generalized-lc-kahler-fourfolds.pdf","lean":false},{"t":"Termination of generalized-canonical flips on compact Kähler fourfolds","dir":"Termination-of-generalized-canonical-flips-on-compact-Kahler-fourfolds-October-5-2026","pdf":"termination-generalized-terminal-flips-compact-kahler-fourfolds.pdf","lean":false},{"t":"Termination for projective log canonical fourfolds with rational boundary","dir":"Termination-for-projective-log-canonical-fourfolds-with-rational-boundary-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Finite ordinary minimal model programs on compact Kähler fourfolds","dir":"Finite-ordinary-minimal-model-programs-on-compact-Kahler-fourfolds-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Finite ordinary minimal model programs on compact Kähler fourfolds","dir":"Finite-ordinary-minimal-model-programs-on-compact-Kahler-fourfolds-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"057","t":"Campana's abelianity conjecture and special varieties","d":"Proves Campana's abelianity conjecture: special compact Kähler manifolds have virtually abelian fundamental groups. Using this theorem, establishes the same conclusion for order-two root orbifolds of smooth projective complex fourfolds along one nonempty smooth connected divisor, when special in the stated differential-line sense. For smooth special complex quasi-projective varieties, proves that every finite-dimensional complex linear representation of the fundamental group has virtually nilpotent image of class at most two.","disc":1,"tier":"C","effort":"S","widget":"Text card on special varieties and virtually abelian fundamental groups.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The abelianity conjecture for special compact Kähler manifolds","dir":"The-abelianity-conjecture-for-special-compact-Kahler-manifolds-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Two-step monodromy of special quasi-projective varieties","dir":"Two-step-monodromy-of-special-quasi-projective-varieties-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"A conditional abelianity theorem for special fourfold pairs with a half-weight divisor","dir":"A-conditional-abelianity-theorem-for-special-fourfold-pairs-with-a-half-weight-divisor-October-5-2026","pdf":"main.pdf","lean":false}]},{"id":"058","t":"The Kollár–Pardon universal-cover conjecture","d":"Proves the Kollár–Pardon conjecture: the semialgebraic universal covers of connected normal projective complex varieties are exactly products D×ℂᵐ× F, with D bounded symmetric and F simply connected, normal, and projective. A universal cover is quasi-projective exactly when the bounded symmetric factor is absent. In particular, a smooth projective variety covered by ℂⁿ has a finite étale cover by an abelian variety.","disc":1,"tier":"C","effort":"S","widget":"Text card classifying semialgebraic universal covers as D x Cᵐ x F.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Semialgebraic universal covers of normal projective varieties","dir":"Semialgebraic-universal-covers-of-normal-projective-varieties-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Symmetry of semialgebraic bounded domains with compact quotient","dir":"Symmetry-of-semialgebraic-bounded-domains-with-compact-quotient-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"059","t":"Counterexamples to Zariski's multiplicity conjecture","d":"Disproves Zariski's multiplicity conjecture by constructing reduced holomorphic hypersurface germs that are ambiently homeomorphic but have different multiplicities. The examples include hypersurfaces in ℂ⁴ with isolated critical points and multiplicities four and five.","disc":1,"tier":"A","effort":"M","widget":"Show the two explicit weighted-homogeneous germs side by side with their multiplicities and Milnor invariants, plus a 2-variable toy of Milnor fibres.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Ambiently homeomorphic isolated hypersurfaces of multiplicities two and three","dir":"Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Ambiently homeomorphic isolated hypersurface germs in ℂ⁴ with multiplicities four and five","dir":"Ambiently-homeomorphic-isolated-hypersurface-germs-in-C4-with-multiplicities-four-and-five-September-27-2026","pdf":"paper.pdf","lean":false}]},{"id":"060","t":"The Global Spherical Shell conjecture","d":"Every connected minimal compact complex surface of class VII with b₂>0 contains a global spherical shell, proving the positive-b₂ Global Spherical Shell conjecture. Such a shell is a holomorphically embedded neighborhood of the standard three-sphere in ℂ²∖{0} whose complement is connected.","disc":1,"tier":"C","effort":"S","widget":"Card only: global spherical shells on class VII surfaces.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Global Spherical Shells on Minimal Surfaces of Class VII","dir":"Global-Spherical-Shells-on-Minimal-Surfaces-of-Class-VII-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"062","t":"The LeBrun–Salamon conjecture and projective contact classification","d":"Proves the LeBrun–Salamon conjecture: every closed connected positive quaternionic-Kähler manifold of real dimension at least eight is homothetic to a compact symmetric Wolf space. It also proves contact-Fano homogeneity and classifies smooth connected complex projective contact manifolds of complex dimension at least three: those with b₂=1 are adjoint varieties with their canonical contact structures, while those with b₂≥2 have underlying manifold ℙ(T*Z) for a smooth projective variety Z.","disc":1,"tier":"C","effort":"S","widget":"Text card: positive quaternion-Kahler manifolds are symmetric (LeBrun–Salamon).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Contact Fano manifolds and the LeBrun–Salamon conjecture","dir":"Contact-Fano-manifolds-and-the-LeBrun-Salamon-conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"063","t":"The generalized Mukai conjecture","d":"Proves the generalized Mukai conjecture: every positive-dimensional smooth complex projective Fano manifold of dimension n, Picard number ρ and pseudoindex ι satisfies ρ(ι-1)≤ n, with equality exactly for (ℙ^(ι-1))^(ρ). Here the pseudoindex is the least anticanonical degree of a rational curve.","disc":1,"tier":"C","effort":"S","widget":"Text card on Fano manifolds, Picard number and pseudoindex, with products of projective spaces as equality cases.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The generalized Mukai conjecture","dir":"The-Generalized-Mukai-Conjecture-September-24-2026","pdf":"article.pdf","lean":false}]},{"id":"064","t":"The μ-constant problem for surface singularities","d":"Proves topological right-triviality for every holomorphic one-parameter family of isolated hypersurface singularities in ℂ³ with constant Milnor number, resolving the surface case of the μ-constant problem. After shrinking the parameter disk and representatives, ambient homeomorphisms vary jointly continuously, fix the origin section and preserve the defining functions.","disc":1,"tier":"C","effort":"S","widget":"Text card on mu-constant families of surface singularities, perhaps with static images of singular surfaces.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Topological triviality of mu-constant families of surface singularities","dir":"Topological-triviality-of-mu-constant-families-of-surface-singularities-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"065","t":"Virasoro constraints for complete intersections and projective bundles","d":"Proves the full ordinary unreduced descendant Virasoro conjecture for smooth complete intersections in complex projective space, in every genus and curve class with arbitrary cohomology insertions. The constraints also pass from any smooth projective complex base satisfying them to the projectivization of every algebraic vector bundle of rank at least two, and hence to projective-bundle towers.","disc":1,"tier":"C","effort":"S","widget":"Text card on Virasoro constraints in Gromov-Witten theory.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Virasoro Constraints under Projectivization","dir":"Virasoro-Constraints-under-Projectivization-October-5-2026","pdf":"virasoro-constraints-under-projectivization.pdf","lean":false},{"t":"Virasoro Constraints for Projective Complete Intersections","dir":"Virasoro-Constraints-for-Projective-Complete-Intersections-September-24-2026","pdf":"article.pdf","lean":false}]},{"id":"066","t":"Bounded klt complements for Fano contractions","d":"Proves the finite-rational-coefficient form of Shokurov’s bounded-klt-complement conjecture for ε-lc complex Fano-type pairs with nef anti-log-canonical divisor. For ε-lc Fano contractions over any algebraically closed characteristic-zero field, it gives klt complements near every base point, with index bounded only by dimension and positive rational ε.","disc":1,"tier":"C","effort":"S","widget":"Card on bounded complements for Fano contractions.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Bounded klt complements for Fano contractions","dir":"Bounded-klt-complements-for-Fano-contractions-September-25-2026","pdf":"Bounded-klt-complements-for-Fano-contractions-September-25-2026.pdf","lean":false},{"t":"Uniform Cartier sections for Fano type contractions","dir":"Uniform-Cartier-sections-for-Fano-type-contractions-September-25-2026","pdf":"Uniform-Cartier-sections-for-Fano-type-contractions-September-25-2026.pdf","lean":false}]},{"id":"067","t":"The Campana–Peternell conjecture in dimension six","d":"Proves the Campana–Peternell conjecture in complex dimension six: every smooth connected complex projective Fano sixfold with nef tangent bundle is rational homogeneous.","disc":1,"tier":"C","effort":"S","widget":"Card only: Fano sixfolds with nef tangent bundle are homogeneous.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Campana–Peternell conjecture in dimension six","dir":"The-Campana-Peternell-conjecture-in-dimension-six-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"068","t":"Anticanonical nonvanishing under smooth semipositivity","d":"If X is a smooth connected complex projective variety and -K_(X) admits a smooth Hermitian metric with nonnegative curvature, then H⁰(X,-mK_(X))≠0 for some m>0. Thus smooth semipositivity forces a nonzero section of a positive tensor power of the anticanonical bundle in every dimension.","disc":1,"tier":"C","effort":"S","widget":"Text card on anticanonical nonvanishing.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Anticanonical nonvanishing from smooth semipositivity","dir":"Anticanonical-nonvanishing-from-smooth-semipositivity-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Invariant anticanonical indices and conversion of twisted differentials","dir":"Invariant-anticanonical-indices-and-conversion-of-twisted-differentials-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Bounded anticanonical metrics on klt pairs and torus quotients","dir":"Bounded-anticanonical-metrics-on-klt-pairs-and-torus-quotients-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Cohomological transfer and equivariant anticanonical sections","dir":"Cohomological-transfer-and-equivariant-anticanonical-sections-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Metric descent and rank-preserving contractions","dir":"Metric-descent-and-rank-preserving-contractions-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Integrable metrics and effectivity with controlled boundary","dir":"Integrable-metrics-and-effectivity-with-controlled-boundary-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Exact orders and invariant anticanonical linear systems","dir":"Exact-orders-and-invariant-anticanonical-linear-systems-September-26-2026","pdf":"main.pdf","lean":false}]},{"id":"069","t":"Quantum geometric Langlands at irrational level","d":"Proves the unramified de Rham quantum geometric Langlands equivalence for every connected simple complex algebraic group on every smooth projective connected complex curve, at every shifted level c∈ℂ∖ℚ. It identifies the full derived categories of twisted D-modules for the group and its Langlands dual, retaining all global forms and connected components.","disc":1,"tier":"C","effort":"S","widget":"Text card on quantum geometric Langlands.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Global quantum geometric Langlands at irrational level","dir":"Global-quantum-geometric-Langlands-at-irrational-level-October-4-2026","pdf":"quantum-langlands.pdf","lean":false}]},{"id":"071","t":"Koebe's circle-domain conjecture and circle-domain rigidity","d":"Resolves the existence part of Koebe's circle-domain conjecture: every domain in the Riemann sphere is conformally equivalent to a domain whose complementary components are round disks or points. It also proves that circle domains with conformally removable boundary are rigid, meaning every conformal equivalence to another circle domain is Möbius, establishing this direction of the He–Schramm conjecture.","disc":2,"tier":"B","effort":"L","widget":"Draw a multiply-connected domain and watch an iterative conformal map round its holes into disks (finite-connectivity Koebe iteration / circle packing).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Removable Boundaries and Rigidity of Circle Domains","dir":"Removable-Boundaries-and-Rigidity-of-Circle-Domains-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Koebe's Circle-Domain Conjecture","dir":"Koebes-Circle-Domain-Conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"072","t":"Brennan's conjecture and a counterexample to Kraetzer's prediction","d":"Proves Brennan's conjecture: for every conformal bijection φ from a simply connected plane domain onto the disk, |φ'|ˢ is area-integrable for 4/3<s<4. The sharp universal integral-means identity is B_(𝒮)(t)=|t|-1 for t≤-2. A strict bound B_(b)(-1)<1/4 for bounded univalent functions disproves Kraetzer's prediction at that parameter.","disc":2,"tier":"B","effort":"M","widget":"Draw conformal maps of polygonal/fractal domains to the disk and show how integrable |phi'|ˢ is near corners and cusps as s sweeps (4/3,4).","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Brennan's conjecture and sharp inverse-square integral means","dir":"Brennans-conjecture-and-sharp-inverse-square-integral-means-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"A strict inverse-first-power bound for univalent functions","dir":"A-strict-inverse-first-power-bound-for-univalent-functions-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"073","t":"The Falconer distance conjecture","d":"Resolves the Falconer distance conjecture in every dimension d≥2: every compact set E⊂ℝᵈ with Hausdorff dimension greater than d/2 determines a set of Euclidean distances of positive Lebesgue measure.","disc":2,"tier":"B","effort":"M","widget":"Generate fractal (Cantor-type) planar sets of tunable Hausdorff dimension and plot the histogram of their pairwise distances as dimension crosses d/2.","related":["erdos"],"conj":true,"page":null,"lean":1,"papers":[{"t":"The Falconer distance conjecture in all dimensions","dir":"The-Falconer-distance-conjecture-in-all-dimensions-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"074","t":"Kakeya in three and four dimensions","d":"Resolves the Kakeya maximal conjecture in three dimensions and the Hausdorff-dimension conjecture in four. In three dimensions, the radius-δ tube maximal operator maps L³(ℝ³) to L³(S²) with norm O_ε(δ^(-ε)) for every ε>0. In four dimensions, every set containing a unit segment in every direction has Hausdorff dimension four.","disc":2,"tier":"B","effort":"M","widget":"Rotate needles and tubes to build Kakeya sets in 3D/4D and see their volume shrink while the dimension stays full.","related":["kakeya"],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Kakeya maximal conjecture in three dimensions","dir":"The-Kakeya-maximal-conjecture-in-three-dimensions-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Every four-dimensional Kakeya set has full Hausdorff dimension","dir":"Every-four-dimensional-Kakeya-set-has-full-Hausdorff-dimension-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"075","t":"The Llog L Fourier-convergence conjecture","d":"Proves that the ordinary symmetric Fourier partial sums of every complex-valued function in Llog L(𝕋) converge almost everywhere along the full sequence. This resolves the classical sufficiency conjecture at the Llog L scale.","disc":2,"tier":"B","effort":"M","widget":"Draw/choose an L log L function on the circle and animate its Fourier partial sums converging pointwise; compare with Kolmogorov's L¹ divergence phenomenon.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Almost-everywhere Fourier convergence in L log L","dir":"Almost-everywhere-Fourier-convergence-in-L-log-L-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"076","t":"Ultraflat real Littlewood polynomials","d":"Constructs polynomials with N consecutive coefficients in {-1,1} whose modulus is (1+o(1))√N uniformly on the entire unit circle, for every sufficiently large integer length N. Thus real Littlewood polynomials are ultraflat, including at the real endpoints. Their binary merit factors tend to infinity, disproving Turyn's bounded-merit-factor conjecture.","disc":2,"tier":"B","effort":"M","widget":"Drag N and see |P(eⁱᵗ)|/sqrt(N) on the circle for Rudin-Shapiro, random, Legendre/Fekete-shifted and quadratic-phase-rounded +-1 sequences; watch the flatness band and merit factor.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Ultraflat real Littlewood polynomials","dir":"Ultraflat-real-Littlewood-polynomials-October-5-2026","pdf":"ultraflat-real-littlewood-polynomials.pdf","lean":false},{"t":"Nearly minimal maxima and positive minima of Littlewood polynomials","dir":"Nearly-minimal-maxima-and-positive-minima-of-Littlewood-polynomials-October-5-2026","pdf":"littlewood-lower-envelope.pdf","lean":false},{"t":"Asymptotically minimal maxima of real Littlewood polynomials","dir":"Asymptotically-minimal-maxima-of-real-Littlewood-polynomials-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"077","t":"Fourier restriction for positively curved surfaces","d":"Proves the diagonal Fourier extension conjecture for positively curved surfaces in three dimensions. For every compact smooth positively curved surface Σ⊂ℝ³, including surfaces with boundary, the extension operator is bounded from Lᵖ(Σ) to Lᵖ(ℝ³) for every p>3.","disc":2,"tier":"B","effort":"M","widget":"Show the Fourier extension of a function on a sphere/paraboloid cap as a 3D wave field, with sliders for p and the decay of |Ef|.","related":["kakeya"],"conj":true,"page":null,"lean":0,"papers":[{"t":"Elliptic capacity propagation and Fourier restriction to the sphere","dir":"Elliptic-capacity-propagation-and-Fourier-restriction-to-the-sphere-September-24-2026","pdf":"Elliptic-capacity-propagation-and-Fourier-restriction-to-the-sphere-September-24-2026.pdf","lean":false},{"t":"Diagonal Fourier extension for positively curved surfaces in three dimensions","dir":"Diagonal-Fourier-extension-for-positively-curved-surfaces-in-three-dimensions-September-24-2026","pdf":"Diagonal-Fourier-extension-for-positively-curved-surfaces-in-three-dimensions-September-24-2026.pdf","lean":false}]},{"id":"078","t":"The three-dimensional Bochner–Riesz conjecture","d":"Resolves the three-dimensional Bochner–Riesz conjecture in its strict range: the Bochner–Riesz multipliers of order δ are bounded on Lᵖ(ℝ³) for every 1≤ p≤∞ whenever δ>max{3|1/p-1/2|-1/2,0}.","disc":2,"tier":"B","effort":"M","widget":"Render Bochner-Riesz multipliers (1-|xi|²)ᵈelta and their kernels, with an (1/p,delta) diagram showing the newly settled 3D region.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Bochner–Riesz multipliers in three dimensions","dir":"Bochner-Riesz-Multipliers-in-Three-Dimensions-September-24-2026","pdf":"Bochner-Riesz-Multipliers-in-Three-Dimensions-September-24-2026.pdf","lean":false}]},{"id":"079","t":"Sogge's local smoothing conjecture in dimension three","d":"Resolves Sogge's local smoothing conjecture for the Euclidean wave equation in three spatial dimensions. The estimate holds throughout the full strict range 2<p<∞, with Sobolev regularity above max{0,1-3/p}. In particular, the critical L³ estimate holds with every positive Sobolev loss.","disc":2,"tier":"C","effort":"S","widget":"Card (optionally a wave-equation animation) on local smoothing.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Critical local smoothing for the three-dimensional wave equation","dir":"Critical-local-smoothing-for-the-three-dimensional-wave-equation-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"080","t":"The Sobolev endpoint in Carleson's Schrödinger convergence problem","d":"Proves almost-everywhere convergence e^(itΔ)f→ f as t↓0 for every f∈ H^(n/(2(n+1)))(ℝⁿ) and every dimension n≥2. This attains the sharp Sobolev equality case of Carleson's Schrödinger convergence problem, including the planar endpoint H^(1/3).","disc":2,"tier":"B","effort":"M","widget":"Evolve the free Schrodinger equation from rough initial data and watch pointwise convergence (or its failure below the H^(1/3) threshold) as t->0.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Endpoint convergence for the planar Schrodinger equation","dir":"Endpoint-convergence-for-the-planar-Schrodinger-equation-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Endpoint pointwise convergence for the Schrodinger equation in higher dimensions","dir":"Endpoint-pointwise-convergence-for-the-Schrodinger-equation-in-higher-dimensions-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"081","t":"The David–Semmes Riesz-transform problem in higher codimension","d":"Resolves the remaining higher-codimension Riesz-transform rectifiability problem: for d≥4 and 2≤ n≤ d-2, an n-Ahlfors–David regular Radon measure on ℝᵈ is uniformly n-rectifiable whenever its n-dimensional Riesz transform is uniformly L²-bounded over all positive hard truncations. The rectifiability bounds depend only on dimension, regularity and operator bounds.","disc":2,"tier":"C","effort":"S","widget":"Text card on Riesz transforms and uniform rectifiability.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Riesz transforms and uniform rectifiability in higher codimension","dir":"Riesz-transforms-and-uniform-rectifiability-in-higher-codimension-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"082","t":"Maximal and variational bounds for the triangular Hilbert transform","d":"Proves maximal and annular r-variation bounds, for every r>2, from complex L³(ℝ²)× L³(ℝ²) to L^(3/2)(ℝ²). The maximal estimate controls both hard truncation endpoints and gives almost-everywhere and norm convergence. Pairing with a third input settles the triangular Hilbert transform estimate at the symmetric L³× L³× L³ point.","disc":2,"tier":"C","effort":"S","widget":"Text card on the triangular Hilbert transform and multilinear singular integrals.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Annular variation of the triangular Hilbert transform at the symmetric point","dir":"Annular-variation-of-the-triangular-Hilbert-transform-at-the-symmetric-point-October-5-2026","pdf":"annular-variation.pdf","lean":false},{"t":"An L³ bound for the dyadic triangular Hilbert form","dir":"An-L3-bound-for-the-dyadic-triangular-Hilbert-form-October-5-2026","pdf":"dyadic-triangular-hilbert.pdf","lean":false},{"t":"The maximal triangular Hilbert transform at the symmetric point","dir":"The-maximal-triangular-Hilbert-transform-at-the-symmetric-point-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"083","t":"Stein's conjecture for Hilbert transforms along Lipschitz directions","d":"Proves a uniform strong L² bound for the planar Hilbert transform along any Lipschitz unit vector field, at integration lengths bounded by an absolute multiple of its reciprocal Lipschitz constant. The estimate is uniform over inner truncations and yields an L²-bounded principal-value operator, establishing Stein's weak-type conjecture at this short scale.","disc":2,"tier":"C","effort":"S","widget":"Text card with a picture of a Lipschitz direction field and the directional Hilbert transform.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A uniform Hilbert transform estimate for Lipschitz directions","dir":"A-uniform-Hilbert-transform-estimate-for-Lipschitz-directions-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"084","t":"The geometric case of the Erdős similarity conjecture","d":"For every fixed q∈(0,1), constructs compact subsets of [0,1] with measure arbitrarily close to one containing no translated and nontrivially dilated copy of {qⁿ:n≥1}, with dilations of either sign. This resolves the geometric-progression case of the Erdős similarity conjecture for every ratio.","disc":2,"tier":"B","effort":"M","widget":"Pick a ratio q, generate a random periodic set of near-full measure, and search for scaled/translated copies of qⁿ inside it.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The geometric case of the Erdős similarity conjecture","dir":"The-geometric-case-of-the-Erdos-similarity-conjecture-October-5-2026","pdf":"geometric-erdos-similarity.pdf","lean":false},{"t":"The dyadic case of the Erdős similarity conjecture","dir":"The-dyadic-case-of-the-Erdos-similarity-conjecture-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"085","t":"Endpoint regularity of the planar centered maximal function","d":"Resolves the planar centered-disk case of the Hajłasz–Onninen maximal-function regularity problem. For every real f∈ W^(1,1)(ℝ²), the centered disk maximal function satisfies ‖∇ Mf‖₁≤ C‖∇ f‖₁ with an absolute constant. It belongs locally to W^(1,1) and has a globally integrable weak gradient.","disc":2,"tier":"B","effort":"M","widget":"Pick a 2D function, compute its centered-disk maximal function on a grid and compare total variation of Mf vs f.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"An Endpoint Gradient Bound for the Centered Disk Maximal Operator","dir":"An-Endpoint-Gradient-Bound-for-the-Centered-Disk-Maximal-Operator-September-26-2026","pdf":"article.pdf","lean":true}]},{"id":"086","t":"An L³ bound for the trilinear Hilbert transform","d":"Proves that the principal-value trilinear Hilbert transform with shifts x-t, x-2t, x-3t is bounded from L³(ℝ)³ to L¹(ℝ). This resolves the L³ exponent case of the standard conjecture for slopes 1,2,3.","disc":2,"tier":"C","effort":"S","widget":"Card only: L³ bound for the trilinear Hilbert transform with slopes 1,2,3.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An L³ bound for the trilinear Hilbert transform","dir":"An-L3-bound-for-the-trilinear-Hilbert-transform-October-5-2026","pdf":"paper.pdf","lean":false}]},{"id":"087","t":"The Mahler conjectures and symplectic width","d":"Resolves the symmetric and nonsymmetric geometric Mahler conjectures in every dimension, with Hanner polytopes and simplices as the respective volume-product minimizers and all equality cases classified. The corresponding sharp functional Mahler inequalities also hold. For n≥2, every symmetric polar product K× K^(∘) in dimension 2n has Gromov width 4.","disc":3,"tier":"A","effort":"M","widget":"Drag vertices of a centrally symmetric polygon (or pick a 3D body) and see its polar body and the volume product |K||K°| against the Hanner/cube and simplex minima 4ⁿ/n! and (n+1)⁽n+1)/(n!)².","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"The symmetric Mahler conjecture and its equality cases","dir":"The-symmetric-Mahler-conjecture-and-its-equality-cases-September-22-2026","pdf":"paper.pdf","lean":true},{"t":"The Mahler Conjecture for General Convex Bodies","dir":"The-Mahler-Conjecture-for-General-Convex-Bodies-September-22-2026","pdf":"paper.pdf","lean":false},{"t":"Symplectic Balls in Symmetric Polar Products","dir":"Symplectic-Balls-in-Symmetric-Polar-Products-September-22-2026","pdf":"paper.pdf","lean":true}]},{"id":"088","t":"Petty's projection-volume conjecture and simplex counterexamples","d":"Proves Petty's projection-volume conjecture in the remaining dimensions n≥4: ellipsoids uniquely minimize projection-body volume at fixed body volume. Also establishes the full Lutwak–Petty projection inequalities. In contrast, products of simplices exceed Brannen's proposed simplex maximum for normalized projection-body volume by an exponential factor in every sufficiently large dimension.","disc":3,"tier":"A","effort":"S","widget":"Build products of simplices Tᵣ x Tₛ, see their projection bodies (zonotopes) in 2D/3D, and watch the normalized projection-body volume beat the conjectured simplex maximum from dimension 20.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Petty’s projection-volume conjecture in dimensions at least four","dir":"Pettys-projection-volume-conjecture-in-dimensions-at-least-four-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"A product counterexample to the simplex maximum for projection-body volume","dir":"A-product-counterexample-to-the-simplex-maximum-for-projection-body-volume-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"089","t":"Bounded-distortion L₁ embeddings of planar and bounded-treewidth graphs","d":"Resolves the planar and bounded-treewidth cases of the Gupta–Newman–Rabinovich–Sinclair conjecture. Shortest-path metrics of finite connected graphs with arbitrary positive edge lengths embed into real L₁ with universal distortion for planar graphs, and distortion depending only on treewidth for bounded-treewidth graphs. The corresponding multicommodity flow–cut gaps are uniformly bounded.","disc":3,"tier":"B","effort":"L","widget":"Draw a planar graph, compute its shortest-path metric and a cut-metric (L1) embedding via LP on small instances, and show the distortion.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Planar Graph Metrics Embed into L1 with Constant Distortion","dir":"Planar-Graph-Metrics-Embed-into-L1-with-Constant-Distortion-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"L1 Embeddings of Graphs of Bounded Treewidth","dir":"L1-Embeddings-of-Graphs-of-Bounded-Treewidth-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"090","t":"Universal optimality of the triangular lattice","d":"Proves that the triangular lattice minimizes the lower limit of energy per particle for every nonnegative completely monotone potential of squared distance among locally finite planar configurations of centered-disk density one. It also minimizes unit-background renormalized Riesz energies for 0<s<2 and Coulomb energy, resolving Sandier–Serfaty and the two-dimensional Brauchart–Hardin–Saff conjecture on the linear term of optimal spherical logarithmic energy.","disc":3,"tier":"A","effort":"M","widget":"Compare energy per particle of the triangular lattice against square and random planar configurations for Gaussian/Riesz potentials, and replay the finite certificate behind its universal optimality.","related":["viazovska"],"conj":false,"page":null,"lean":0,"papers":[{"t":"An atomic certificate for triangular-lattice universal optimality","dir":"An-atomic-certificate-for-triangular-lattice-universal-optimality-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Universal optimality of the triangular lattice","dir":"Universal-optimality-of-the-triangular-lattice-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"A sharp Fourier certificate for planar circle packing","dir":"A-sharp-Fourier-certificate-for-planar-circle-packing-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Triangular minimality for planar Coulomb renormalized energy","dir":"Triangular-minimality-for-planar-Coulomb-renormalized-energy-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"091","t":"The logarithmic Brunn–Minkowski conjecture","d":"Proves the logarithmic Brunn–Minkowski inequality for origin-symmetric convex bodies in every dimension, and the scalar-dilation B-conjecture for all even log-concave Radon measures. For Lebesgue volume it also proves the additive Lₚ Brunn–Minkowski inequality for full-dimensional origin-symmetric convex bodies throughout 0<p<1.","disc":3,"tier":"B","effort":"M","widget":"For origin-symmetric planar polygons, interpolate K and L by the log-Minkowski combination and plot volume against the inequality.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The logarithmic Brunn–Minkowski conjecture","dir":"The-logarithmic-Brunn-Minkowski-conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"092","t":"The optimal order of convex-body covering density","d":"Determines the optimal worst-case covering density as Θ(nlog n), for both lattice and unrestricted translative coverings. Every convex body in ℝⁿ, n≥2, admits a lattice covering of density at most Cnlog n; centrally symmetric examples in every sufficiently large dimension require at least cnlog n even without the lattice restriction, for absolute c,C>0.","disc":3,"tier":"B","effort":"M","widget":"Cover the plane/space with lattice translates of a convex body and see the covering density; show how n log n arises in high dimension.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A single-lattice covering bound of order n log n","dir":"A-single-lattice-covering-bound-of-order-n-log-n-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Translative covering densities of order n log n","dir":"Translative-covering-densities-of-order-n-log-n-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"093","t":"Dimension-free logarithmic Sobolev inequality for subgaussian log-concave measures","d":"Proves a dimension-free logarithmic Sobolev inequality for centered log-concave densities with uniformly subgaussian linear marginals, with constant bounded by a universal multiple of the squared linear subgaussian parameter.","disc":3,"tier":"C","effort":"S","widget":"Text card on dimension-free log-Sobolev for log-concave measures.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A dimension-free logarithmic Sobolev inequality for subgaussian log-concave measures","dir":"A-dimension-free-logarithmic-Sobolev-inequality-for-subgaussian-log-concave-measures-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"094","t":"Subpolynomial dimension reduction in Lₚ","d":"For every fixed 1<p<∞ and distortion D>1, every n-point subset of real Lₚ embeds into ℓₚᵈ with distortion at most D and dimension d=nᵒ⁽¹⁾, answering Naor's sublinear-dimension question for p≠2. In contrast, exact embeddings require worst-case dimension Θ(n²) when p≠2.","disc":3,"tier":"C","effort":"S","widget":"Text card on metric embeddings of Lₚ point sets into low dimensions.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Subpolynomial dimension reduction in Lp","dir":"Subpolynomial-dimension-reduction-in-Lp-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"095","t":"Hyperbolicity cones without semidefinite lifts","d":"Disproves the Projected Lax conjecture: some hyperbolicity cones are not spectrahedral shadows. The examples admit no exact finite affine semidefinite lift, regardless of the number of auxiliary variables or the real coefficients used. This also disproves the generalized Lax conjecture that every hyperbolicity cone is spectrahedral.","disc":3,"tier":"A","effort":"M","widget":"Explore 2D/3D slices of the degree-20 hyperbolic polynomial in 23 variables: pick a direction, watch all 20 roots stay real, and see the cone boundary.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Hyperbolicity Cones Without Semidefinite Lifts","dir":"Hyperbolicity-Cones-Without-Semidefinite-Lifts-October-5-2026","pdf":"nonliftable-hyperbolicity.pdf","lean":false},{"t":"A nonspectrahedral hyperbolicity cone","dir":"A-Nonspectrahedral-Hyperbolicity-Cone-September-24-2026","pdf":"nonspectrahedral-hyperbolicity-cone.pdf","lean":true},{"t":"An Exact Semidefinite Lift of a Nonspectrahedral Hyperbolicity Cone","dir":"An-Exact-Semidefinite-Lift-of-a-Nonspectrahedral-Hyperbolicity-Cone-October-5-2026","pdf":"Exact-Semidefinite-Lift-of-a-Nonspectrahedral-Hyperbolicity-Cone.pdf","lean":false}]},{"id":"096","t":"The Gaussian propeller conjecture","d":"Proves that the sum of squared Gaussian first moments of any finite measurable partition is at most 9/(8π). In dimension at least two, three planar sectors of angle 2π/3, extended orthogonally, attain the bound. Combined with the separate Unique Games theorem, this proves NP-hardness of improving the loss factor (8π/9)(1-1/k) for identity-target kernel clustering with fixed k≥3 on rational centered positive semidefinite inputs.","disc":3,"tier":"A","effort":"S","widget":"Drag sector boundaries (or paint regions) to partition the Gaussian plane and watch the sum of squared Gaussian first moments, maximized by the 3-blade propeller at 9/(8pi).","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The Gaussian propeller bound in every dimension","dir":"The-Gaussian-Propeller-Bound-in-Every-Dimension-September-24-2026","pdf":"main.pdf","lean":true}]},{"id":"097","t":"The Euclidean Steinitz–Bergström conjecture","d":"Proves that any finite sequence in the Euclidean unit ball of ℝᵈ admits signs keeping every partial sum within C√d, independently of length. Consequently every zero-sum family can be reordered with the same bound on unsigned partial sums. A matching lower bound gives the optimal order S₂(d)=Θ(√d).","disc":3,"tier":"B","effort":"M","widget":"Feed a stream of unit vectors in Rᵈ, choose signs (greedy or user) and watch the signed prefix path stay within a sqrt(d)-radius ball.","related":[],"conj":true,"page":null,"lean":1,"papers":[{"t":"The Euclidean Steinitz–Bergström theorem","dir":"The-Euclidean-Steinitz-Bergstrom-theorem-September-24-2026","pdf":"The-Euclidean-Steinitz-Bergstrom-theorem-September-24-2026.pdf","lean":true}]},{"id":"098","t":"A negative answer to the Lang–Plaut problem","d":"Every infinite-dimensional real Banach space contains a compact doubling set that admits no bi-Lipschitz embedding into any finite-dimensional normed space. The doubling constant is universal. This answers the Lang–Plaut problem negatively, even for compact subsets of Hilbert space.","disc":3,"tier":"C","effort":"S","widget":"Card only: a doubling subset of Hilbert space with no bi-Lipschitz finite-dimensional embedding.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A doubling Hilbert subset with no finite-dimensional bi-Lipschitz embedding","dir":"A-doubling-Hilbert-subset-with-no-finite-dimensional-bi-Lipschitz-embedding-September-25-2026","pdf":"main.pdf","lean":true}]},{"id":"099","t":"The sharp distortion of edit distance into ℓ₁","d":"Determines the least distortion of embedding edit distance on words of length at most d into real ℓ₁: it is exp(Θ(√(log d loglog d))). Insertions, deletions and substitutions have unit cost. The constants are uniform over all finite alphabets with at least two symbols, even when the alphabet grows with d; binary words already force the lower bound.","disc":3,"tier":"B","effort":"M","widget":"Type two binary words, see their edit distance and alignment, and watch a low-dimensional l1 embedding distort distances as word length grows.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Edit Distance in l1: Matching Bounds up to Constants in the Exponent","dir":"Edit-Distance-in-l1-Matching-Bounds-up-to-Constants-in-the-Exponent-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Finite-Circle Obstructions, Binary Codes, and Histogram Embeddings for Edit Distance","dir":"Finite-Circle-Obstructions-Binary-Codes-and-Histogram-Embeddings-for-Edit-Distance-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Tree Constructions for the l1 Distortion of Binary Edit Distance","dir":"Tree-Constructions-for-the-l1-Distortion-of-Binary-Edit-Distance-September-27-2026","pdf":"paper.pdf","lean":false}]},{"id":"100","t":"A counterexample to Bang's cylinder-covering bound","d":"Covers the entire closed regular tetrahedron by finitely many cylinders with compact triangular perpendicular bases whose total area is less than half its smallest orthogonal projection area. This disproves Bang's half-area cylinder-covering bound and the stronger directionwise normalized conjecture in dimension three.","disc":3,"tier":"A","effort":"M","widget":"Spin a regular tetrahedron wrapped in two tilted families of thin triangular cylinders and watch the total base area dip below half the minimal shadow.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Finite angular cylinder covers below the half-area bound","dir":"Finite-angular-cylinder-covers-below-the-half-area-bound-September-27-2026","pdf":"main.pdf","lean":false},{"t":"Finite cylinder approximation of ruled sets","dir":"Finite-cylinder-approximation-of-ruled-sets-September-27-2026","pdf":"main.pdf","lean":false},{"t":"Slope-field perturbations of the two-cylinder covering","dir":"Slope-field-perturbations-of-the-two-cylinder-covering-September-27-2026","pdf":"main.pdf","lean":false},{"t":"Finite triangular approximation of radial sweeps","dir":"Finite-triangular-approximation-of-radial-sweeps-September-27-2026","pdf":"main.pdf","lean":false}]},{"id":"101","t":"The sharp simplex conjecture for isotropic constants","d":"Proves that simplices uniquely maximize the isotropic constant among convex bodies in every dimension, resolving the strong isotropic constant conjecture. Also establishes the sharp entropy lower bound for log-concave probability densities, with equality precisely for invertible affine images of products of one-sided exponential laws.","disc":3,"tier":"A","effort":"M","widget":"Compare isotropic constants of simplex, cube, cross-polytope and random polytopes in dimension n; the simplex always wins.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A sharp entropy bound and the simplex inequality for isotropic constants","dir":"A-sharp-entropy-bound-and-the-simplex-inequality-for-isotropic-constants-October-5-2026","pdf":"isotropic-simplex.pdf","lean":false}]},{"id":"102","t":"The Unique Games Conjecture and optimal approximation thresholds","d":"Proves Khot's Unique Games Conjecture. Independent direct reductions also establish NP-hardness, on unweighted graphs, of approximation beyond the Goemans–Williamson ratio for Max-Cut, below factor two for Vertex Cover, and within any fixed constant factor for Min-UnCut and directed feedback vertex set. These direct proofs use established PCP and Label Cover hardness results.","disc":4,"tier":"B","effort":"M","widget":"Run Goemans-Williamson SDP-style rounding (random hyperplane) on small graphs and show the 0.878 ratio that is now proven optimal.","related":[],"conj":true,"page":null,"lean":3,"papers":[{"t":"The Unique Games Theorem","dir":"The-Unique-Games-Theorem-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"A Direct Proof of Optimal Max-Cut Hardness","dir":"A-Direct-Proof-of-Optimal-Max-Cut-Hardness-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"The Factor-Two Hardness Threshold for Vertex Cover","dir":"The-Factor-Two-Hardness-Threshold-for-Vertex-Cover-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Constant-factor hardness of Min-UnCut","dir":"Constant-factor-hardness-of-Min-UnCut-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Constant-factor hardness of directed feedback vertex set","dir":"Constant-factor-hardness-of-directed-feedback-vertex-set-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"103","t":"Derandomization of logarithmic space: L=RL=BPL","d":"Proves L=RL=BPL, resolving derandomization for bounded-error logarithmic-space computation. An effective compiler converts each randomized polynomial-time logarithmic-space machine deciding a language with one-sided or two-sided error into a deterministic logarithmic-space decider with explicit polynomial running-time bounds.","disc":4,"tier":"C","effort":"S","widget":"Card on derandomizing log-space computation.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Exact derandomization of logarithmic space: L = RL = BPL","dir":"Exact-Derandomization-of-Logarithmic-Space-L-equals-RL-equals-BPL-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"104","t":"Quasipolynomial algorithms for mean-payoff, stochastic and parity games","d":"Gives deterministic algorithms using 2^(O((log(L+2))^2)) bit operations, for complete binary input length L, for ordinary mean-payoff games and two separate extensions. They compute exact values and optimal positional strategies in ordinary games, the nonnegative expectation-of-liminf value set in turn-based stochastic games, and the winning set for nonnegative liminf mean payoff conjoined with parity. Signed rewards, rational chance probabilities, and parity priorities are unrestricted and binary-encoded.","disc":4,"tier":"A","effort":"M","widget":"Build a small mean-payoff (or parity) game graph, run the solver, and see each vertex's winning player and optimal positional strategy.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Turn-Based Stochastic Mean-Payoff Games in Deterministic Quasipolynomial Time","dir":"Turn-Based-Stochastic-Mean-Payoff-Games-in-Deterministic-Quasipolynomial-Time-October-5-2026","pdf":"stochastic-mean-payoff-games.pdf","lean":false},{"t":"Mean-payoff parity games in quasipolynomial time","dir":"Mean-payoff-parity-games-in-quasipolynomial-time-October-5-2026","pdf":"mean-payoff-parity.pdf","lean":false},{"t":"Deterministic quasipolynomial-time mean-payoff games","dir":"Deterministic-quasipolynomial-time-mean-payoff-games-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Randomized quasipolynomial-time mean-payoff games","dir":"Randomized-quasipolynomial-time-mean-payoff-games-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"105","t":"The 2-to-1 Games Conjecture with perfect completeness","d":"Proves Khot's 2-to-1 Games Conjecture with perfect completeness: for every fixed rational δ∈(0,1), it is NP-hard to distinguish satisfiable games from games whose optimum is at most δ, on explicit unweighted instances. The alphabet depends only on δ, and every right-hand label has exactly two preimages under each constraint map.","disc":4,"tier":"C","effort":"S","widget":"Text card on 2-to-1 Games and hardness of approximation.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Perfect completeness for 2-to-1 games","dir":"Perfect-completeness-for-2-to-1-games-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"106","t":"Hardness of coloring three-colorable graphs","d":"It is NP-hard to color a three-colorable graph using any fixed number c≥3 of colors. More strongly, for every fixed 0<δ<1/3, a deterministic polynomial-time reduction from 3SAT produces simple unweighted graphs that are three-colorable in the satisfiable case and have no independent set of size δ n otherwise, where n is the number of vertices.","disc":4,"tier":"B","effort":"M","widget":"Play with the 3SAT-to-graph gadget: satisfiable formulas give 3-colourable graphs, unsatisfiable ones give graphs with no large independent set.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Hardness of finding large independent sets in three-colorable graphs","dir":"Hardness-of-finding-large-independent-sets-in-three-colorable-graphs-September-24-2026","pdf":"Hardness-of-finding-large-independent-sets-in-three-colorable-graphs-September-24-2026.pdf","lean":true}]},{"id":"107","t":"Matrix multiplication with exponent at most 9/4","d":"Proves ω≤9/4 over ℂ, giving O_ε(n^(9/4+ε)) arithmetic operations for square matrix multiplication. In characteristic zero, some inner dimension nᵃ with a>0.465 permits n²⁺ᵒ⁽¹⁾ rectangular multiplication. Further square bounds give ω<2.258 outside finitely many positive characteristics and ω<2.371054886006746 over every fixed field.","disc":4,"tier":"A","effort":"M","widget":"Interactive history of omega (2.81 -> 2.37 -> 9/4), Strassen demo, and the discrete growth argument P(a,3h+a-1)>=3P(a,h) forcing P(a,a)>=a^(4/3), hence omega<=9/4.","related":[],"conj":false,"page":null,"lean":3,"papers":[{"t":"An Upper Bound of 9/4 for the Matrix Multiplication Exponent","dir":"Matrix-Multiplication-Nine-Fourths-October-2-2026","pdf":"paper.pdf","lean":true},{"t":"Complex Matrix Multiplication Below 2.258 and Rectangular Bounds September 24 2026","dir":"Complex-Matrix-Multiplication-Below-2.258-and-Rectangular-Bounds-September-24-2026","pdf":"Complex-Matrix-Multiplication-Below-2.258-and-Rectangular-Bounds-September-24-2026.pdf","lean":true},{"t":"Staggered extraction for exact matrix multiplication over every field","dir":"Staggered-extraction-for-exact-matrix-multiplication-over-every-field-September-24-2026","pdf":"Staggered-extraction-for-exact-matrix-multiplication-over-every-field-September-24-2026.pdf","lean":true}]},{"id":"108","t":"A cubic permanent–determinant lower bound","d":"Proves an Ω(n³) lower bound for the border determinantal complexity of the n× n permanent over ℂ. Even coefficientwise limits of determinants of affine-linear matrices require matrix size at least cn³, for an absolute c>0 and all sufficiently large n; the same bound therefore holds for exact representations.","disc":4,"tier":"C","effort":"S","widget":"Text card on permanent vs determinant and the new cubic border-complexity lower bound.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A cubic lower bound for border determinantal complexity of the permanent","dir":"A-cubic-lower-bound-for-border-determinantal-complexity-of-the-permanent-September-24-2026","pdf":"A-cubic-lower-bound-for-border-determinantal-complexity-of-the-permanent-September-24-2026.pdf","lean":false}]},{"id":"109","t":"Integer multiplication below nlog n","d":"Multiplies two n-bit integers exactly at every input length in deterministic worst-case time O(n(log n)^(1-κ)), with κ=2⁻¹⁸², on one fixed finite-alphabet Turing machine with finitely many one-dimensional tapes. This disproves the Schönhage–Strassen nlog n optimality conjecture in the ordinary multitape bit model.","disc":4,"tier":"B","effort":"M","widget":"Race schoolbook, Karatsuba and FFT multiplication on growing inputs and show where n log n sits.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Integer multiplication below n log n","dir":"Integer-multiplication-below-n-log-n-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"110","t":"Optimal-order randomized k-server on arbitrary metrics","d":"Establishes a randomized competitive ratio O(log²(k+1)) for k-server on every metric space, matching the worst-case lower-bound order. One policy serves every finite oblivious request sequence, including on infinite unbounded metrics. On finite rational metrics, a uniform implementation has polynomial preprocessing and per-request bit cost in the input length and log(t+1) at request t, with a finite instance-dependent additive movement constant.","disc":4,"tier":"B","effort":"M","widget":"Play k-server on a metric (points on a line or plane) against the randomized policy and compare its cost to the offline optimum.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Squared-logarithmic randomized k-server on arbitrary metrics","dir":"Squared-logarithmic-randomized-k-server-on-arbitrary-metrics-September-24-2026","pdf":"Squared-logarithmic-randomized-k-server-on-arbitrary-metrics-September-24-2026.pdf","lean":false},{"t":"Uniform computation of the squared-logarithmic k-server bound","dir":"Uniform-computation-of-the-squared-logarithmic-k-server-bound-September-24-2026","pdf":"Uniform-computation-of-the-squared-logarithmic-k-server-bound-September-24-2026.pdf","lean":false}]},{"id":"111","t":"One-sample matroid prophet inequalities against an almighty adversary","d":"For every finite matroid known in advance, gives a distribution-independent online rule using one independent sample per element and earning a universal constant fraction of the expected offline optimum. Values are independent and nonnegative, with finite expected optimum. The guarantee holds even when the arrival-order adversary sees all samples, values, and the rule's entire random seed; no polynomial-time implementation is asserted.","disc":4,"tier":"B","effort":"M","widget":"Run the one-sample online selection rule on a chosen matroid (graphic, uniform, partition) against adversarial arrival orders and compare earnings with the offline optimum over many trials.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"One Sample Suffices for Matroid Prophet Inequalities against an Almighty Adversary","dir":"One-Sample-Suffices-for-Matroid-Prophet-Inequalities-against-an-Almighty-Adversary-September-23-2026","pdf":"final.pdf","lean":false}]},{"id":"112","t":"Beyond the square-root exponent for depth-three circuits","d":"Constructs a single language in deterministic polynomial time whose n-bit membership function requires 2^(ω(√n)) total gates in unbounded-fan-in OR–AND–OR circuits, at every sufficiently large input length. This crosses the square-root-exponent threshold for explicit depth-three Boolean circuit lower bounds.","disc":4,"tier":"C","effort":"S","widget":"Text card on depth-three circuit lower bounds.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Beyond the Square-Root Exponent for Depth-Three Boolean Circuits","dir":"Beyond-the-Square-Root-Exponent-for-Depth-Three-Boolean-Circuits-September-23-2026","pdf":"main.pdf","lean":true}]},{"id":"113","t":"Approximate counting and the perfect-matching entropy conjecture","d":"Gives a fully polynomial randomized approximation scheme for counting perfect matchings in arbitrary finite simple graphs, with exact detection of zero counts. Also proves the perfect-matching entropy conjecture of Anari, Oveis Gharan, and Vinzant, bounding the maximum entropy of a matching law at every feasible edge-marginal vector in a loopless labelled multigraph, including boundary points.","disc":4,"tier":"B","effort":"M","widget":"Draw a graph, count its perfect matchings exactly (small n) and compare with a Markov-chain approximate count.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A Fully Polynomial Randomized Approximation Scheme for Perfect Matchings in General Graphs","dir":"A-Fully-Polynomial-Randomized-Approximation-Scheme-for-Perfect-Matchings-in-General-Graphs-September-23-2026","pdf":"main.pdf","lean":false},{"t":"Entropy and Face Dimension of the Perfect-Matching Polytope","dir":"Entropy-and-Face-Dimension-of-the-Perfect-Matching-Polytope-September-23-2026","pdf":"main.pdf","lean":true}]},{"id":"114","t":"Approximate counting of common integer polymatroid bases","d":"Gives a fully polynomial randomized approximation scheme for counting common integer bases of two integral polymatroids of equal total rank, supplied by exact rank-value oracles. Capacities are binary-encoded, each integer vector counts once, and oracle calls and bit operations outside the oracles are polynomial on every execution. For matroids presented by independence oracles, the results also cover common independent sets of prescribed, unrestricted, or maximum cardinality, even when the ranks differ.","disc":4,"tier":"B","effort":"M","widget":"Count common bases of two small matroids (e.g. perfect matchings of a bipartite graph) exactly and compare against a Markov-chain sampler estimate.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"An FPRAS for Common Integer Polymatroid Bases with Binary Capacities","dir":"An-FPRAS-for-Common-Integer-Polymatroid-Bases-with-Binary-Capacities-October-5-2026","pdf":"polymatroid-fpras.pdf","lean":false},{"t":"Approximate counting of common bases of two matroids","dir":"Approximate-counting-of-common-bases-of-two-matroids-September-23-2026","pdf":"main.pdf","lean":true}]},{"id":"115","t":"Sampling and counting contingency tables with arbitrary margins","d":"For nonnegative integer matrices with prescribed row and column sums, gives exact uniform sampling in expected polynomial bit time and almost-uniform sampling in worst-case polynomial bit time. The dimensions and binary-encoded margins are unrestricted. Also gives a fully polynomial randomized approximation scheme for counting such tables with arbitrary individual cell bounds, including structural zeros, with polynomial cost on every execution.","disc":4,"tier":"B","effort":"M","widget":"Pick small row/column margins, enumerate all contingency tables exactly and draw uniform samples from them.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Exact Uniform Sampling of Contingency Tables with Arbitrary Margins","dir":"Exact-Uniform-Sampling-of-Contingency-Tables-with-Arbitrary-Margins-September-24-2026","pdf":"main.pdf","lean":false},{"t":"An FPRAS for Cell-Bounded Contingency Tables","dir":"An-FPRAS-for-Cell-Bounded-Contingency-Tables-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"116","t":"Uniform identity testing for noncommutative formulas","d":"For each characteristic, constructs in deterministic polynomial bit time a polynomial-dimensional matrix tuple detecting every nonzero division-free noncommutative formula of bounded size over any field of that characteristic. Rational formulas over ℚ also admit polynomial-size hitting lists whenever they have a defined rational-matrix evaluation.","disc":4,"tier":"A","effort":"M","widget":"Type a small noncommutative formula; the page substitutes the paper's single rational matrix tuple and shows the nonzero matrix that witnesses it.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Uniform Matrix Hitting Points in Every Positive Characteristic","dir":"Uniform-Matrix-Hitting-Points-in-Every-Positive-Characteristic-October-4-2026","pdf":"uniform-matrix-hitting-points-positive-characteristic.pdf","lean":false},{"t":"One Rational Matrix Hitting Point for Noncommutative Formulas","dir":"One-Rational-Matrix-Hitting-Point-for-Noncommutative-Formulas-September-24-2026","pdf":"One-Rational-Matrix-Hitting-Point-for-Noncommutative-Formulas-September-24-2026.pdf","lean":false},{"t":"Polynomial Hitting Lists for Noncommutative Rational Formulas","dir":"Polynomial-Hitting-Lists-for-Noncommutative-Rational-Formulas-September-24-2026","pdf":"Polynomial-Hitting-Lists-for-Noncommutative-Rational-Formulas-September-24-2026.pdf","lean":true}]},{"id":"117","t":"Uniform sparsest cut: hardness and semidefinite gaps","d":"Proves that approximating Uniform Sparsest Cut within any fixed constant factor is NP-hard, even with nonnegative rational capacities and unit demands. The Goemans–Linial semidefinite relaxation also has integrality gaps of order at least √(log n)/(loglog n)³, approaching the square-root-logarithmic upper bound.","disc":4,"tier":"B","effort":"M","widget":"Brute-force the sparsest cut of small graphs and compare with the SDP/spectral relaxation value.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Constant-factor hardness of uniform sparsest cut","dir":"Constant-factor-hardness-of-uniform-sparsest-cut-September-24-2026","pdf":"Constant-factor-hardness-of-uniform-sparsest-cut-September-24-2026.pdf","lean":false},{"t":"Near-square-root logarithmic integrality gaps for uniform sparsest cut","dir":"Near-square-root-logarithmic-integrality-gaps-for-uniform-sparsest-cut-September-24-2026","pdf":"Near-square-root-logarithmic-integrality-gaps-for-uniform-sparsest-cut-September-24-2026.pdf","lean":true}]},{"id":"118","t":"Unbounded bin-packing gaps and the modified integer round-up conjecture","d":"Disproves the modified integer round-up conjecture of Scheithauer and Terno: the integral bin-packing optimum can exceed its configuration linear-programming value by an arbitrarily large additive constant. Approximating the optimum within any fixed additive constant is also NP-hard, even when every item exceeds 1/6 and each bin holds at most five items.","disc":4,"tier":"B","effort":"M","widget":"Drag items into bins and compare the integer optimum to the configuration-LP value on small instances, showing the integrality gap the paper makes unbounded.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Additive hardness and unbounded configuration gaps in bin packing","dir":"Additive-hardness-and-unbounded-configuration-gaps-in-bin-packing-September-24-2026","pdf":"Additive-hardness-and-unbounded-configuration-gaps-in-bin-packing-September-24-2026.pdf","lean":true}]},{"id":"119","t":"The Courtade–Kumar and Hellinger conjectures","d":"Proves the Courtade–Kumar conjecture: among Boolean functions of independent uniform bits, a single coordinate retains the most mutual information after independent bit-flip noise. A stronger theorem treats randomized binary summaries at fixed initial information. The Hellinger conjecture is also proved for every Boolean output bias and noise correlation.","disc":4,"tier":"A","effort":"S","widget":"Flip noisy bits through a Boolean function of your choice and compare the mutual information it retains with a dictator; brute-force all functions on n<=4 bits.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Sharp binary-information contraction on the discrete cube","dir":"Sharp-binary-information-contraction-on-the-discrete-cube-September-24-2026","pdf":"main.pdf","lean":true},{"t":"Hellinger contraction with arbitrary Boolean output bias","dir":"Hellinger-contraction-with-arbitrary-Boolean-output-bias-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"120","t":"Almost-linear-time exact matching in general graphs","d":"Gives a randomized algorithm finding an exact maximum-cardinality matching in any simple undirected graph in (n+m)¹⁺ᵒ⁽¹⁾ word time, with success probability at least 2/3. The time bound holds on every computation path. The same guarantees apply to finding a spanning subgraph with prescribed admissible vertex degrees, or deciding that none exists.","disc":4,"tier":"B","effort":"M","widget":"Animate augmenting-path matching on general graphs (blossoms) and show near-linear scaling claims on random graphs.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Almost-Linear-Time Maximum-Cardinality Matching in General Graphs","dir":"Almost-Linear-Time-Maximum-Cardinality-Matching-in-Sparse-General-Graphs-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"121","t":"Almost-linear expected-time approximation of edit distance","d":"For every fixed rational ε∈(0,1), gives a randomized (1+ε) approximation to unit-cost edit distance in worst-case expected time N¹⁺ᵒ⁽¹⁾, with success probability at least 2/3. The strings have total length N and polynomially bounded integer symbols. This is an asymptotic guarantee at fixed accuracy.","disc":4,"tier":"B","effort":"S","widget":"Type two strings, see the exact edit-distance DP grid and a coarse approximate estimate.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"An Almost-Linear Approximation Scheme for Edit Distance","dir":"An-Almost-Linear-Approximation-Scheme-for-Edit-Distance-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"122","t":"Superpolynomial lower bounds and quasipolynomial reconstruction from deletion traces","d":"At every fixed deletion probability in (0,1), reconstructing an arbitrary length-n binary string requires n^(Ω(loglog n)) independent traces, ruling out polynomial-sample reconstruction. A uniform decoder achieves quasipolynomial sample and running-time bounds for known fixed rational retention probabilities. When the deletion probability is at most n^(-ε) for fixed ε>0, both bounds become polynomial in the input and parameter encoding.","disc":4,"tier":"B","effort":"S","widget":"Send a binary string through a deletion channel, see the traces, and try reconstruction as the trace count grows.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Uniform quasipolynomial-time trace reconstruction","dir":"Uniform-quasipolynomial-time-trace-reconstruction-October-5-2026","pdf":"uniform-trace-reconstruction.pdf","lean":false},{"t":"A latest-anchor induction with spectrally compact masks for worst-case trace reconstruction","dir":"A-latest-anchor-induction-with-spectrally-compact-masks-for-worst-case-trace-reconstruction-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Quantitative lower bounds for trace reconstruction","dir":"quantitative-lower-bounds-for-trace-reconstruction-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"124","t":"Polynomial-time scheduling on three identical machines","d":"Resolves the three-processor unit-job scheduling problem of Garey and Johnson: a deterministic polynomial-time algorithm minimizes makespan for nonpreemptive unit-length jobs with arbitrary precedence constraints on three identical parallel machines. For an explicitly given precedence graph, it decides deadline feasibility exactly and constructs a feasible schedule.","disc":4,"tier":"B","effort":"L","widget":"Draw a precedence DAG of unit jobs and see optimal 3-machine schedules found by exhaustive search, versus greedy list scheduling and Coffman–Graham.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Polynomial-Time Algorithm for Three-Machine Unit-Job Scheduling","dir":"A-polynomial-time-algorithm-for-three-machine-unit-job-scheduling-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"125","t":"The approximation threshold for metric k-median","d":"Gives a deterministic polynomial-time (1+2/e+ε)-approximation for finite rational metric k-median with specified candidate facilities, for every fixed ε>0. Assuming P≠ NP, the optimal infimum approximation factor is 1+2/e.","disc":4,"tier":"B","effort":"M","widget":"Place points and facilities and run greedy/local-search k-median, showing the 1+2/e 1.736 threshold line against achieved ratios.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Single-exponential recovery and bounded-price strictness for metric k-median","dir":"Single-Exponential-Recovery-and-Bounded-Price-Strictness-for-Metric-k-Median-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"The approximation threshold for metric k-median","dir":"The-Approximation-Threshold-for-Metric-k-Median-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"126","t":"Exponential semidefinite complexity of perfect matching","d":"Proves that every exact semidefinite lift of the perfect matching polytope has exponential size, answering Rothvoss's polynomial-size lift question negatively. The bound holds even for the positive semidefinite rank of its odd-cut slack matrix after any fixed shift 0<ρ<1, allowing arbitrary real positive semidefinite factors.","disc":4,"tier":"C","effort":"S","widget":"Text card on positive semidefinite rank and extension complexity of the matching polytope.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Exponential PSD rank of positively shifted matching matrices","dir":"Exponential-PSD-rank-of-positively-shifted-matching-matrices-October-5-2026","pdf":"shifted-matching-psd.pdf","lean":false}]},{"id":"127","t":"The asymptotic Gotsman–Linial conjecture","d":"Proves that a degree-at-most-d polynomial threshold function on the uniform n-dimensional Boolean cube has average sensitivity at most 8d√n, uniformly for 1≤ d≤ n. Average sensitivity counts expected output changes under single-bit flips. This establishes the asymptotic Gotsman–Linial conjecture, allowing polynomial zeros with sign(0)=1.","disc":4,"tier":"B","effort":"S","widget":"Build degree-d polynomial threshold functions on small cubes, compute exact average sensitivity, and plot against 8d*sqrt(n).","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Average sensitivity of polynomial threshold functions","dir":"Average-Sensitivity-of-Polynomial-Threshold-Functions-September-25-2026","pdf":"main.pdf","lean":true}]},{"id":"128","t":"A factor-two approximation for shortest common superstring","d":"Gives a deterministic polynomial-time algorithm constructing a common superstring of length at most twice the optimum for every finite family of explicitly represented strings. The running time is polynomial in the full encoded input length, including symbol labels.","disc":4,"tier":"A","effort":"L","widget":"Enter a handful of strings, run the paper's algorithm and the brute-force optimum, and show the output superstring is at most twice optimal.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A Polynomial-Time 2-Approximation for Shortest Common Superstring","dir":"A-Polynomial-Time-2-Approximation-for-Shortest-Common-Superstring-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"129","t":"Exponential state costs for two-way automata","d":"Proves exponential lower bounds both for complementing two-way nondeterministic finite automata and for simulating one-way nondeterministic automata by two-way deterministic ones. The latter resolves the Sakoda–Sipser state-succinctness conjecture over growing finite alphabets; both results rule out polynomial state bounds independent of alphabet size.","disc":4,"tier":"B","effort":"M","widget":"Run small two-way automata on words (e.g. the h+3 state automaton for one-way liveness) and watch the head move back and forth.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"An exponential state lower bound for two-way nondeterministic complementation","dir":"An-exponential-state-lower-bound-for-two-way-nondeterministic-complementation-September-25-2026","pdf":"paper.pdf","lean":true},{"t":"An exponential two-way deterministic state lower bound for one-way liveness","dir":"An-exponential-two-way-deterministic-state-lower-bound-for-one-way-liveness-September-25-2026","pdf":"main.pdf","lean":true}]},{"id":"130","t":"Fourier transforms below nlog n","d":"Gives a deterministic length-n discrete Fourier transform algorithm using O(n(log n)^(1-δ)) operations for every n, with explicit δ=10⁻¹³. The model uses exact complex arithmetic, unrestricted coefficients and a supplied root of unity, and counts scalar preparation and logarithmic-word indexing.","disc":4,"tier":"C","effort":"S","widget":"Text card: DFT in o(n log n) operations with delta=1e-13.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"An explicit power saving for the exact discrete Fourier transform","dir":"An-explicit-power-saving-for-the-exact-discrete-Fourier-transform-September-25-2026","pdf":"main.pdf","lean":false},{"t":"Finite tensor savings and exact Fourier circuits","dir":"Finite-tensor-savings-and-exact-Fourier-circuits-September-25-2026","pdf":"main.pdf","lean":true}]},{"id":"131","t":"Polynomial mixing of graph switches with prescribed degrees","d":"Resolves the simple-undirected Kannan–Tetali–Vempala conjecture: the lazy edge-switch chain mixes in O(n⁸) time for every graphical labeled degree sequence. The same degree-constrained graphs can also be sampled exactly uniformly by an almost-surely terminating algorithm with expected polynomial bit running time.","disc":4,"tier":"B","effort":"S","widget":"Run the edge-switch Markov chain on graphs with a chosen degree sequence and watch statistics mix.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Polynomial mixing of the switch chain for every graphical degree sequence","dir":"Polynomial-Mixing-of-the-Switch-Chain-for-Every-Graphical-Degree-Sequence-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"132","t":"A counterexample to the quadratic sensitivity conjecture","d":"Constructs total Boolean functions with block sensitivity bs(f)≥ s(f)^(α) for a fixed α>2, disproving the quadratic strengthening of the Sensitivity Conjecture. Here s(f) counts influential individual-bit flips, while block sensitivity allows disjoint groups of bits to change together.","disc":4,"tier":"B","effort":"M","widget":"Build Boolean functions and compute sensitivity vs block sensitivity on small examples, showing the composition mechanism that amplifies a gap.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A superquadratic separation between sensitivity and block sensitivity","dir":"A-superquadratic-separation-between-sensitivity-and-block-sensitivity-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"133","t":"The complexity of Weisfeiler–Leman refinement","d":"Proves unconditional n^(Ω(k)) deterministic time lower bounds for joint and separate k-dimensional Weisfeiler–Leman equivalence, for sufficiently large fixed k in the specified sequential adjacency-matrix models. With dimension as input, joint equivalence is EXPTIME-complete even on subcubic graphs; deciding whether refinement identifies a graph is also EXPTIME-complete.","disc":4,"tier":"B","effort":"M","widget":"Run k-dimensional Weisfeiler-Leman colour refinement on CFI-style graph pairs and watch it fail to tell them apart until k grows.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Parity lifts and bounded-treewidth witnesses for Weisfeiler–Leman equivalence","dir":"Parity-lifts-and-bounded-treewidth-witnesses-for-Weisfeiler-Leman-equivalence-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"The complexity of identifying a graph by Weisfeiler–Leman refinement","dir":"The-complexity-of-identifying-a-graph-by-Weisfeiler-Leman-refinement-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Unconditional time lower bounds for Weisfeiler–Leman equivalence","dir":"Unconditional-time-lower-bounds-for-Weisfeiler-Leman-equivalence-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Variable-dimension Weisfeiler–Leman equivalence on general and subcubic graphs","dir":"Variable-dimension-Weisfeiler-Leman-equivalence-on-general-and-subcubic-graphs-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"134","t":"Generalized star height at most three","d":"Every regular language over a finite alphabet has a generalized regular expression with at most three nested Kleene stars, allowing union, concatenation and complement over the same alphabet. This establishes an absolute bound independent of automaton size, resolving the uniform-boundedness version of the generalized star-height problem.","disc":4,"tier":"C","effort":"S","widget":"Card explaining regular expressions with complement and the star-height bound of three.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Finite Monoid Computations and a Uniform Generalized Star-Height Bound","dir":"Finite-Monoid-Computations-and-a-Uniform-Generalized-Star-Height-Bound-September-25-2026","pdf":"Finite-Monoid-Computations-and-a-Uniform-Generalized-Star-Height-Bound-September-25-2026.pdf","lean":false},{"t":"Generalized Star Height at Most Four","dir":"Generalized-Star-Height-at-Most-Four-September-25-2026","pdf":"Generalized-Star-Height-at-Most-Four-September-25-2026.pdf","lean":false},{"t":"Generalized Star Height at Most Three","dir":"Generalized-Star-Height-at-Most-Three-September-25-2026","pdf":"article.pdf","lean":false}]},{"id":"135","t":"Sharp homogeneous depth-five complexity of matrix products","d":"Over every characteristic-zero field, the (1,1) entry of a product of n independent n× n variable matrices requires n^(Θ(√n)) gates in homogeneous depth-five sum–product circuits. This sharp bound allows shared gates and bottom linear forms involving all variables.","disc":4,"tier":"C","effort":"S","widget":"Card only: depth-five circuit lower bounds for iterated matrix multiplication.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Homogeneous depth-five lower bounds for iterated matrix multiplication","dir":"Homogeneous-depth-five-lower-bounds-for-iterated-matrix-multiplication-September-25-2026","pdf":"Homogeneous-depth-five-lower-bounds-for-iterated-matrix-multiplication-September-25-2026.pdf","lean":false}]},{"id":"136","t":"The quasilinear PCP-for-PPAD conjecture","d":"Resolves the quasilinear PCP-for-PPAD conjecture. An End-of-Line instance of length N reduces to numerical circuit constraints of total length N(log N)^(O(1)) such that any polynomially encoded rational assignment satisfying all but a fixed fraction to fixed accuracy yields an endpoint solution. Such assignments always exist, giving robust local verification with only quasilinear size overhead.","disc":4,"tier":"C","effort":"S","widget":"Text card on PCP-for-PPAD.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The PCP-for-PPAD conjecture: a quasilinear reduction","dir":"The-PCP-for-PPAD-conjecture-a-quasilinear-reduction-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"137","t":"One-tape time simulation in two-fifths-power space","d":"Determines the halting and finite-control outcome of a fixed deterministic one-writable-tape machine up to time T using O(T^(2/5)log^(C)(T+2)) space, improving the square-root exponent. Heads move at most one cell per step; finitely many read-only input heads are allowed. Initial contents are independent of T, and contents and input symbols have polylogarithmic-space access. Simulation time is unrestricted.","disc":4,"tier":"C","effort":"S","widget":"Text card on time-space simulation of one-tape Turing machines.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Simulating One-Tape Time in Two-Fifths-Power Space","dir":"Simulating-One-Tape-Time-in-Two-Fifths-Power-Space-September-25-2026","pdf":"article.pdf","lean":false}]},{"id":"138","t":"Subset Sum in O(2^(0.49n)) time","d":"Gives a uniform randomized classical algorithm for worst-case Subset Sum in ordinary O(2^(0.49n)) word-RAM time on polynomial-bit inputs, where n counts the integers. The time bound holds on every execution and success probability is at least 2/3 on every input. Inputs may repeat positive integers; words have O(n+b) bits for maximum input bit length b.","disc":4,"tier":"B","effort":"M","widget":"Run meet-in-the-middle subset sum on small instances and plot the 2^(n/2) vs 2^(0.49n) cost curves.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Subset Sum in Time O(2^(0.49n)) ","dir":"Subset-Sum-in-Time-2-power-0-49n-October-4-2026","pdf":"subset-sum.pdf","lean":false},{"t":"A Low-Space Algorithm for Worst-Case Subset Sum","dir":"A-Low-Space-Algorithm-for-Worst-Case-Subset-Sum-September-26-2026","pdf":"paper.pdf","lean":false}]},{"id":"139","t":"Subpolynomial queries for log-concave sampling","d":"For C² potentials with a supplied minimizer and I⪯∇²V⪯2I, proves that sampling within total variation 1/10 requires only C_ε d^(ε) exact value-and-gradient queries for every fixed ε>0. The bound holds on every run, with unrestricted computation between queries. A logarithmic lower bound also holds, so the optimal power-law exponent in this oracle model is zero.","disc":4,"tier":"B","effort":"M","widget":"Compare Langevin-type samplers on 2D well-conditioned log-concave densities and count gradient queries to reach a target TV distance.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Subpolynomial query complexity for well-conditioned log-concave sampling","dir":"Subpolynomial-query-complexity-for-well-conditioned-log-concave-sampling-September-26-2026","pdf":"article.pdf","lean":true}]},{"id":"140","t":"Memory–sample lower bounds for noiseless Gaussian regression","d":"For fixed A>0, a one-pass learner with Ad² persistent bits needs Ω_(A)(dlog(1/ε)) noiseless Gaussian samples to recover a unit vector to angular error 0<ε≤1/10 with probability 2/3, uniformly in accuracy for large d. Computation and randomized updates are unrestricted, but output uses only the terminal state, stopping index and fresh randomness.","disc":4,"tier":"C","effort":"S","widget":"Card on memory versus sample trade-offs in learning.","related":[],"conj":false,"page":null,"lean":5,"papers":[{"t":"Memory and precision in noiseless Gaussian regression","dir":"Memory-and-precision-in-noiseless-Gaussian-regression-September-27-2026","pdf":"paper.pdf","lean":true},{"t":"Posterior replicas and conditional information in Gaussian regression","dir":"Posterior-replicas-and-conditional-information-in-Gaussian-regression-September-27-2026","pdf":"paper.pdf","lean":true},{"t":"Localization costs and information growth for exact Gaussian observations","dir":"Localization-costs-and-information-growth-for-exact-Gaussian-observations-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Projection moments, positive cap domination, and Riesz estimates on the sphere","dir":"Projection-moments-positive-cap-domination-and-Riesz-estimates-on-the-sphere-September-27-2026","pdf":"paper.pdf","lean":true},{"t":"Replacing Gaussian observations in memory-constrained inference","dir":"Replacing-Gaussian-observations-in-memory-constrained-inference-September-27-2026","pdf":"paper.pdf","lean":true},{"t":"Subsphere methods for memory-sample lower bounds in noiseless Gaussian regression","dir":"Subsphere-methods-for-memory-sample-lower-bounds-in-noiseless-Gaussian-regression-September-27-2026","pdf":"paper.pdf","lean":true}]},{"id":"141","t":"The existential theory of the reals and existential–universal sentences in the counting hierarchy","d":"Proves that the existential theory of the reals lies in the counting hierarchy. More generally, truth of existential–universal real sentences can be decided at one fixed level of that hierarchy, even when their integer polynomials are specified by arithmetic circuits.","disc":4,"tier":"C","effort":"S","widget":"Card only: the existential theory of the reals lies in the counting hierarchy.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Existential–universal real sentences in the counting hierarchy","dir":"Existential-universal-real-sentences-in-the-counting-hierarchy-October-4-2026","pdf":"etr-counting-hierarchy.pdf","lean":false}]},{"id":"142","t":"Deterministic polynomial factorization over prime fields","d":"Gives a uniform deterministic algorithm that completely factors every nonzero dense degree-n polynomial over a prime field 𝔽ₚ, including multiplicities, in bit complexity polynomial in (n+1)log p. The prime is supplied in binary. No randomness, integer-factorization or primitive-root oracle, or GRH assumption is required.","disc":4,"tier":"B","effort":"L","widget":"Factor polynomials over Fₚ in the browser and step through the deterministic splitting stages.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Deterministic Polynomial Factorization over Prime Fields","dir":"Deterministic-Polynomial-Factorization-over-Prime-Fields-October-4-2026","pdf":"Deterministic-Polynomial-Factorization-over-Prime-Fields.pdf","lean":false}]},{"id":"143","t":"Uniform limit-cycle bounds in Hilbert's sixteenth problem","d":"Resolves the uniform boundedness assertion in Hilbert's sixteenth problem: the number of isolated periodic orbits of a real planar polynomial vector field is bounded by a finite constant depending only on its degree. For classical quintic Liénard systems, the exact maximum is two limit cycles.","disc":5,"tier":"B","effort":"M","widget":"Draw a planar polynomial vector field (Lienard x'=y-F(x), y'=-x with quintic F), integrate orbits, and find limit cycles via the Poincare return map; see at most two for quintic Lienard.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Uniform bounds for planar polynomial limit cycles","dir":"uniform-bounds-for-planar-polynomial-limit-cycles-September-24-2026","pdf":"uniform-bounds-for-planar-polynomial-limit-cycles-September-24-2026.pdf","lean":false},{"t":"Two limit cycles for quintic Liénard systems","dir":"two-limit-cycles-for-quintic-lienard-systems-September-24-2026","pdf":"two-limit-cycles-for-quintic-lienard-systems-September-24-2026.pdf","lean":true}]},{"id":"144","t":"Banach's simple Lebesgue-spectrum problem","d":"Resolves the probability-preserving form of Banach's simple Lebesgue-spectrum problem within smooth dynamics. A smooth volume-preserving diffeomorphism of the standard-volume three-torus has simple Lebesgue spectrum on its entire complex mean-zero L² space: the bilateral iterates of one real observable form an orthonormal basis of that space.","disc":5,"tier":"C","effort":"S","widget":"Text card on simple Lebesgue spectrum, maybe animating an Anosov–Katok style torus map.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A smooth three-torus diffeomorphism with simple Lebesgue spectrum","dir":"A-smooth-three-torus-diffeomorphism-with-simple-Lebesgue-spectrum-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"145","t":"Rokhlin's multiple-mixing problem","d":"Proves that every invertible mixing probability-preserving transformation is mixing of all finite orders, resolving Rokhlin's multiple-mixing problem for a single transformation. Correlations among any finite collection of measurable sets converge to the product of their measures whenever all pairwise time separations diverge.","disc":5,"tier":"B","effort":"M","widget":"Visualize correlations of 2- and 3-fold set intersections under a mixing map (e.g. a cat map/shift) decaying to product measure.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Rokhlin's multiple-mixing problem for one transformation","dir":"Rokhlins-multiple-mixing-problem-for-one-transformation-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"146","t":"Sinai's positive-entropy conjecture for the standard map","d":"Proves that the standard sine map on the two-dimensional torus has positive metric entropy with respect to area for every sufficiently large positive parameter. This establishes Sinai's positive-parameter-measure conjecture for the original family, with the stronger conclusion of a full parameter tail.","disc":5,"tier":"B","effort":"S","widget":"Iterate the Chirikov standard map at large K, show the phase portrait and running Lyapunov exponent estimates.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Positive Metric Entropy for the Standard Map at Large Parameters","dir":"Positive-Metric-Entropy-for-the-Standard-Map-at-Large-Parameters-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"147","t":"The near-boundary Birkhoff conjecture","d":"Resolves the near-boundary Birkhoff conjecture for smooth strictly convex planar billiards of positive curvature. Such a billiard is an ellipse whenever a full grazing annulus is continuously foliated by individually invariant essential curves. A continuous physical collar of smooth closed convex caustics also suffices.","disc":5,"tier":"B","effort":"M","widget":"Play billiards in convex tables, see the caustic curves, and compare an ellipse with perturbed tables whose near-boundary caustics break up.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Continuous Phase Foliations Create Analytic Caustic Collars","dir":"Continuous-Phase-Foliations-Create-Analytic-Caustic-Collars-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Rigidity of Smooth Billiards with a Continuous Caustic Collar","dir":"Rigidity-of-Smooth-Billiards-with-a-Continuous-Caustic-Collar-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"148","t":"The dimension formula for self-similar measures on the line","d":"For every self-similar measure on the line generated by finitely many contracting similarities, proves dim_(H)μ=min{1,h_(RW)/χ}, where h_(RW) is the entropy rate of random composed maps and χ the average logarithmic contraction. This resolves the entropy-rate dimension conjecture without a separation assumption, allowing exact overlaps and unequal contraction ratios.","disc":5,"tier":"B","effort":"M","widget":"Choose contraction ratios and translations for an IFS on the line, render the self-similar measure histogram, and estimate h_(R)W/chi versus box-counting dimension.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The entropy-rate dimension formula for self-similar measures on the line","dir":"The-entropy-rate-dimension-formula-for-self-similar-measures-on-the-line-September-24-2026","pdf":"main.pdf","lean":true}]},{"id":"149","t":"Permanence for weakly reversible reaction networks","d":"Proves the permanence conjecture for every finite weakly reversible mass-action system with fixed positive rate constants. Every positive stoichiometric compatibility class, even an unbounded one, has a common compact convex forward-invariant absorbing set. All positive trajectories in that class therefore eventually share positive lower and finite upper concentration bounds.","disc":5,"tier":"B","effort":"M","widget":"Simulate weakly reversible mass-action networks (pick a reaction graph and rates) and watch trajectories enter a common compact absorbing box.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Uniform Permanence in Weakly Reversible Mass-Action Systems","dir":"Uniform-Permanence-in-Weakly-Reversible-Mass-Action-Systems-October-5-2026","pdf":"permanence.pdf","lean":false},{"t":"Boundedness and persistence of weakly reversible mass-action systems","dir":"Boundedness-and-persistence-of-weakly-reversible-mass-action-systems-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"150","t":"Weak mixing of irrational triangular billiards","d":"Proves that the billiard flow in every nondegenerate Euclidean triangle with at least one angle irrational relative to π is weakly mixing for normalized area times uniform direction. This strengthens ergodicity on the entire irrational-angle class, with no genericity or Diophantine restrictions.","disc":5,"tier":"B","effort":"S","widget":"Shoot billiard trajectories in a triangle with an irrational angle and watch phase-space orbits fill and decorrelate.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Weak mixing of triangular billiards with an irrational angle","dir":"Weak-mixing-of-triangular-billiards-with-an-irrational-angle-October-5-2026","pdf":"weak-mixing-triangular-billiards.pdf","lean":false},{"t":"Ergodicity of triangular billiards with an irrational angle","dir":"Ergodicity-of-triangular-billiards-with-an-irrational-angle-September-25-2026","pdf":"Ergodicity-of-triangular-billiards-with-an-irrational-angle-September-25-2026.pdf","lean":false}]},{"id":"151","t":"A C¹ counterexample to Shub’s entropy conjecture","d":"Constructs a noninvertible C¹ self-map of a compact smooth manifold with zero topological entropy but eigenvalue 2 on second homology. This disproves the homological entropy lower bound for general C¹ self-maps: homological growth need not force positive orbit complexity.","disc":5,"tier":"C","effort":"S","widget":"Text card: a smooth map can stretch homology without generating any entropy.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A C^1 Counterexample to the Entropy Conjecture","dir":"A-C1-Counterexample-to-the-Entropy-Conjecture-September-25-2026","pdf":"article.pdf","lean":false}]},{"id":"152","t":"Zero entropy does not guarantee a smooth positive-volume model","d":"Constructs a zero-entropy ergodic invertible transformation of a standard nonatomic probability space that is not measurably conjugate to any C^(∞) diffeomorphism preserving a strictly positive smooth probability density on a compact finite-dimensional manifold. One example rules out every finite dimension.","disc":5,"tier":"C","effort":"S","widget":"Card on smooth realizability of ergodic systems.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A zero-entropy system without a smooth positive-volume model","dir":"A-finite-entropy-system-without-a-smooth-positive-volume-model-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"153","t":"Arithmetic classification of Bernoulli convolutions","d":"Classifies singular and absolutely continuous unbiased Bernoulli convolutions for every λ∈(0,1) by an infinite, one-sided approximation condition using explicit finite sets of algebraic units. It also proves singularity at reciprocals of every quartic Salem number in (1,2), giving examples beyond reciprocal Pisot parameters.","disc":5,"tier":"A","effort":"M","widget":"Slide lambda and watch the Bernoulli convolution (the law of sum of +/-lambdaⁿ) form a smooth or singular density; highlight the certified degree-31 non-Pisot singular parameter.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Arithmetic classification and non-Pisot singularity for Bernoulli convolutions","dir":"Arithmetic-classification-and-non-Pisot-singularity-for-Bernoulli-convolutions-October-3-2026","pdf":"paper.pdf","lean":false}]},{"id":"154","t":"Pointwise multiple ergodic averages for mixing transformations","d":"Proves almost-everywhere convergence of consecutive multiple ergodic averages of every finite length for invertible mixing probability-preserving transformations. For each fixed tuple of bounded functions, the limit is the product of their integrals, along all positive averaging lengths. No mixing rate or standardness assumption on the probability space is required.","disc":5,"tier":"B","effort":"M","widget":"Pick a mixing map (e.g. a toral automorphism or Bernoulli shift) and functions, and watch multiple ergodic averages converge to the product of integrals.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Pointwise Multiple Ergodic Averages for Mixing Transformations","dir":"Pointwise-Multiple-Ergodic-Averages-for-Mixing-Transformations-October-4-2026","pdf":"multiple-ergodic-averages.pdf","lean":false},{"t":"Pointwise convergence of fourfold ergodic averages for mixing transformations","dir":"Pointwise-convergence-of-fourfold-ergodic-averages-for-mixing-transformations-October-4-2026","pdf":"fourfold-ergodic-averages.pdf","lean":false},{"t":"Triple ergodic averages with distinct integer slopes","dir":"Triple-ergodic-averages-with-distinct-integer-slopes-October-4-2026","pdf":"triple-ergodic-distinct-slopes.pdf","lean":false},{"t":"Pointwise convergence of triple ergodic averages for mixing transformations","dir":"Pointwise-convergence-of-triple-ergodic-averages-for-mixing-transformations-October-4-2026","pdf":"pointwise-triple-ergodic-averages-mixing-transformations.pdf","lean":false}]},{"id":"155","t":"A counterexample to periodic tiling in dimension three","d":"Constructs a finite translational tile in ℤ³ that tiles space but admits no fully periodic tiling, disproving the periodic tiling conjecture in the smallest possible lattice dimension. Its unit-cube thickening gives the same counterexample in ℝ³, even with arbitrary real translation vectors.","disc":6,"tier":"B","effort":"L","widget":"Explore the Sudoku-style encoding behind a 3D translational tile with no periodic tiling: small-scale versions of the word rule and stacking layers.","related":["chair44"],"conj":false,"page":null,"lean":1,"papers":[{"t":"A translational tile with no fully periodic tiling in dimension three","dir":"A-translational-tile-with-no-fully-periodic-tiling-in-dimension-three-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"156","t":"Borsuk's conjecture fails in dimension nine","d":"Constructs a compact subset of ℝ⁹ that cannot be covered by ten sets of strictly smaller diameter, disproving Borsuk's covering assertion already in dimension nine. The example consists of rank-one orthogonal projectors onto lines in ℝ⁴, with the Frobenius metric.","disc":6,"tier":"B","effort":"M","widget":"Explore lines in R⁴ as projectors in 9D: pick two lines and see they are at diameter sqrt2 exactly when orthogonal; try to colour RP³ with 10 labels and watch orthogonal pairs collide.","related":["borsuk"],"conj":true,"page":null,"lean":1,"papers":[{"t":"A nine-dimensional counterexample to Borsuk's covering assertion","dir":"A-nine-dimensional-counterexample-to-Borsuks-covering-assertion-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"157","t":"Counterexamples to the Hadwiger and Colin de Verdière conjectures","d":"Disproves Hadwiger's conjecture even for fractional coloring: arbitrarily large finite simple graphs with independence number at most two satisfy χ_(f)(G)>h(G), where h(G) is the largest clique-minor order. Also disproves the fractional Colin de Verdière chromatic bound χ_(f)(G)≤μ(G)+1. In the positive direction, every finite nonempty graph satisfies χ_(list)(G)≤ C h(G) for a universal constant C.","disc":6,"tier":"B","effort":"M","widget":"Explore small graphs with independence number <=2, computing fractional chromatic number and clique-minor order side by side.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"A counterexample to Hadwiger's conjecture","dir":"A-counterexample-to-Hadwigers-conjecture-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"A counterexample to the Colin de Verdière chromatic conjecture","dir":"A-counterexample-to-the-Colin-de-Verdiere-chromatic-conjecture-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"A linear list-coloring bound in terms of the Hadwiger number","dir":"A-linear-list-coloring-bound-in-terms-of-the-Hadwiger-number-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"158","t":"The Euclidean plane cannot be colored with five colors","d":"Proves that every five-coloring of the Euclidean plane has a monochromatic pair at distance one, with no restriction on the color classes. This advances the Hadwiger–Nelson problem: together with the classical seven-coloring, only six and seven remain possible chromatic numbers of the plane.","disc":6,"tier":"B","effort":"M","widget":"Try to 5-colour patches of the plane and get shown monochromatic unit pairs; context on the 4->5->6 history.","related":["hadwiger"],"conj":true,"page":null,"lean":1,"papers":[{"t":"The Euclidean plane is not five-colorable","dir":"The-Euclidean-plane-is-not-five-colorable-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"159","t":"Erdős's reciprocal-sum conjecture and quasipolynomial Szemerédi bounds","d":"Proves Erdős's conjecture that every set of positive integers with divergent reciprocal sum contains arithmetic progressions of every finite length. Quantitatively, for each fixed k≥3, every subset of {1,…,N} with no nonconstant k-term progression has size at most CₖNexp[-cₖ(log N)^(εₖ)], with positive constants depending only on k.","disc":6,"tier":"B","effort":"M","widget":"Build AP-free subsets of 1..N (greedy, Behrend-type) and compare their sizes with the new quasipolynomial bound; check divergent-reciprocal-sum sets for long APs.","related":["capset"],"conj":false,"page":null,"lean":0,"papers":[{"t":"Quasipolynomial Bounds for Arithmetic Progressions","dir":"Quasipolynomial-Bounds-for-Arithmetic-Progressions-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"160","t":"Superexponential van der Waerden numbers","d":"Resolves Erdős's superexponential-growth question for van der Waerden numbers. If Wᵣ(k) is the least interval length forcing a monochromatic k-term progression in every r-coloring, then Wᵣ(k)>k^(ck⌊log₂ r⌋) for an absolute c>0, all r≥2 and sufficiently large k, uniformly in r. In particular, Wᵣ(k)^(1/k)→∞ for each fixed r.","disc":6,"tier":"B","effort":"M","widget":"Colour 1..N by hand or by search and find the first monochromatic k-term progression; tabulate known small van der Waerden numbers vs. the superexponential lower bound.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Quantitative Superexponential Bounds for van der Waerden Numbers","dir":"Quantitative-Superexponential-Bounds-for-van-der-Waerden-Numbers-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"161","t":"Counterexamples to Sidorenko's conjecture and the forcing conjecture","d":"Disproves Sidorenko's conjecture with a connected bipartite pattern on 35 vertices and 66 edges that occurs less frequently than in a random graph of the same edge density. The same pattern disproves the forcing conjecture of Skokan and Thoma: matching its density and the edge density of a constant graphon need not force quasirandomness.","disc":6,"tier":"A","effort":"M","widget":"Inspect the explicit 13-point, 22-triangle complex H (35-vertex, 66-edge bipartite pattern) that breaks Sidorenko's conjecture, and see why each pair lying in exactly two faces creates a sign correlation.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"A counterexample to Sidorenko's conjecture","dir":"A-counterexample-to-Sidorenkos-conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"162","t":"Counterexamples to Ryser's covering and Gyárfás's tree-cover conjectures","d":"Disproves Ryser's covering conjecture by constructing intersecting (q+1)-partite, (q+1)-uniform hypergraphs with covering number q+1, rather than the predicted bound q, for every sufficiently large prime q. A separate construction over extension fields also disproves Gyárfás's monochromatic tree-cover conjecture.","disc":6,"tier":"B","effort":"M","widget":"Visualize intersecting (q+1)-partite hypergraphs from projective planes and the covering vs matching numbers for small q.","related":[],"conj":true,"page":null,"lean":1,"papers":[{"t":"Balanced counterexamples to Ryser's conjecture at prime orders","dir":"Balanced-Counterexamples-to-Rysers-Conjecture-at-Prime-Orders-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"A counterexample to Ryser's covering conjecture","dir":"A-Counterexample-to-Rysers-Covering-Conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"164","t":"Hindman's finite sums and products conjecture","d":"Proves Hindman's finite sums and products conjecture: every finite coloring of the positive integers contains sets of any prescribed finite size whose nonempty subset sums and nonempty subset products all have one common color.","disc":6,"tier":"B","effort":"M","widget":"Colour 1..N with k colours and search for small sets whose subset sums and products share a colour.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Monochromatic finite sums and products in the positive integers","dir":"Monochromatic-finite-sums-and-products-in-the-positive-integers-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"165","t":"Exact crossing numbers of complete and complete bipartite graphs","d":"Resolves the Harary–Hill conjecture and Turán's brickyard problem in the Zarankiewicz formulation, determining the crossing numbers of every complete and complete bipartite graph. The result proves the optimality of the classical drawings among all plane drawings with continuous edge arcs.","disc":6,"tier":"A","effort":"S","widget":"Draw Kₙ in the paper's own two-page drawing and Kₘ,n in Zarankiewicz's, count crossings exactly, try to beat them by hand, and run an exhaustive search of every two-page drawing up to K₁₁.","related":[],"conj":true,"page":"crossing/","lean":2,"papers":[{"t":"The crossing number of complete graphs","dir":"The-crossing-number-of-complete-graphs-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"The crossing number of complete bipartite graphs","dir":"The-crossing-number-of-complete-bipartite-graphs-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"166","t":"The higher-dimensional Erdős distinct-distances conjecture","d":"For every fixed d≥3, any n≥2 distinct points in ℝᵈ determine at least c_(d)n^(2/d) distinct distances, with c_(d)>0 depending only on dimension. This matches the integer-grid order and resolves the higher-dimensional Erdős distinct-distances conjecture with a constant-factor bound.","disc":6,"tier":"B","effort":"S","widget":"Place points in 3D and count distinct distances, comparing grids with the c_(d) n^(2/d) lower bound.","related":["erdos"],"conj":false,"page":null,"lean":0,"papers":[{"t":"The higher-dimensional Erdős distinct-distances conjecture","dir":"The-higher-dimensional-Erdos-distinct-distances-conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"167","t":"Pinned distances and a power saving for planar unit distances","d":"Proves the weak pinned Erdős distance conjecture: for every fixed ε>0, all but o(n) points of any n-point planar set determine at least n^(1-ε) distinct nonzero distances. A complementary theorem bounds the number of unit-distance pairs by O(n^(4/3-δ)) for an absolute δ>0.","disc":6,"tier":"B","effort":"S","widget":"Place n points and count, for each pin, its distinct distances; histogram of pinned-distance counts and unit-distance pairs for lattice-like sets.","related":["erdos","guthkatz","szemeredi-trotter"],"conj":false,"page":null,"lean":1,"papers":[{"t":"The weak pinned planar distance theorem","dir":"The-weak-pinned-planar-distance-theorem-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"A power saving for planar unit distances","dir":"A-power-saving-for-planar-unit-distances-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"168","t":"Combinatorial invariance of Kazhdan–Lusztig polynomials","d":"Resolves the full combinatorial invariance conjecture: isomorphic Bruhat intervals in arbitrary Coxeter systems have identical equal-parameter Kazhdan–Lusztig polynomials. Thus the abstract order of the interval determines the polynomial, even across different Coxeter systems.","disc":6,"tier":"A","effort":"M","widget":"Pick two Bruhat intervals in small Weyl groups (S4, S5, B3, H3...) and see their Hasse diagrams; isomorphic posets always carry the same Kazhdan-Lusztig polynomial.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Combinatorial invariance of Kazhdan–Lusztig polynomials","dir":"Combinatorial-Invariance-of-Kazhdan-Lusztig-Polynomials-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"169","t":"The Shareshian–Wachs e-positivity conjecture","d":"Resolves the elementary-positivity part of the Shareshian–Wachs conjecture: the chromatic quasisymmetric function of every natural unit interval graph has elementary-basis coefficients in ℕ[q]. The coefficients count explicitly described permutations, giving a combinatorial explanation of positivity.","disc":6,"tier":"A","effort":"M","widget":"Pick a unit interval graph (Dyck path) and see its chromatic quasisymmetric function expanded in the e-basis with q-coefficients, each a count of explicit permutations.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Elementary positivity of chromatic quasisymmetric functions","dir":"Elementary-Positivity-of-Chromatic-Quasisymmetric-Functions-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"170","t":"Sharp logarithmic exponents for off-diagonal Ramsey numbers","d":"For every fixed integer s≥5, proves r(s,t)=tˢ⁻¹/(log t)ˢ⁻²⁺ᵒ⁽¹⁾ as t→∞, determining the logarithmic exponent and matching the classical upper bound at that scale. Here r(s,t) is the least number of vertices forcing an s-clique or a t-vertex independent set.","disc":6,"tier":"C","effort":"S","widget":"Text card on r(s,t) asymptotics with the sharp log exponent.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The sharp logarithmic exponent of r(5,t)","dir":"The-Sharp-Logarithmic-Exponent-of-r-5-t-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Sharp logarithmic exponents for fixed off-diagonal Ramsey numbers","dir":"Sharp-Logarithmic-Exponents-for-Fixed-Off-Diagonal-Ramsey-Numbers-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"171","t":"The hypercube Ramsey conjecture","d":"Resolves the Burr–Erdős hypercube Ramsey conjecture: the two-color Ramsey number of the n-dimensional cube is Θ(2ⁿ). Thus every red-blue coloring of a complete graph on a universal constant times the cube's number of vertices contains a monochromatic copy of the cube.","disc":6,"tier":"B","effort":"M","widget":"Colour a complete graph red/blue and search for monochromatic cubes Q₂, Q₃.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The hypercube Ramsey number has linear order","dir":"The-hypercube-Ramsey-number-has-linear-order-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"172","t":"Classification of finite Euclidean Ramsey configurations","d":"Classifies finite point configurations that occur monochromatically, at their original scale, in every finite coloring of sufficiently high-dimensional Euclidean space. The characterization is an algebraic condition over the coordinate field. It also disproves the Leader–Russell–Walters conjecture that every such configuration is a subset of a finite transitive set.","disc":6,"tier":"A","effort":"S","widget":"See the 12-point 'three concentric squares' configuration on the unit circle and check the tensor/derivation identities that make it non-Ramsey; play with colorings.","related":["hadwiger"],"conj":false,"page":null,"lean":1,"papers":[{"t":"A classification of finite Euclidean Ramsey configurations","dir":"A-classification-of-finite-Euclidean-Ramsey-configurations-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"173","t":"Seymour's second-neighborhood conjecture","d":"Proves Seymour's second-neighborhood conjecture: every nonempty finite oriented graph has a vertex with at least as many vertices at directed distance exactly two as at directed distance one. Oriented graphs may be arbitrary apart from the exclusion of loops and oppositely directed edge pairs.","disc":6,"tier":"A","effort":"S","widget":"Draw any oriented graph (or generate random/tournament-like ones) and the page highlights a vertex whose second out-neighbourhood is at least its first, with both sets shown.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A proof of Seymour’s second-neighborhood conjecture","dir":"A-proof-of-Seymours-second-neighborhood-conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"174","t":"Deterministic construction of strong thin spanning trees","d":"Resolves the strong thin-tree conjecture constructively. Every finite loopless k-edge-connected multigraph on at least two vertices has a spanning tree containing at most a universal C/k fraction of the edges of every cut. Such a tree can be found deterministically in polynomial time, even with binary-encoded parallel-edge multiplicities.","disc":6,"tier":"B","effort":"M","widget":"Pick a k-edge-connected multigraph and find a spanning tree that takes at most a C/k fraction of every cut, with cuts highlighted.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The strong thin tree conjecture","dir":"The-strong-thin-tree-conjecture-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"A polynomial-time construction of strong thin trees","dir":"A-polynomial-time-construction-of-strong-thin-trees-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"175","t":"Talagrand's conjectures and graph decompositions at expectation thresholds","d":"Proves that integral and fractional expectation thresholds differ by at most a universal factor, and resolves Talagrand's discrete-convexity conjecture. An application proves the Ascoli–He–Park–Talagrand graph-decomposition conjecture: every graph's edges split into a universally bounded number of fixed pieces, each with containment threshold at most a universal constant times the original graph's integral expectation threshold. The pieces' embeddings need not agree on shared vertices.","disc":6,"tier":"C","effort":"S","widget":"Text card on expectation thresholds and Talagrand's conjectures.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Graph Decompositions at the Integral Expectation Threshold","dir":"Graph-Decompositions-at-the-Integral-Expectation-Threshold-October-5-2026","pdf":"graph-threshold-decompositions.pdf","lean":false},{"t":"Integral and fractional expectation thresholds are equivalent","dir":"Integral-and-fractional-expectation-thresholds-are-equivalent-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Talagrand’s discrete-convexity conjecture","dir":"Talagrands-discrete-convexity-conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"176","t":"The second Kahn–Kalai conjecture","d":"Proves the second Kahn–Kalai conjecture: for every finite simple graph H with h≥1 edges and at most n vertices, its appearance threshold in G(n,p) is at most C p_(E)(n,H)(1+log₂ h), with universal C. Here p_(E) is the least density at which every subgraph of H has expected copy count at least 1/2.","disc":6,"tier":"B","effort":"M","widget":"Pick a small graph H, compute its expectation threshold p_(E)(n,H), and simulate G(n,p) to see when H actually appears.","related":[],"conj":true,"page":null,"lean":1,"papers":[{"t":"The second Kahn–Kalai conjecture","dir":"The-second-Kahn-Kalai-conjecture-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"177","t":"Bounded-degree coboundary expanders in every dimension","d":"Constructs arbitrarily large finite d-dimensional simplicial complexes, for every d≥3, with uniformly bounded vertex degrees and uniform 𝔽₂ coboundary expansion in every degree below d. Together with the known graph and two-dimensional cases, this establishes the existence of such expanders in every positive dimension.","disc":6,"tier":"C","effort":"S","widget":"Card on high-dimensional expanders.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Bounded-degree coboundary expanders in every dimension","dir":"Bounded-degree-coboundary-expanders-in-every-dimension-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"178","t":"Deterministic nonbipartite Ramanujan graphs in every fixed degree","d":"For every fixed d≥3, constructs a simple d-regular nonbipartite Ramanujan graph on every sufficiently large even number n of vertices, with every nonconstant adjacency eigenvalue strictly between -2√(d-1) and 2√(d-1). A deterministic algorithm outputs the full adjacency list in polynomial bit time, with exponent depending on d.","disc":6,"tier":"B","effort":"M","widget":"Generate regular graphs, plot their adjacency spectrum against the Ramanujan window +/-2sqrt(d-1), and check which ones are Ramanujan.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Deterministic nonbipartite Ramanujan graphs in every fixed degree","dir":"Deterministic-nonbipartite-Ramanujan-graphs-in-every-fixed-degree-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"179","t":"The circulant Hadamard conjecture","d":"Proves that real circulant Hadamard matrices exist exactly in orders 1 and 4, resolving the circulant Hadamard conjecture. Together with classical Barker-sequence results, this shows that binary sequences whose nontrivial aperiodic autocorrelations have magnitude at most 1 exist at lengths n>1 exactly when n∈{2,3,4,5,7,11,13}.","disc":6,"tier":"A","effort":"S","widget":"Build a circulant ±1 matrix one row at a time and watch H·Hᵀ, search every order up to 18 and every Barker length up to 44 in the browser, and see which orders survive each classical condition.","related":[],"conj":false,"page":"hadamard/","lean":1,"papers":[{"t":"The circulant Hadamard conjecture","dir":"The-circulant-Hadamard-conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"180","t":"Barnette's Hamiltonian-cycle conjecture","d":"Proves that every finite simple cubic bipartite planar 3-vertex-connected graph has a Hamiltonian cycle, resolving Barnette's conjecture. Equivalently, every three-edge path in a finite simple cubic 3-vertex-connected bipartite Pfaffian graph lies in a Hamiltonian cycle.","disc":6,"tier":"B","effort":"M","widget":"Generate random cubic bipartite planar 3-connected graphs and find a Hamiltonian cycle by search, highlighting it on the planar drawing.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Paired states and Hamiltonian cycles in cubic bipartite planar graphs","dir":"Paired-states-and-Hamiltonian-cycles-in-cubic-bipartite-planar-graphs-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"181","t":"The Erdős–Gallai cycle-decomposition conjecture","d":"Proves that the edges of every finite simple undirected graph on n vertices can be partitioned into at most Cn simple cycles and single edges, for an absolute constant C. This resolves the Erdős–Gallai cycle-decomposition conjecture, bounding the number of pieces linearly even for dense graphs.","disc":6,"tier":"B","effort":"M","widget":"Draw or randomize a graph and watch it decompose into cycles and single edges, counting pieces against n.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A linear cycle-and-edge decomposition of every graph","dir":"A-linear-cycle-and-edge-decomposition-of-every-graph-September-24-2026","pdf":"main.pdf","lean":true}]},{"id":"182","t":"Power savings for polynomial-difference-free sets","d":"For every fixed intersective integer polynomial h of degree k≥2 with positive leading coefficient, proves that a subset of {1,…,N} avoiding nonzero values h(1),h(2),… as differences has size Oₕ(N^(1-cₖ)), with cₖ>0 depending only on degree. Here intersective means having a root modulo every modulus. For prime arguments, a power saving also holds when h has a unit root modulo every modulus, with exponent allowed to depend on h.","disc":6,"tier":"B","effort":"S","widget":"Greedily build subsets of 1..N with no two elements differing by a square (or h(n)), and plot their size against N⁽1-c).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A power saving for intersective polynomial differences with an exponent depending only on the degree","dir":"A-power-saving-for-intersective-polynomial-differences-with-an-exponent-depending-only-on-the-degree-October-5-2026","pdf":"power-saving-intersective-polynomial-differences.pdf","lean":false},{"t":"A Power Saving for Polynomial Differences at Prime Arguments","dir":"A-Power-Saving-for-Polynomial-Differences-at-Prime-Arguments-October-5-2026","pdf":"prime-argument-polynomial-differences.pdf","lean":false},{"t":"A power saving for square-difference-free sets","dir":"A-power-saving-for-square-difference-free-sets-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"183","t":"Power savings for planar halving lines and k-sets","d":"Improves the planar halving-line bound to O(n^(4/3-ε)) for sets with no three collinear and an absolute ε>0. More generally, an n-point set with no three collinear has O(n(k+1)^(1/3-ε₀)) strictly separable k-subsets for 1≤ k≤ n/2, with an absolute ε₀>0. The constants and positive exponents are nonquantitative.","disc":6,"tier":"B","effort":"S","widget":"Drop points in the plane, see every halving line and the k-set counts, plotted against n^(4/3).","related":["szemeredi-trotter"],"conj":false,"page":null,"lean":0,"papers":[{"t":"A power saving for planar halving lines","dir":"A-power-saving-for-planar-halving-lines-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"184","t":"Coloring and independence in graphs with forbidden subgraphs","d":"Proves the Alon–Krivelevich–Sudakov coloring conjecture in correspondence-coloring form: graphs avoiding any fixed subgraph F need O_(F)(Δ/logΔ) colors when their maximum degree Δ is sufficiently large. Also proves the Ajtai–Erdős–Komlós–Szemerédi independence conjecture: for fixed r≥4, every n-vertex Kᵣ-free graph of average degree d≥2 has an independent set of size Ωᵣ(nlog d/d).","disc":6,"tier":"B","effort":"S","widget":"Generate Kᵣ-free graphs and compare greedy colorings and independent sets with the Delta/log Delta and n log d/d bounds.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Correspondence coloring graphs with a forbidden clique","dir":"Correspondence-Coloring-Graphs-with-a-Forbidden-Clique-October-5-2026","pdf":"correspondence-coloring-forbidden-clique.pdf","lean":false},{"t":"A logarithmic independence bound for clique-free graphs","dir":"A-Logarithmic-Independence-Bound-for-Clique-Free-Graphs-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"185","t":"Counterexamples to infinite matroid intersection and packing/covering","d":"Disproves the unrestricted infinite matroid intersection and packing/covering conjectures in ZFC, using two self-dual partitional matroids on a countably infinite ground set. The same examples answer Joó’s partitional-matroid question negatively. They are neither finitary nor cofinitary, so Nash-Williams’ original finitary conjecture remains outside the result.","disc":6,"tier":"C","effort":"S","widget":"Text card on infinite matroid intersection counterexamples.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A Counterexample to the Infinite Matroid Packing/Covering Conjecture","dir":"A-Counterexample-to-the-Infinite-Matroid-Packing-Covering-Conjecture-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"186","t":"The Friedgut–Kalai graph and hypergraph threshold conjectures","d":"Proves the Friedgut–Kalai threshold-width conjectures for graphs and fixed-uniformity hypergraphs. For fixed 0<ε<1/2, every nontrivial increasing relabeling-invariant property crosses from probability ε to 1-ε within width O((log n)⁻²) for graphs and Oᵣ((log n)^(-r/(r-1))) for r-uniform hypergraphs, r≥3. The hypergraph influence bound also applies to nonmonotone properties.","disc":6,"tier":"B","effort":"S","widget":"Slide p for a random graph G(n,p) and watch monotone properties (connectivity, triangle, Hamiltonicity) jump from rare to typical within a window shrinking like (log n)⁻2.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A uniform influence bound for hypergraph properties","dir":"A-uniform-influence-bound-for-hypergraph-properties-October-5-2026","pdf":"hypergraph-influences.pdf","lean":false},{"t":"A Sharp Threshold Bound for Monotone Graph Properties","dir":"A-Sharp-Threshold-Bound-for-Monotone-Graph-Properties-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"187","t":"Snaky in 21 Maker moves","d":"Settles the Snaky achievement problem: Maker can force the six-cell Snaky shape within 21 of its own moves on the initially empty infinite square board. Maker moves first, each player claims one free cell per turn, and translations, rotations and reflections count as wins.","disc":6,"tier":"A","effort":"M","widget":"Play Breaker against the certified Maker strategy on the infinite grid and watch Maker force the six-cell Snaky shape within 21 moves.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Snaky in 21 Maker moves","dir":"Snaky-in-21-Maker-moves-September-25-2026","pdf":"article.pdf","lean":false}]},{"id":"188","t":"The sharp constant in random triangle removal","d":"Starting from the complete graph on n vertices, repeatedly delete a uniformly chosen remaining triangle. The terminal edge count is asymptotic to n^(3/2)/(2√2), with mean-square convergence after normalization by n^(3/2). This proves the triangle case of the Joos–Kühn sharp-constant conjecture.","disc":6,"tier":"B","effort":"S","widget":"Start from Kₙ, delete random triangles until none remain, and compare the leftover edge count to n^(3/2)/(2*sqrt2).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The sharp terminal leave in random triangle removal","dir":"The-Sharp-Terminal-Leave-in-Random-Triangle-Removal-September-25-2026","pdf":"The-Sharp-Terminal-Leave-in-Random-Triangle-Removal-September-25-2026.pdf","lean":false}]},{"id":"189","t":"Exact cycle–clique Ramsey numbers","d":"Proves the Erdős–Faudree–Rousseau–Schelp conjecture: R(Cₘ,Kₙ)=(m-1)(n-1)+1 for every m≥ n≥3, except R(C₃,K₃)=6. This is the exact threshold forcing a red m-cycle or a blue n-clique in every red–blue coloring of a complete graph.","disc":6,"tier":"A","effort":"M","widget":"Pick m,n, see the extremal colouring with no red Cₘ and no blue Kₙ on (m-1)(n-1) vertices, and brute-force small cases like R(C₄,K₃)=7.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Cycle--clique Ramsey numbers","dir":"Cycle-clique-Ramsey-numbers-September-25-2026","pdf":"Cycle-clique-Ramsey-numbers-September-25-2026.pdf","lean":false}]},{"id":"190","t":"Polynomial removal fails for ordered binary matrices","d":"Disproves polynomial ordered binary matrix removal with one fixed 66×66 zero–one pattern. Matrices can require many binary-entry changes to become pattern-free while their copy density is smaller than every proposed polynomial bound in that distance. Copies preserve row and column orders and match both zeros and ones.","disc":6,"tier":"A","effort":"M","widget":"Render the explicit 66x66 pattern H and the tree host matrices Aₕ; highlight ordered copies and the removal distance as depth h grows.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Polynomial removal fails for ordered binary matrices","dir":"Polynomial-removal-fails-for-ordered-binary-matrices-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"191","t":"A power improvement in the Heilbronn triangle problem","d":"For every sufficiently large n, constructs n points in the unit square such that every triangle has area at least n⁻²⁺ᶜ for one absolute c>0. This disproves the conjectured almost-n⁻² upper bound in Heilbronn's triangle problem, which asks how large the smallest determined triangle can be.","disc":6,"tier":"B","effort":"M","widget":"Generate point sets by the paper's algebraic/random construction versus random and grid sets and display the smallest triangle area scaled by n².","related":["heilbronn"],"conj":false,"page":null,"lean":0,"papers":[{"t":"A power improvement in the Heilbronn triangle lower bound","dir":"A-power-improvement-in-the-Heilbronn-triangle-lower-bound-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"192","t":"A counterexample to the Gopalan–Servedio conjecture","d":"Disproves the proposed square-root bound relating a Boolean function's linear Fourier coefficients to its polynomial degree. For every C>0, there is a sign-valued Boolean function f with ∑ᵢf̂({i})>C√(deg(f)). Thus its total signed correlation with individual input bits can exceed the proposed bound by an arbitrary factor.","disc":6,"tier":"B","effort":"M","widget":"Toy with Boolean functions on a few bits: compute their degree and sum of linear Fourier coefficients and compare with sqrt(deg) and majority.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Unbounded Violations of the Square-Root Degree Bound","dir":"Unbounded-Violations-of-the-Square-Root-Degree-Bound-September-26-2026","pdf":"Unbounded-Violations-of-the-Square-Root-Degree-Bound-September-26-2026.pdf","lean":false}]},{"id":"193","t":"Serre's intersection-multiplicity conjecture","d":"Proves strict positivity of Serre's intersection multiplicity χ^(R)(M,N) for nonzero finitely generated modules over any regular local ring, provided M⊗_(R) N has finite length and dim M+dim N=dim R. This resolves the positivity conjecture, including ramified mixed characteristic.","disc":7,"tier":"C","effort":"S","widget":"Text card on Serre intersection multiplicities.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Positivity of Serre's Intersection Multiplicity","dir":"Positivity-of-Serres-Intersection-Multiplicity-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"194","t":"Lech's multiplicity conjecture","d":"Proves e(R)≤ e(S) for every flat local homomorphism of nonzero Noetherian local rings, where e is Hilbert–Samuel multiplicity. This resolves Lech's conjecture in every dimension and characteristic.","disc":7,"tier":"C","effort":"S","widget":"Text card on Lech's multiplicity inequality for flat local maps.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Lech's multiplicity conjecture","dir":"Lechs-multiplicity-conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"195","t":"A counterexample to the small Cohen–Macaulay module conjecture","d":"Constructs a three-dimensional complete Noetherian normal local domain over ℂ with no nonzero finitely generated maximal Cohen–Macaulay module. A three-dimensional local domain essentially of finite type over ℂ has the same property, disproving the domain form of the small Cohen–Macaulay module conjecture.","disc":7,"tier":"C","effort":"S","widget":"Card on Cohen-Macaulay modules.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Complete Local Domain without a Small Cohen–Macaulay Module","dir":"A-Complete-Local-Domain-Without-a-Small-Cohen-Macaulay-Module-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"196","t":"A counterexample to Kaplansky's zero-divisor conjecture","d":"Constructs a finitely presented torsion-free group G whose group algebra 𝔽₂[G] has nonzero zero divisors, disproving Kaplansky's zero-divisor conjecture. The group has a finite two-dimensional classifying space.","disc":7,"tier":"C","effort":"S","widget":"Card only: a torsion-free group whose F2 group algebra has zero divisors.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A Torsion-Free Group Algebra with Zero Divisors","dir":"A-Torsion-Free-Group-Algebra-with-Zero-Divisors-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"197","t":"Nonsofic groups and group-ring counterexamples","d":"Constructs a finitely presented torsion-free nonsofic group whose group algebra over 𝔽₂ is not directly finite, disproving Kaplansky's conjecture even without torsion. Companion examples give injective nonsurjective cellular automata on all configurations, refuting Gottschalk's surjunctivity conjecture. Another counterexample is an integral group-ring matrix, invertible over the rational group ring, with Fuglede–Kadison determinant strictly between zero and one, disproving the unrestricted Determinant Conjecture.","disc":7,"tier":"C","effort":"S","widget":"Text card: Kaplansky direct-finiteness and Gottschalk surjunctivity counterexamples via nonsofic groups.","related":[],"conj":false,"page":null,"lean":3,"papers":[{"t":"A Torsion-Free Group Algebra That Is Not Directly Finite","dir":"A-Torsion-Free-Group-Algebra-That-Is-Not-Directly-Finite-October-4-2026","pdf":"direct-finiteness.pdf","lean":false},{"t":"A Counterexample to Kaplansky's Direct-Finiteness Conjecture in Characteristic Two","dir":"A-Counterexample-to-Kaplanskys-Direct-Finiteness-Conjecture-in-Characteristic-Two-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"A Counterexample to the Group-Ring Determinant Conjecture","dir":"A-Counterexample-to-the-Group-Ring-Determinant-Conjecture-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"A Counterexample to Kaplansky's Direct-Finiteness Conjecture in Odd Characteristic","dir":"A-Counterexample-to-Kaplanskys-Direct-Finiteness-Conjecture-in-Odd-Characteristic-September-26-2026","pdf":"paper.pdf","lean":true}]},{"id":"198","t":"A counterexample to the little finitistic-dimension conjecture","d":"Constructs a finite-dimensional complex algebra whose finite-dimensional modules have unbounded finite projective dimensions. This disproves the little finitistic-dimension conjecture.","disc":7,"tier":"C","effort":"S","widget":"Text card on finitistic dimension of finite-dimensional algebras.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"An algebra of infinite little finitistic dimension","dir":"An-algebra-of-infinite-little-finitistic-dimension-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"199","t":"Counterexamples to conjectures of Auslander–Reiten, Tachikawa, and Nakayama","d":"Constructs finite-dimensional algebras over a characteristic-two rational-function field that disprove the Auslander–Reiten and Gorenstein-projective conjectures, and Tachikawa's second conjecture. An associated endomorphism algebra also disproves the classical, generalized and strong Nakayama conjectures, the Auslander–Gorenstein conjecture, and the Wakamatsu tilting conjecture. The counterexamples persist under every extension of the base field.","disc":7,"tier":"C","effort":"S","widget":"Text card showing the eight-simple quiver with relations behind the counterexample.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"An explicit counterexample to the Auslander-Reiten conjecture","dir":"An-explicit-counterexample-to-the-Auslander-Reiten-conjecture-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"A counterexample to Tachikawa's second conjecture","dir":"A-counterexample-to-Tachikawas-second-conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"200","t":"Eisenbud–Green–Harris and lex-plus-powers in characteristic zero","d":"Proves the Eisenbud–Green–Harris and lex-plus-powers conjectures over every characteristic-zero field. Any homogeneous ideal containing a regular sequence, of arbitrary length and degrees at least two, admits a lex-plus-powers ideal with the same Hilbert function and no smaller graded Betti numbers.","disc":7,"tier":"C","effort":"S","widget":"Text card on lex-plus-powers ideals and Betti numbers.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Artinian Lex-Plus-Powers Betti Theorem","dir":"The-Artinian-Lex-Plus-Powers-Betti-Theorem-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Commuting Division-Coefficient Forms and the Artinian Eisenbud--Green--Harris Conjecture","dir":"Commuting-Division-Coefficient-Forms-and-the-Artinian-Eisenbud-Green-Harris-Conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"201","t":"A counterexample to Kurosh's division-ring problem","d":"Constructs a countable characteristic-zero division ring that is algebraic over its center and generated by two elements over that center, but has infinite dimension over it. This answers Kurosh's division-ring problem on local finiteness negatively.","disc":7,"tier":"C","effort":"S","widget":"Card on algebraic division rings.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Counterexample to Kurosh’s Division-Ring Problem","dir":"A-Counterexample-to-Kuroshs-Division-Ring-Problem-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"202","t":"The blockwise Alperin weight conjecture","d":"Proves the numerical blockwise Alperin weight conjecture for every prime and every finite group: the number of irreducible Brauer characters in a block equals the number of conjugacy classes of its weights.","disc":7,"tier":"C","effort":"S","widget":"Card only: blockwise Alperin weight conjecture.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Blockwise Alperin Weight Conjecture","dir":"The-Blockwise-Alperin-Weight-Conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"203","t":"Donovan's conjecture over fields and discrete valuation rings","d":"Proves Donovan's conjecture: over each fixed algebraically closed field of characteristic p, blocks of finite groups with bounded defect-group order have only finitely many Morita-equivalence classes, for every prime p. Also proves the integral form over each fixed complete mixed-characteristic discrete valuation ring with algebraically closed residue field.","disc":7,"tier":"C","effort":"S","widget":"Text card on Donovan's conjecture.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Donovan's Conjecture over Algebraically Closed Fields","dir":"Donovans-Conjecture-over-Algebraic-Closures-of-Prime-Fields-September-24-2026","pdf":"main.pdf","lean":false},{"t":"Integral Donovan Finiteness over Witt Vectors","dir":"Integral-Donovan-Finiteness-over-Witt-Vectors-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"204","t":"Tensor saturation for even spin groups","d":"Proves saturation factor one for Spin(2n), n≥2: for three dominant integral weights whose sum lies in the root lattice, an invariant at any common positive integral dilation already gives an invariant at the original weights. This resolves the type-D part of the simply-laced saturation conjecture.","disc":7,"tier":"C","effort":"S","widget":"Text card on tensor-product saturation for Spin(2n).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Tensor saturation for even spin groups","dir":"Tensor-Saturation-for-Even-Spin-Groups-September-24-2026","pdf":"Tensor-Saturation-for-Even-Spin-Groups-September-24-2026.pdf","lean":false}]},{"id":"205","t":"Saxl's conjecture and universal tensor squares","d":"Proves Saxl's conjecture: the tensor square of every staircase representation contains every irreducible complex representation of the corresponding symmetric group. More generally, every Sₙ with n∉{2,4,9} has an irreducible representation whose tensor square contains all irreducibles.","disc":7,"tier":"A","effort":"M","widget":"Pick a staircase partition and see the tensor square of its Sₙ representation decompose, with every irreducible appearing.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Universal Tensor Squares for Symmetric Groups","dir":"Universal-Tensor-Squares-for-Symmetric-Groups-September-24-2026","pdf":"main.pdf","lean":false},{"t":"A Cyclic Polytabloid Proof of Saxl's Conjecture","dir":"A-Cyclic-Polytabloid-Proof-of-Saxls-Conjecture-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"206","t":"Finite lattice representation: counterexamples and undecidability","d":"Some finite lattices are not congruence lattices of any finite algebra, answering the finite lattice representation problem negatively. Moreover, no algorithm decides whether a finite lattice has such a representation, or whether it is a full subgroup interval of a finite group.","disc":7,"tier":"C","effort":"S","widget":"Text card: some finite lattices are not congruence lattices of any finite algebra, and representability is undecidable.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Finite congruence lattices: characterization and undecidability","dir":"Finite-Congruence-Lattices-Characterization-and-Undecidability-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"A negative solution to the finite lattice representation problem","dir":"A-Negative-Solution-to-the-Finite-Lattice-Representation-Problem-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"207","t":"The ℓ¹-Bass and complex Bass trace conjectures","d":"Proves the ℓ¹-Bass conjecture for every discrete group: Hattori–Stallings traces of idempotent matrices over ℓ¹(G) are supported on finitely many finite-order conjugacy classes. The algebraic companion proves the integral Bass trace conjecture and Kaplansky's idempotent conjecture for torsion-free groups over every commutative unital characteristic-zero domain.","disc":7,"tier":"C","effort":"S","widget":"Card on idempotents in group rings.","related":[],"conj":true,"page":null,"lean":1,"papers":[{"t":"The ℓ¹-Bass Conjecture for Discrete Groups","dir":"The-l1-Bass-Conjecture-for-Discrete-Groups-October-5-2026","pdf":"l1-bass-conjecture.pdf","lean":false},{"t":"The Bass trace conjecture and the characteristic-zero Kaplansky idempotent conjecture","dir":"The-Bass-trace-conjecture-for-complex-group-rings-September-24-2026","pdf":"The-Bass-trace-conjecture-for-complex-group-rings-September-24-2026.pdf","lean":true}]},{"id":"208","t":"The finite Benson–Etingof–Ostrik conjecture","d":"Proves that every finite symmetric tensor category over an algebraically closed field k of characteristic p>0 admits a k-linear exact faithful strong symmetric monoidal fiber functor to a higher Verlinde category Ver_(pⁿ). The level may depend on the category, and the theorem includes characteristic two, resolving the finite case of the Benson–Etingof–Ostrik conjecture.","disc":7,"tier":"C","effort":"S","widget":"Card only: fiber functors to higher Verlinde categories.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Fiber functors for finite symmetric tensor categories in positive characteristic","dir":"Fiber-functors-for-finite-symmetric-tensor-categories-in-positive-characteristic-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"209","t":"Integral counterexamples to Gersten’s conjecture","d":"Disproves unrestricted integral Gersten injectivity in degrees 3 and 5. Two explicit two-dimensional ramified regular local rings of mixed characteristic (0,5) have nonzero integral K-theory classes that vanish over their fraction fields.","disc":7,"tier":"C","effort":"S","widget":"Text card on Gersten counterexamples in K-theory.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An integral counterexample to Gersten's conjecture","dir":"An-Integral-Counterexample-to-Gerstens-Conjecture-September-25-2026","pdf":"An-Integral-Counterexample-to-Gerstens-Conjecture-September-25-2026.pdf","lean":false},{"t":"An integral degree-three Gersten counterexample","dir":"An-Integral-Degree-Three-Gersten-Counterexample-September-26-2026","pdf":"paper.pdf","lean":false}]},{"id":"210","t":"Foulkes’ conjecture for sixth powers and quadratic stabilization","d":"Proves the sixth case of Foulkes’ conjecture: Sym⁶(SymᵇV) embeds equivariantly in Symᵇ(Sym⁶V) for every b≥6 and finite-dimensional complex V. More generally, the canonical multiplication map Symᵇ(SymᵃV)→Symᵃ(SymᵇV) is surjective for a≥2 and b≥ a(a-1), giving dimension-independent quadratic stabilization.","disc":7,"tier":"A","effort":"L","widget":"Compare plethysm multiplicities in Symᵃ(Symᵇ V) and Symᵇ(Symᵃ V) partition by partition for small a,b, seeing the Foulkes inequality hold.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Foulkes' conjecture for the sixth symmetric power","dir":"Foulkes-Conjecture-for-the-Sixth-Symmetric-Power-September-25-2026","pdf":"main.pdf","lean":false},{"t":"Quadratic stabilization of the canonical Foulkes--Howe map","dir":"Quadratic-Stabilization-of-the-Canonical-Foulkes-Howe-Map-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"211","t":"Geometry, diffusion, and spectra of random planar maps","d":"Critical Fortuin–Kasteleyn planar maps converge to Liouville quantum gravity spheres for 0<q≤4 and to the Brownian continuum random tree for q>4, establishing the surface-to-tree geometric transition. For FK–Ising and spanning-tree-weighted maps, stationary random walks converge to Liouville Brownian motion on the limiting sphere. The FK–Ising spectral result also gives convergence of eigenvalues and heat traces, using the stated Brownian/LQG inputs.","disc":8,"tier":"B","effort":"L","widget":"Sample FK-weighted random planar maps (via Sheffield hamburger-cheeseburger bijection) and embed them, sliding q across 4 to see sphere vs tree.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Random Walks on Critical FK–Ising Maps and Liouville Brownian Motion","dir":"Random-Walks-on-Critical-FK-Ising-Maps-and-Liouville-Brownian-Motion-October-5-2026","pdf":"fk-ising-walk-limit.pdf","lean":false},{"t":"Spectral convergence for critical FK–Ising planar maps","dir":"Spectral-convergence-for-critical-FK-Ising-planar-maps-October-5-2026","pdf":"spectral-convergence-critical-fk-ising-planar-maps.pdf","lean":false},{"t":"A Linear Clock for Random Walk on Tree-Weighted Planar Maps","dir":"A-Linear-Clock-for-Random-Walk-on-Tree-Weighted-Planar-Maps-October-5-2026","pdf":"linear-clock-random-walk-tree-weighted-planar-maps.pdf","lean":false},{"t":"Canonical conformal limits of subcritical FK planar maps","dir":"Canonical-conformal-limits-of-subcritical-FK-planar-maps-September-24-2026","pdf":"main.pdf","lean":false},{"t":"The critical Liouville quantum sphere and geometric limits of FK maps at q=4","dir":"The-critical-Liouville-quantum-sphere-and-geometric-limits-of-FK-maps-at-q-equals-4-September-24-2026","pdf":"main.pdf","lean":false},{"t":"Metric-measure limits of subcritical FK and spanning-tree planar maps","dir":"Metric-measure-limits-of-subcritical-FK-and-spanning-tree-planar-maps-September-24-2026","pdf":"main.pdf","lean":false},{"t":"Brownian continuum random tree limits of finite Fortuin–Kasteleyn maps above four","dir":"Brownian-continuum-random-tree-limits-of-finite-Fortuin-Kasteleyn-maps-above-four-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"212","t":"No bigeodesics and smooth limit shapes in planar first-passage percolation","d":"Proves that planar first-passage percolation has no doubly infinite geodesic for iid nonnegative nonatomic edge weights when the minimum of four weights has finite second moment. For exponential weights, the limit shape is strictly convex with C¹ boundary. Differentiability also holds for every Gamma law with positive shape and rate.","disc":8,"tier":"B","effort":"S","widget":"Simulate first-passage percolation on Z² with exponential weights, grow the ball, and show the smooth convex limit shape and coalescing geodesics.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"No bigeodesics in planar first-passage percolation","dir":"No-bigeodesics-in-planar-first-passage-percolation-September-24-2026","pdf":"main.pdf","lean":false},{"t":"Strict convexity and differentiability of the planar exponential first-passage limit shape","dir":"Strict-convexity-and-differentiability-of-the-planar-exponential-first-passage-limit-shape-September-24-2026","pdf":"main.pdf","lean":true}]},{"id":"213","t":"No infinite critical clusters on quasi-transitive graphs","d":"Resolves the Benjamini–Schramm criticality conjecture for bond percolation on every infinite connected locally finite quasi-transitive graph with p_(c)<1: at the critical probability, there is almost surely no infinite cluster. The family also establishes this conclusion for both nearest-neighbor bond and site percolation on ℤ³.","disc":8,"tier":"B","effort":"S","widget":"Simulate bond percolation on Z²/Z³ slices near p_(c) and watch the largest cluster.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Critical bond and site percolation on the cubic lattice","dir":"Critical-bond-and-site-percolation-on-the-cubic-lattice-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"No percolation at criticality on quasi-transitive graphs","dir":"No-percolation-at-criticality-on-quasi-transitive-graphs-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"214","t":"The Benjamini–Schramm nonuniqueness conjecture","d":"Proves p_(c)<p_(u) for Bernoulli bond percolation on every infinite connected locally finite nonamenable quasi-transitive graph, resolving the Benjamini–Schramm nonuniqueness conjecture. Thus there is a nonempty range of probabilities with infinitely many infinite clusters. A stronger operator bound also establishes the critical triangle condition.","disc":8,"tier":"B","effort":"M","widget":"Run bond percolation on a tree-like (nonamenable) graph such as a hyperbolic tiling and see the phase with infinitely many infinite clusters between p_(c) and p_(u).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Nonuniqueness of percolation on nonamenable quasi-transitive graphs","dir":"Nonuniqueness-of-percolation-on-nonamenable-quasi-transitive-graphs-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"215","t":"Massive continuum limits and exact mass asymptotics for planar O(n) models","d":"Constructs the canonical continuum limit of the two-dimensional nearest-neighbor O(3) model: a non-Gaussian local relativistic theory with a unique vacuum and a positive mass gap. For the square-lattice O(4) model, determines the exact leading asymptotic of the full transfer gap, m_(lat)(β)∼32e^(π/4-1/2)√β e^(-πβ). The family also proves exponential spin-correlation decay for two-dimensional nearest-neighbor O(n) models with n≥3 at every positive temperature.","disc":8,"tier":"B","effort":"M","widget":"Run a Monte Carlo O(3)/O(4) spin model on a lattice, measure spin correlation decay, and overlay the exact mass asymptotic 32 e^(pi/4-1/2) sqrt(beta) e^(-pi beta).","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The canonical massive continuum limit of the two-dimensional O(3) model","dir":"The-canonical-massive-continuum-limit-of-the-two-dimensional-O3-model-October-4-2026","pdf":"massive-continuum-o3.pdf","lean":false},{"t":"An Isolated Particle Pole for the Two-Dimensional O(3) Spin Field","dir":"An-Isolated-Particle-Pole-for-the-Two-Dimensional-O3-Spin-Field-October-4-2026","pdf":"o3-particle-pole.pdf","lean":false},{"t":"Exact mass asymptotics for the two-dimensional O(4) lattice model","dir":"Exact-mass-asymptotics-for-the-two-dimensional-O4-lattice-model-October-5-2026","pdf":"exact-mass-o4.pdf","lean":false},{"t":"Sharp mass bounds for the two-dimensional O(4) model","dir":"Sharp-mass-bounds-for-the-two-dimensional-O4-model-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Exponential decay in two-dimensional classical O(n) models","dir":"Exponential-decay-in-two-dimensional-classical-On-models-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"216","t":"Critical logarithmic corrections and BKT scaling for the planar XY model","d":"For the square-lattice nearest-neighbor cosine XY model, proves critical axis correlations C_(β_c)(r)∼ Ar^(-1/4)(log r)^(1/8) and the Berezinskii–Kosterlitz–Thouless essential singularity √(β_(c)-β)logξ(β)→ B, with A,B>0 after the free-box thermodynamic limit. For finite square-symmetric interactions containing nearest neighbors, discrete Gaussian heights converge to Gaussian fields throughout the rough phase, including its threshold, along geometric torus sizes. Critical center-magnetization and spin-field conclusions retain their stated height, renormalization, and field-input assumptions.","disc":8,"tier":"B","effort":"M","widget":"Metropolis/Wolff simulation of the 2D XY model with vortex display; tune beta through the BKT transition and plot correlation decay vs r⁻1/4 (log r)¹/8.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The critical logarithmic correction for the planar XY model","dir":"The-critical-logarithmic-correction-for-the-planar-XY-model-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Critical Center Magnetization in the Planar XY Model","dir":"Critical-Center-Magnetization-in-the-Planar-XY-Model-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"The Critical Spin Field of the Planar XY Model","dir":"The-Critical-Spin-Field-of-the-Planar-XY-Model-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Essential Singularity of the Correlation Length in the Planar XY Model","dir":"Essential-Singularity-of-the-Correlation-Length-in-the-Planar-XY-Model-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"The critical correlation exponent of the planar XY model","dir":"The-critical-correlation-exponent-of-the-planar-XY-model-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"BKT universality for height and planar spin fields","dir":"BKT-universality-for-height-and-planar-spin-fields-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"217","t":"The low-temperature Sherrington–Kirkpatrick fluctuation law","d":"For every fixed inverse temperature β>1, determines the fluctuation scale and limiting law of the zero-field Gaussian Sherrington–Kirkpatrick log partition function. Its variance is asymptotic to c_β n^(1/3), with c_β>0, confirming the predicted n^(1/6) standard-deviation scale. Exact centering and standardization give full-sequence convergence to a uniquely characterized nondegenerate law.","disc":8,"tier":"B","effort":"M","widget":"Sample SK spin-glass instances and plot the fluctuation of log Z against n^(1/6).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The low-temperature Sherrington–Kirkpatrick free-energy limiting law","dir":"The-low-temperature-Sherrington-Kirkpatrick-free-energy-limiting-law-September-24-2026","pdf":"The-low-temperature-Sherrington-Kirkpatrick-free-energy-limiting-law-September-24-2026.pdf","lean":false},{"t":"The low-temperature Sherrington–Kirkpatrick fluctuation scale","dir":"The-low-temperature-Sherrington-Kirkpatrick-fluctuation-scale-September-24-2026","pdf":"The-low-temperature-Sherrington-Kirkpatrick-fluctuation-scale-September-24-2026.pdf","lean":false}]},{"id":"218","t":"Conformal universality for weakly interacting and disordered Ising models","d":"Weak finite-range square-symmetric even multispin perturbations of the square-lattice Ising model preserve critical bulk spin and energy limits; weak square-symmetric contour interactions also yield chordal SLE₃ interface limits. With sufficiently weak iid bond disorder of any fixed bounded nondegenerate mean-zero law, critical spin interfaces converge to the same law in probability over environments.","disc":8,"tier":"B","effort":"M","widget":"Run a critical Ising model with weak multispin or random-bond perturbations and trace domain-wall interfaces that look like SLE₃.","related":["ising"],"conj":false,"page":null,"lean":0,"papers":[{"t":"Quenched SLE₃ limits for general weak random-bond Ising models","dir":"Quenched-SLE3-limits-for-general-weak-random-bond-Ising-models-October-5-2026","pdf":"general-weak-random-bond-ising.pdf","lean":false},{"t":"Quenched SLE₃ Universality for the Weak Random-Bond Ising Model","dir":"Quenched-SLE3-Universality-for-the-Weak-Random-Bond-Ising-Model-October-5-2026","pdf":"quenched-sle3-weak-random-bond-ising.pdf","lean":false},{"t":"Logarithmic Relative Fluctuations in the Weakly Disordered Planar Ising Model","dir":"Logarithmic-Relative-Fluctuations-in-the-Weakly-Disordered-Planar-Ising-Model-October-5-2026","pdf":"critical-relative-second-moment-weak-random-bond-ising.pdf","lean":false},{"t":"Conformal universality of bulk Ising correlations under weak interactions","dir":"Conformal-universality-of-bulk-Ising-correlations-under-weak-interactions-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"SLE3 universality for weak finite-range Ising interactions","dir":"SLE3-universality-for-weak-finite-range-Ising-interactions-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Buffered comparison and stopping-band resolution in critical Ising","dir":"Buffered-comparison-and-stopping-band-resolution-in-critical-Ising-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"219","t":"GOE universality for random regular graphs with weak disorder","d":"For every fixed degree d≥3, the bulk adjacency-eigenvalue point process of a uniform simple random d-regular graph converges to the Gaussian orthogonal ensemble law, including for cubic graphs. The same fixed-energy universality persists under sufficiently weak fixed iid uniform diagonal disorder, throughout compact bands strictly inside the clean spectral edges.","disc":8,"tier":"B","effort":"M","widget":"Sample random d-regular graphs, compute adjacency eigenvalues and compare level spacings to the GOE (Wigner surmise).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Fixed-energy universality for weak Anderson disorder on random regular graphs","dir":"Fixed-energy-universality-for-weak-Anderson-disorder-on-random-regular-graphs-October-5-2026","pdf":"fixed-energy-universality-weak-anderson-disorder-random-regular-graphs.pdf","lean":false},{"t":"GOE bulk universality for fixed-degree random regular graphs","dir":"GOE-bulk-universality-for-fixed-degree-random-regular-graphs-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"220","t":"Directional zero–one laws and ballisticity in random environments","d":"On ℤᵈ, d≥3, directional escape has probability zero or one for iid strictly elliptic nearest-neighbor environments, and for stationary ergodic finite-range-dependent environments under uniform ellipticity. In iid uniformly elliptic environments with d≥2, almost-sure directional transience implies a deterministic limiting velocity with positive projection in that direction, resolving the ballisticity conjecture.","disc":8,"tier":"B","effort":"S","widget":"Simulate random walks in random environments on Z²/Z³ and watch directional escape and limiting velocity.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A directional zero–one law for finite-range-dependent random environments","dir":"A-directional-zero-one-law-for-finite-range-dependent-random-environments-October-5-2026","pdf":"directional-zero-one-finite-range.pdf","lean":false},{"t":"A directional zero–one law under strict ellipticity","dir":"A-directional-zero-one-law-under-strict-ellipticity-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Directional transience implies ballisticity","dir":"Directional-transience-implies-ballisticity-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"221","t":"The Mézard–Parisi formula for diluted spin glasses","d":"Proves the Mézard–Parisi hierarchical cavity formula for Poisson-diluted even-arity Ising models satisfying the Panchenko–Talagrand factorization and positivity assumptions, with only first-moment integrability. The limiting free energy equals the infimum over finite-depth hierarchical trial laws. This includes the Viana–Bray model, symmetric diluted even-spin models, and weighted soft even-K satisfiability.","disc":8,"tier":"C","effort":"S","widget":"Text card on the Mezard–Parisi formula for diluted spin glasses.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Mézard–Parisi formula for diluted spin glasses","dir":"The-Mezard-Parisi-formula-for-diluted-spin-glasses-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"222","t":"Perceptron free energies and microscopic jamming","d":"Determines finite-temperature variational free energies for Gaussian Ising perceptrons with bounded Borel log-potentials and Gaussian spherical perceptrons with bounded continuous potentials, at every positive pattern density. A spherical extension treats bi-orthogonally invariant disorder with compact limiting singular-value distributions and no outliers. At margin -1, the quadratic-penalty spherical model has a sharp feasibility threshold and limiting gap and force laws, with system size, zero temperature, and critical density taken in that order.","disc":8,"tier":"B","effort":"M","widget":"Sample random perceptron constraints and run a solver near capacity, watching the feasibility threshold and jamming gap/force distributions.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The free energy of the Ising random perceptron","dir":"The-free-energy-of-the-Ising-random-perceptron-September-24-2026","pdf":"The-free-energy-of-the-Ising-random-perceptron-September-24-2026.pdf","lean":false},{"t":"Microscopic jamming in the negative spherical perceptron","dir":"Microscopic-jamming-in-the-negative-spherical-perceptron-September-24-2026","pdf":"Microscopic-jamming-in-the-negative-spherical-perceptron-September-24-2026.pdf","lean":false},{"t":"The spherical perceptron with bi-orthogonally invariant disorder","dir":"The-spherical-perceptron-with-bi-orthogonally-invariant-disorder-September-24-2026","pdf":"The-spherical-perceptron-with-bi-orthogonally-invariant-disorder-September-24-2026.pdf","lean":false},{"t":"The free energy of the spherical random perceptron","dir":"The-free-energy-of-the-spherical-random-perceptron-September-24-2026","pdf":"The-free-energy-of-the-spherical-random-perceptron-September-24-2026.pdf","lean":false}]},{"id":"223","t":"Conformal limits of square-lattice random-cluster interfaces","d":"Proves chordal SLE_κ limits for critical square-lattice random-cluster interfaces for 0<q≤4, with κ=4π/arccos(-√q/2): bounded Jordan domains are allowed for q≥1, and smooth Jordan domains for q<1, under the stated marked-boundary approximations. For 1≤ q≤4, complete nested plane loops converge to CLE_κ.","disc":8,"tier":"B","effort":"M","widget":"Simulate critical random-cluster model on a square grid, trace the interface, and compare with SLEₖappa for chosen q.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Square-lattice FK interfaces and nested loops for 1 <= q < 4","dir":"Square-lattice-FK-interfaces-and-nested-loops-for-1-leq-q-lt-4-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Self-dual random-cluster interfaces below one","dir":"Self-dual-random-cluster-interfaces-below-one-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Quenched SLE Universality for Weakly Disordered FK–Ising Interfaces","dir":"Quenched-SLE-Universality-for-Weakly-Disordered-FK-Ising-Interfaces-October-5-2026","pdf":"quenched-fk-ising.pdf","lean":false},{"t":"Thermal FK–Ising interfaces and massive SLE","dir":"Thermal-FK-Ising-interfaces-and-massive-SLE-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Natural Occupation Measures for Critical Square-Lattice FK Interfaces","dir":"Natural-Occupation-Measures-for-Critical-Square-Lattice-FK-Interfaces-October-5-2026","pdf":"natural-occupation-measures-critical-square-lattice-fk-interfaces.pdf","lean":false},{"t":"Conformal Limits of Critical Square-Lattice Random-Cluster Interfaces","dir":"Conformal-Limits-of-Critical-Square-Lattice-Random-Cluster-Interfaces-October-5-2026","pdf":"paper.pdf","lean":false}]},{"id":"224","t":"Critical and near-critical universality for Voronoi percolation","d":"Proves Cardy's formula for annealed critical Poisson–Voronoi crossing probabilities in every bounded Jordan quadrilateral. With each model normalized by its own expected unit-square pivotal count, the conditional joint near-critical crossing-threshold laws for rational polygonal quads converge in environment probability to the triangular-lattice reference law. This establishes quenched near-critical universality for crossing thresholds.","disc":8,"tier":"B","effort":"M","widget":"Simulate critical Poisson-Voronoi percolation in a user-drawn quad and compare crossing frequencies with Cardy's formula.","related":["voronoi"],"conj":false,"page":null,"lean":0,"papers":[{"t":"From critical crossings to quenched near-critical universality in Voronoi percolation","dir":"From-critical-crossings-to-quenched-near-critical-universality-in-Voronoi-percolation-October-5-2026","pdf":"critical-crossings-quenched-near-critical-universality-voronoi-percolation.pdf","lean":false},{"t":"A Pivotal Amplitude for Voronoi Percolation from Cardy's Formula","dir":"A-Pivotal-Amplitude-for-Voronoi-Percolation-from-Cardys-Formula-October-5-2026","pdf":"voronoi-pivotal-amplitude.pdf","lean":false},{"t":"Cardy’s formula for critical Poisson–Voronoi percolation","dir":"Cardys-formula-for-critical-Poisson-Voronoi-percolation-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"225","t":"Gaussian free field limits for the balanced six-vertex model","d":"The balanced square-lattice six-vertex height field with a=b=1 and 0<c≤2 converges to a Gaussian free field, including at the endpoint c=2. The plane state is defined by balanced-torus limits. For unit height increments and Green kernel -(2π)⁻¹log|x-y|, the exact variance multiplier is 1/arcsin(c/2).","disc":8,"tier":"B","effort":"M","widget":"Monte Carlo sample the six-vertex model for c in (0,2], show the height function and its variance against the 1/arcsin(c/2) prediction.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Gaussian free field limit of the balanced six-vertex model with variance multiplier 1/arcsin(c/2)","dir":"The-Gaussian-free-field-limit-of-the-balanced-six-vertex-model-with-variance-multiplier-1-over-arcsin-c-over-2-September-23-2026","pdf":"The-Gaussian-free-field-limit-of-the-balanced-six-vertex-model-with-variance-multiplier-1-over-arcsin-c-over-2-September-23-2026.pdf","lean":false}]},{"id":"226","t":"The double-dimer CLE₄ conjecture in the half-plane","d":"Resolves the half-plane Temperleyan form of the double-dimer scaling-limit conjecture: the complete loop ensemble formed by two independent dimer coverings of the Temperleyan square lattice converges to nested CLE₄. Convergence matches every macroscopic loop as an unparametrized curve, upgrading convergence of loop observables to convergence of the loops themselves.","disc":8,"tier":"B","effort":"M","widget":"Sample two random domino tilings, overlay them into double-dimer loops, and see CLE₄-like nested loops emerge.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The curve scaling limit of half-plane double dimers","dir":"The-curve-scaling-limit-of-half-plane-double-dimers-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"227","t":"The dynamical phase transition in the Sherrington–Kirkpatrick model","d":"For zero-field Gaussian SK heat-bath dynamics with rate-one updates per spin, proves worst-start cutoff on the log n scale for fixed 0≤β<1, mixing time n^(2/3+o(1)) at β=1, and stretched-exponential mixing from a Gibbs-sampled fixed starting configuration for β>1, in probability over disorder. At criticality, rescaled stationary and quench autocorrelation processes have universal random limits for Gaussian and Rademacher disorder; the quench limit relaxes to the stationary limit.","disc":8,"tier":"B","effort":"M","widget":"Simulate heat-bath dynamics of an SK spin glass at chosen beta and n, plotting magnetization autocorrelation and empirical mixing to see slowdown across beta=1.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Universality of critical quench autocorrelations in the Sherrington–Kirkpatrick model","dir":"Universality-of-critical-quench-autocorrelations-in-the-Sherrington-Kirkpatrick-model-October-5-2026","pdf":"main.pdf","lean":false},{"t":"Functional universality of critical SK autocorrelations","dir":"Functional-universality-of-critical-SK-autocorrelations-October-5-2026","pdf":"critical-sk-autocorrelations.pdf","lean":false},{"t":"A spectral gap throughout the high-temperature Sherrington–Kirkpatrick phase","dir":"A-spectral-gap-throughout-the-high-temperature-Sherrington-Kirkpatrick-phase-September-24-2026","pdf":"main.pdf","lean":false},{"t":"Cutoff throughout the high-temperature Sherrington–Kirkpatrick phase","dir":"Cutoff-throughout-the-high-temperature-Sherrington-Kirkpatrick-phase-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Critical slowing down in the Sherrington–Kirkpatrick model","dir":"Critical-slowing-down-in-the-Sherrington-Kirkpatrick-model-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"Stretched-exponential barriers for typical SK initial states","dir":"Stretched-exponential-barriers-for-typical-SK-initial-states-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"A typical-start upper bound for low-temperature SK Glauber dynamics","dir":"A-typical-start-upper-bound-for-low-temperature-SK-Glauber-dynamics-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Critical mixing in the Sherrington–Kirkpatrick model","dir":"Critical-mixing-in-the-Sherrington-Kirkpatrick-model-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"228","t":"Continuum phase transitions for radial pair potentials","d":"Constructs stable distance-dependent pair interactions for three-dimensional classical particles with a first-order phase transition: the canonical free energy has a derivative jump at one inverse temperature throughout an open density interval. One potential has a divergent repulsive core; another is bounded and continuous with an integrable power-law tail, realizing the type of transition sought in Simon's continuum problem.","disc":8,"tier":"B","effort":"L","widget":"Molecular-dynamics/Monte Carlo of 3D particles with an engineered radial pair potential, showing a first-order transition in energy vs temperature.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"A continuum temperature singularity for a radial pair potential","dir":"A-continuum-temperature-singularity-for-a-radial-pair-potential-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"A radial continuum phase transition with algebraic decay","dir":"A-radial-continuum-phase-transition-with-algebraic-decay-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"229","t":"Sharp three- and four-state reconstruction thresholds","d":"Proves the exact reconstruction threshold dλ²>1, with nonreconstruction at equality, for three-state symmetric and four-state ferromagnetic broadcasting on regular trees (d≥2) and observed Poisson trees (mean d>1 and d>0, respectively), with Poisson advantage averaged without conditioning on survival. The three-state theorem allows both signs of λ and gives the exact weak-recovery threshold for the symmetric three-community stochastic block model.","disc":8,"tier":"B","effort":"S","widget":"Broadcast colours down a random tree with noise and try to guess the root, sliding d*lambda² across 1.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Reconstruction Threshold for the Ferromagnetic Four-State Potts Model","dir":"The-Reconstruction-Threshold-for-the-Ferromagnetic-Four-State-Potts-Model-October-5-2026","pdf":"four-state-potts.pdf","lean":false},{"t":"A Capacity Criterion for Four-State Potts Reconstruction on Trees","dir":"A-Capacity-Criterion-for-Four-State-Potts-Reconstruction-on-Trees-October-5-2026","pdf":"four-state-capacity.pdf","lean":false},{"t":"The exact reconstruction threshold for the three-state symmetric channel","dir":"The-exact-reconstruction-threshold-for-the-three-state-symmetric-channel-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"230","t":"Exact Hausdorff measure for SLE","d":"Resolves Schramm’s Hausdorff-measure question for chordal SLE_κ, 0<κ<8. The explicit gauge rᵈ(loglog(1/r))^((2-d)/2), d=1+κ/8, gives almost surely positive finite measure to every trace segment γ([s,t]) with 0<s<t<∞, and finite expected measure to the trace in every bounded disk.","disc":8,"tier":"B","effort":"M","widget":"Generate SLEₖappa curves for adjustable kappa and box-count their dimension 1+kappa/8, overlaying the log-log correction gauge.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An exact Hausdorff gauge for SLE","dir":"An-exact-Hausdorff-gauge-for-SLE-September-25-2026","pdf":"An-exact-Hausdorff-gauge-for-SLE-September-25-2026.pdf","lean":false},{"t":"An explicit exact Hausdorff gauge for SLE","dir":"An-explicit-exact-Hausdorff-gauge-for-SLE-September-26-2026","pdf":"An-explicit-exact-Hausdorff-gauge-for-SLE-September-26-2026.pdf","lean":false}]},{"id":"231","t":"The free uniform spanning forest is a factor of IID","d":"On every infinite connected locally finite simple unweighted graph, the free uniform spanning forest is a factor of independent vertex labels, by one isomorphism-equivariant rule using no root. Translation-invariant strongly Rayleigh binary processes on every countable group, including invariant determinantal processes with Hermitian positive-contraction kernels, are also factors of IID.","disc":8,"tier":"B","effort":"S","widget":"Run Wilson's algorithm on growing graphs to show uniform spanning trees/forests.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The free uniform spanning forest is a factor of IID","dir":"The-free-uniform-spanning-forest-is-a-factor-of-IID-September-25-2026","pdf":"The-free-uniform-spanning-forest-is-a-factor-of-IID-September-25-2026.pdf","lean":false}]},{"id":"232","t":"Gaussian fields and SLE interfaces for Lipschitz heights","d":"Proves Gaussian free field limits on bounded smooth simply connected domains for triangular-lattice height models: uniform odd heights with increments 0,±2 and two-arc boundary values ±1, and zero-boundary integer Lipschitz heights weighted by fixed x∈[1/√2,1]. Uniform real Lipschitz heights also converge to a Gaussian field; at a tuned opposite-boundary amplitude, their interface converges to chordal SLE₄, establishing Schramm’s real-field/interface predictions.","disc":8,"tier":"B","effort":"M","widget":"Sample Lipschitz height functions on the triangular lattice and watch them look like a Gaussian free field, with the SLE₄ interface between boundary arcs.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Gaussian free-field limits of weighted integer Lipschitz heights","dir":"Gaussian-free-field-limits-of-weighted-integer-Lipschitz-heights-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"The Gaussian free field limit of integer Lipschitz heights with two-arc boundary data","dir":"The-Gaussian-free-field-limit-of-integer-Lipschitz-heights-with-two-arc-boundary-data-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Uniform real Lipschitz surfaces on the triangular lattice","dir":"Uniform-real-Lipschitz-surfaces-on-the-triangular-lattice-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"233","t":"The joint critical Ashkin–Teller scaling limit","d":"Identifies the joint scaling limit of Ashkin–Teller heights and both complete current-cluster collections throughout the critical line, including the four-state Potts endpoint. In bounded Jordan domains with admissible lattice approximations and wired primal/free dual boundaries, the height converges to the predicted Gaussian free field, and the clusters to canonical recursive sets of that same field, retaining every nesting depth.","disc":8,"tier":"B","effort":"L","widget":"Simulate the Ashkin–Teller model along its critical line and show height function and current clusters.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The joint scaling limit of critical Ashkin-Teller currents","dir":"The-joint-scaling-limit-of-critical-Ashkin-Teller-currents-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"234","t":"All-temperature pressure for orthogonally invariant Ising spin glasses","d":"Gives an exact variational formula for the limiting pressure of orthogonally invariant Ising spin glasses at every fixed temperature, both almost surely and in expectation. The coupling matrix is a Haar-random rotation of a deterministic spectrum converging to a compactly supported law, with extreme eigenvalues converging to its support edges. The zero-field ground-state energy follows as temperature tends to zero.","disc":8,"tier":"B","effort":"M","widget":"Simulate an Ising spin glass with a Haar-rotated coupling spectrum and compare finite-size free energy with the variational formula curve.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"All-temperature pressure for orthogonally invariant Ising spin glasses","dir":"All-temperature-pressure-for-orthogonally-invariant-Ising-spin-glasses-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"235","t":"Random-SAT thresholds, sharp variance and computability","d":"For random k-SAT with independent uniformly signed proper clauses sampled with replacement, proves finite positive limiting thresholds and hitting-time variance Θₖ(n) for every fixed k≥3, and computability of the 3-SAT threshold. We credit Gaia Carenini with priority for resolving the threshold-existence conjecture in her concurrent ECCC TR26-229, made public October 5, 2026; this family supplies another proof and the sharper variance and computability results.","disc":8,"tier":"B","effort":"S","widget":"Generate random 3-SAT at clause density alpha, solve with a small DPLL, and watch the satisfiable fraction drop near 4.27.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Limiting Satisfiability Threshold for Every Fixed Clause Size","dir":"A-Limiting-Satisfiability-Threshold-for-Every-Fixed-Clause-Size-September-25-2026","pdf":"article.pdf","lean":false},{"t":"Linear Variance of the Random 3-SAT Hitting Time","dir":"Linear-Variance-of-the-Random-3-SAT-Hitting-Time-October-5-2026","pdf":"linear-variance-of-the-random-3-sat-hitting-time.pdf","lean":false},{"t":"Variance of the Random k-SAT Hitting Time","dir":"Variance-of-the-Random-k-SAT-Hitting-Time-September-27-2026","pdf":"article.pdf","lean":false},{"t":"Computing the Random 3-SAT Threshold","dir":"Computing-the-Random-3-SAT-Threshold-September-27-2026","pdf":"article.pdf","lean":false}]},{"id":"236","t":"The factor-of-IID threshold for free Ising states on trees","d":"Determines when the free zero-field ferromagnetic Ising state on the infinite d-regular tree is a factor of independent vertex labels: exactly when tanhβ≤(d-1)^(-1/2), including equality, for d≥3 and β≥0. The construction uses no root and is almost surely equivariant for each fixed tree automorphism, resolving the ferromagnetic case of Lyons's question.","disc":8,"tier":"B","effort":"M","widget":"Sample Ising states on a d-regular tree and show the factor-of-IID threshold tanh(beta)=1/sqrt(d-1).","related":["ising"],"conj":false,"page":null,"lean":1,"papers":[{"t":"The sharp factor-of-IID threshold for the free Ising model on regular trees","dir":"The-sharp-factor-of-IID-threshold-for-the-free-Ising-model-on-regular-trees-September-26-2026","pdf":"article.pdf","lean":true}]},{"id":"237","t":"The three-quarter diameter exponent for honeycomb walks","d":"Proves the diameter form of Nienhuis's predicted three-quarter exponent: a uniformly chosen n-step self-avoiding walk on the honeycomb lattice has diameter n^(3/4+o(1)). Its local mass and covering numbers have exponent 4/3. These estimates hold at every sufficiently large fixed length, simultaneously across scales, with arbitrarily high polynomial probability.","disc":8,"tier":"B","effort":"M","widget":"Grow self-avoiding walks on the honeycomb lattice and plot diameter vs n against n^(3/4).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Radial transfer estimates and polygon length laws for honeycomb walks","dir":"Radial-transfer-estimates-and-polygon-length-laws-for-honeycomb-walks-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Critical honeycomb chords with prescribed boundary endpoints","dir":"Critical-honeycomb-chords-with-prescribed-boundary-endpoints-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Cylinder loop weights and planar nesting","dir":"Cylinder-loop-weights-and-planar-nesting-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Mass and covering exponents for fixed-length honeycomb walks","dir":"Mass-and-covering-exponents-for-fixed-length-honeycomb-walks-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Signed cylinder propagation and marked polygons on the honeycomb lattice","dir":"Signed-cylinder-propagation-and-marked-polygons-on-the-honeycomb-lattice-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Cylinder amplitudes and logarithmic bridge-length windows on the honeycomb lattice","dir":"Cylinder-amplitudes-and-logarithmic-bridge-length-windows-on-the-honeycomb-lattice-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Marked polygon correlations and one-arc bounds","dir":"Marked-polygon-correlations-and-one-arc-bounds-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Disk transfer representations and confined bridge mass","dir":"Disk-transfer-representations-and-confined-bridge-mass-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Polynomial vacuum representations and bridge mass for honeycomb walks","dir":"Polynomial-vacuum-representations-and-bridge-mass-for-honeycomb-walks-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Renewal and changes of law for critical honeycomb walks","dir":"Renewal-and-changes-of-law-for-critical-honeycomb-walks-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Critical strip-crossing mass on the honeycomb lattice","dir":"Critical-strip-crossing-mass-on-the-honeycomb-lattice-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Uniform marked-polygon estimates and sharp finite bridge moments","dir":"Uniform-marked-polygon-estimates-and-sharp-finite-bridge-moments-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Cap-selected amplitudes and triangle chords for honeycomb walks","dir":"Cap-selected-amplitudes-and-triangle-chords-for-honeycomb-walks-September-26-2026","pdf":"main.pdf","lean":false}]},{"id":"238","t":"Optimal logarithmic mixing of the Thorp shuffle","d":"Proves that the Thorp shuffle randomizes N=2ᵈ labeled cards in Θ(log N) physical shuffles, settling its optimal mixing order for power-of-two deck sizes. Convergence is in total variation from the worst initial ordering and concerns the entire permutation, not just individual card positions.","disc":8,"tier":"B","effort":"S","widget":"Animate the Thorp shuffle on 2ᵈ cards and plot total-variation distance to uniform; compute it exactly for 8 cards.","related":[],"conj":false,"page":null,"lean":3,"papers":[{"t":"Optimal-order mixing of the Thorp shuffle","dir":"Optimal-order-mixing-of-the-Thorp-shuffle-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Random coordinate frames and partial permutation laws","dir":"Random-coordinate-frames-and-partial-permutation-laws-September-26-2026","pdf":"main.pdf","lean":false},{"t":"From partial permutation information to Fourier bounds","dir":"From-partial-permutation-information-to-Fourier-bounds-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Conditional information under deterministic coordinate sweeps","dir":"Conditional-information-under-deterministic-coordinate-sweeps-September-26-2026","pdf":"main.pdf","lean":false},{"t":"Conditional permutations in a revealed switching environment","dir":"Conditional-permutations-in-a-revealed-switching-environment-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Routing densities and representation contraction for Thorp sweeps","dir":"Routing-densities-and-representation-contraction-for-Thorp-sweeps-September-26-2026","pdf":"paper.pdf","lean":true},{"t":"Row&#8211;column symmetry and contraction of coordinate sweeps","dir":"Row-column-symmetry-and-contraction-of-coordinate-sweeps-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Random-subspace tests and trace smoothing for coordinate sweeps","dir":"Random-subspace-tests-and-trace-smoothing-for-coordinate-sweeps-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Compatibility entropy and the spectrum of a Thorp sweep","dir":"Compatibility-entropy-and-the-spectrum-of-a-Thorp-sweep-September-26-2026","pdf":"paper.pdf","lean":true},{"t":"Signed tensor densities and diagram budgets for the Thorp shuffle","dir":"Signed-tensor-densities-and-diagram-budgets-for-coordinate-sweeps-September-26-2026","pdf":"paper.pdf","lean":false},{"t":"Conditional coordinate sweeps and analytic transfer","dir":"Conditional-coordinate-sweeps-and-analytic-transfer-September-26-2026","pdf":"main.pdf","lean":true},{"t":"A strict four-row permanent inequality and permutation moments","dir":"A-strict-four-row-permanent-inequality-and-permutation-moments-September-26-2026","pdf":"main.pdf","lean":false}]},{"id":"239","t":"Sharp singularity rates for symmetric sign matrices","d":"Determines the sharp exponential singularity rate of symmetric random sign matrices with independent entries on and above the diagonal. Uniform signs give Pr(det Aₙ=0)=(1/2+o(1))ⁿ; for fixed bias p∈(0,1)∖{1/2}, the rate is (p²+(1-p)²+o(1))ⁿ. In the biased case, agreeing rows attain this rate.","disc":8,"tier":"B","effort":"S","widget":"Sample random symmetric +/-1 matrices, estimate Pr(det=0) and compare with (1/2)ⁿ or (p²+(1-p)²)ⁿ; exact census for n<=6.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The sharp exponential rate of singularity for symmetric Bernoulli matrices","dir":"The-sharp-exponential-rate-of-singularity-for-symmetric-Bernoulli-matrices-October-3-2026","pdf":"symmetric-bernoulli-singularity.pdf","lean":false},{"t":"The sharp singularity rate for biased symmetric sign matrices","dir":"The-sharp-singularity-rate-for-biased-symmetric-sign-matrices-October-4-2026","pdf":"biased-symmetric-sign-singularity.pdf","lean":false}]},{"id":"240","t":"Shelah's eventual categoricity conjecture","d":"Proves Shelah's eventual categoricity conjecture in ZFC: for each bound on the Löwenheim–Skolem number, a uniform threshold makes categoricity of an abstract elementary class in one cardinal above that threshold imply categoricity throughout the same tail. Categoricity means uniqueness up to isomorphism at a given cardinality. Under the continuum hypothesis, a proposed specific Hanf threshold need not suffice.","disc":9,"tier":"C","effort":"S","widget":"Text card on categoricity of abstract elementary classes.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A CH obstruction to a prescribed categoricity threshold","dir":"A-CH-Obstruction-to-a-Prescribed-Categoricity-Threshold-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"Eventual categoricity for abstract elementary classes","dir":"Eventual-Categoricity-for-Abstract-Elementary-Classes-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"241","t":"Rigidity of the Turing degrees","d":"Every order automorphism of the Turing degrees is the identity, resolving their rigidity problem. Thus no nontrivial relabeling of degrees preserves the ordering by relative computability.","disc":9,"tier":"C","effort":"S","widget":"Text card on Turing degrees and their rigidity.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Rigidity of the Turing degrees","dir":"Rigidity-of-the-Turing-degrees-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"242","t":"Single-fold Diophantine representations","d":"Every recursively enumerable set of tuples of natural numbers has a Diophantine representation with exactly one auxiliary solution for each member and none for nonmembers. This proves the single-fold conjecture and hence the finite-fold conjecture. Diophantine solvability over the nonnegative integers remains undecidable even with an at-most-one-solution promise.","disc":9,"tier":"C","effort":"S","widget":"Text card on single-fold Diophantine representations of r.e. sets.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Single-fold Diophantine representations","dir":"Single-fold-Diophantine-representations-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"243","t":"Choiceless counting does not capture polynomial time","d":"Confirms the Blass–Gurevich–Shelah noncapture conjecture: consistency of a linear system over 𝔽₃ defines a polynomial-time query on unordered finite structures that choiceless polynomial time with counting cannot express. A separate result shows that adding witnessed symmetric choice strictly increases expressive power. Both separations hold for the full counting formalism, allowing hereditarily finite sets of arbitrary finite rank.","disc":9,"tier":"C","effort":"S","widget":"Card on choiceless polynomial time and F₃ linear systems.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Choiceless polynomial time with counting does not capture polynomial time","dir":"Choiceless-polynomial-time-with-counting-does-not-capture-polynomial-time-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Witnessed symmetric choice is strictly stronger than choiceless polynomial time with counting","dir":"Witnessed-symmetric-choice-is-strictly-stronger-than-choiceless-polynomial-time-with-counting-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"244","t":"The partition principle does not imply choice","d":"Assuming ZF is consistent, constructs a model in which every surjective image of a set injects into that set, yet the axiom of choice fails. Choice for ordinal-indexed families still holds. From any countable transitive model of ZFC, a separate construction gives a transitive symmetric extension with these properties and no new countable sequences of ground-model elements.","disc":9,"tier":"C","effort":"S","widget":"Card only: the Partition Principle does not imply the Axiom of Choice.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The Partition Principle does not imply Choice","dir":"The-Partition-Principle-does-not-imply-Choice-September-24-2026","pdf":"partition-principle-without-choice.pdf","lean":true}]},{"id":"245","t":"The β-Barendregt–Geuvers–Klop conjecture","d":"Proves that weak normalization implies strong normalization for every pure type system: if every legal expression in every valid context has a β-normal form, every β-reduction sequence terminates. This resolves the β-Barendregt–Geuvers–Klop conjecture, including nonfunctional rules and open contexts.","disc":9,"tier":"C","effort":"S","widget":"Text card: weak normalization implies strong normalization for pure type systems.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Weak and strong normalization in pure type systems","dir":"Weak-and-strong-normalization-in-pure-type-systems-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"246","t":"Cannon's conjecture","d":"Every word-hyperbolic group with boundary homeomorphic to S² admits a proper cocompact isometric action on hyperbolic three-space with finite kernel, proving Cannon's conjecture. Every torsion-free such group is therefore the fundamental group of a closed hyperbolic three-manifold.","disc":10,"tier":"C","effort":"S","widget":"Text card on Cannon's conjecture: groups with sphere boundary are Kleinian.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Modulus Proof of Cannon’s Conjecture","dir":"A-Modulus-Proof-of-Cannons-Conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"247","t":"An infinite finitely presented residually finite 2-group","d":"Constructs an infinite finitely presented residually finite group whose elements all have finite 2-power order, answering the finitely presented Burnside problem negatively even in this class. The construction also yields an infinite-dimensional finitely presented nil associative 𝔽₂-algebra and a finitely presented infinite-dimensional algebraic unitization, giving negative answers to the corresponding nilpotence and Kurosh finiteness questions.","disc":10,"tier":"C","effort":"S","widget":"Text card on the Burnside problem and finitely presented torsion groups.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"An infinite finitely presented residually finite 2-group","dir":"An-infinite-finitely-presented-residually-finite-2-group-October-5-2026","pdf":"residually-finite-torsion.pdf","lean":false},{"t":"An infinite finitely presented periodic group","dir":"An-infinite-finitely-presented-periodic-group-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"248","t":"Thompson's group F is nonamenable","d":"Proves that Thompson's group F, the group of dyadic piecewise linear homeomorphisms of the interval, is nonamenable, resolving its longstanding amenability problem.","disc":10,"tier":"B","effort":"M","widget":"Build elements of Thompson's group F as tree-pair diagrams / dyadic PL maps, compose them, and run random walks.","related":[],"conj":true,"page":null,"lean":1,"papers":[{"t":"Thompson's group F is nonamenable","dir":"Thompsons-group-F-is-nonamenable-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"249","t":"A finitely generated counterexample to Eilenberg–Ganea","d":"Constructs a finitely generated residually finite group with integral cohomological dimension two and geometric dimension three, disproving the Eilenberg–Ganea conjecture. It has no two-dimensional classifying space, even with infinitely many cells.","disc":10,"tier":"C","effort":"S","widget":"Card showing the seed presentation <x,y | x²y⁻5, x²(xy⁻1)⁻3> and explaining cd vs gd.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"A finitely generated counterexample to the Eilenberg–Ganea conjecture","dir":"A-finitely-generated-counterexample-to-the-Eilenberg-Ganea-conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"250","t":"The Boone–Higman conjecture and higher finiteness","d":"A finitely generated group has decidable word problem exactly when it embeds in a finitely presented simple group, proving the Boone–Higman conjecture. The target can have type F_∞: a classifying space with finitely many cells in each dimension. A single group of type F_∞ can also contain every finitely presented group.","disc":10,"tier":"C","effort":"S","widget":"Card only: Boone-Higman conjecture.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Finite algebraic envelopes and the Boone–Higman conjecture","dir":"Finite-algebraic-envelopes-and-the-Boone-Higman-conjecture-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Simple F∞ overgroups of groups with decidable word problem","dir":"Simple-F-infinity-overgroups-of-groups-with-decidable-word-problem-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"A universal group of type F∞","dir":"A-universal-group-of-type-F-infinity-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"251","t":"Amenability, unitarizability, and Ulam stability","d":"Resolves Dixmier's problem for all discrete groups: amenability is equivalent to every uniformly bounded Hilbert-space representation being similar to a unitary representation. For countable discrete groups, amenability is also equivalent to strong Ulam stability: sufficiently accurate unitary approximate representations are uniformly close in operator norm to genuine representations on the same, possibly infinite-dimensional, Hilbert space.","disc":10,"tier":"C","effort":"S","widget":"Text card on amenability, unitarizability and Ulam stability.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Unitarizability implies amenability for discrete groups","dir":"Unitarizability-Implies-Amenability-for-Countable-Groups-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Strong Ulam Stability Characterizes Amenability","dir":"Strong-Ulam-Stability-Characterizes-Amenability-October-5-2026","pdf":"strong-ulam-stability.pdf","lean":false}]},{"id":"252","t":"A non-residually-finite torsion-free hyperbolic group","d":"Constructs a torsion-free word-hyperbolic group that is not residually finite, answering the residual-finiteness question negatively. One fixed nonidentity element is killed by every finite-dimensional linear representation over every commutative field, so the group is not linear over any such field.","disc":10,"tier":"C","effort":"S","widget":"Text card on a torsion-free hyperbolic group that is not residually finite.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A torsion-free hyperbolic group that is not residually finite","dir":"a-torsion-free-hyperbolic-group-that-is-not-residually-finite-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"253","t":"An infinite finitely presented simple amenable group","d":"Constructs an infinite finitely presented simple amenable group, answering the longstanding question of whether these properties can occur simultaneously.","disc":10,"tier":"C","effort":"S","widget":"Text card on simple amenable groups.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"An infinite finitely presented simple amenable group","dir":"An-Infinite-Finitely-Presented-Simple-Amenable-Group-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"254","t":"Classifying spaces and geometric obstructions for Artin groups","d":"The Salvetti complex of every finite-rank Artin group is aspherical, proving the Artin K(π,1) conjecture. Arbitrary intersections of its parabolic subgroups are parabolic, proving the Parabolic Intersection Conjecture. An explicit Artin group admits no proper cocompact isometric action on any nonempty proper CAT(0) space.","disc":10,"tier":"C","effort":"S","widget":"Text card on the Artin K(pi,1) conjecture and parabolic intersections, with Coxeter diagrams.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Harmonic heights and the Artin K(pi,1) conjecture","dir":"Harmonic-heights-and-the-Artin-K-pi-1-conjecture-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"An Artin group with no geometric CAT(0) action","dir":"An-Artin-group-with-no-geometric-CAT-0-action-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Parabolic intersections in Artin groups","dir":"Parabolic-intersections-in-Artin-groups-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"255","t":"Quasi-isometric rigidity of virtually polycyclic groups","d":"Proves that every finitely generated group quasi-isometric to a finitely generated virtually polycyclic group is virtually polycyclic, resolving the Eskin–Fisher–Whyte lattice-recognition conjecture. Equivalently, a group quasi-isometric to a lattice in a connected simply connected solvable Lie group is virtually a uniform lattice in some such Lie group, possibly a different one.","disc":10,"tier":"B","effort":"M","widget":"Explore Cayley graphs of polycyclic groups (Z², Heisenberg, Sol) at large scale.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Quasi-isometric recognition of virtually polycyclic groups","dir":"quasi-isometric-recognition-of-virtually-polycyclic-groups-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"256","t":"Howie's conjecture on equations over groups","d":"Proves that every finite system of equations over an arbitrary group whose exponent-sum matrix has full row rank over ℚ has a simultaneous solution in an overgroup, resolving Howie's conjecture. The coefficient group embeds in the presented quotient. A companion proves Kervaire's conjecture: adjoining one generator and one relation cannot trivialize a nontrivial group.","disc":10,"tier":"C","effort":"S","widget":"Card only: Kervaire and Howie conjectures on equations over groups.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Nonsingular systems of equations over arbitrary groups","dir":"Nonsingular-systems-of-equations-over-arbitrary-groups-October-5-2026","pdf":"nonsingular-systems-over-arbitrary-groups.pdf","lean":false},{"t":"The Kervaire theorem for groups","dir":"The-Kervaire-Theorem-for-Groups-September-24-2026","pdf":"The-Kervaire-Theorem-for-Groups-September-24-2026.pdf","lean":false}]},{"id":"257","t":"A hyperbolic group with no geometric CAT(0) action","d":"Answers negatively whether every word-hyperbolic group is a CAT(0) group. Constructs one with a finite classifying space but no proper cocompact isometric action on any proper complete CAT(0) space, in any dimension.","disc":10,"tier":"C","effort":"S","widget":"Text card: a hyperbolic group that is not CAT(0).","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A hyperbolic group with no geometric CAT(0) action","dir":"A-hyperbolic-group-with-no-geometric-CAT0-action-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"258","t":"Gersten's conjecture for one-relator groups","d":"Proves Gersten's conjecture: every finitely generated one-relator group containing no Baumslag–Solitar subgroup BS(m,n), with m,n≠0, is word-hyperbolic. It also proves that every word-hyperbolic one-relator group is virtually compact special.","disc":10,"tier":"C","effort":"S","widget":"Text card on one-relator groups, Baumslag-Solitar subgroups and hyperbolicity.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Baumslag-Solitar-free one-relator groups are hyperbolic","dir":"Baumslag-Solitar-free-one-relator-groups-are-hyperbolic-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Virtual compact specialness of hyperbolic one-relator groups","dir":"Virtual-compact-specialness-of-hyperbolic-one-relator-groups-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"259","t":"A group without fixed price","d":"Constructs a finitely generated group with two essentially free probability-measure-preserving actions of different costs, answering the general fixed-price problem negatively. Its Bernoulli action has cost bounded away from one, while a sequence of finite height extensions has costs tending to one.","disc":10,"tier":"C","effort":"S","widget":"Text card on cost of group actions.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A group without fixed price","dir":"A-group-without-fixed-price-October-5-2026","pdf":"unequal-costs-rank-100-amalgam.pdf","lean":false}]},{"id":"260","t":"Spacetime Penrose inequalities and rigidity","d":"Proves the sharp enclosing-area spacetime Penrose inequality for smooth one-ended asymptotically flat initial data in every spatial dimension n≥3, under dominant energy, weak future trapping, positive enclosing area, and the stated decay assumptions. It bounds invariant ADM mass below using minimum enclosing area, with equality rigidity under additional horizon hypotheses. Charged upper-area bounds treat dyonic three-dimensional data; the higher-dimensional purely electric extension uses the matched neutral theorem.","disc":11,"tier":"B","effort":"M","widget":"Plot ADM mass vs horizon area for Schwarzschild/Reissner-Nordstrom/Kerr-Newman data and show the Penrose bound and its equality case.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The spacetime Penrose inequality with charge and original-data rigidity","dir":"The-spacetime-Penrose-inequality-with-charge-and-original-data-rigidity-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"A Charged Reduction of the Spacetime Penrose Inequality in Spatial Dimensions at Least Four","dir":"A-Charged-Reduction-of-the-Spacetime-Penrose-Inequality-in-Spatial-Dimensions-at-Least-Four-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Spacetime Penrose inequalities: enclosing area, charge, and rigidity","dir":"Spacetime-Penrose-inequalities-enclosing-area-charge-and-rigidity-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"The Kerr–Newman Penrose Inequality for Axisymmetric Electrovacuum Exteriors","dir":"The-Kerr-Newman-Penrose-Inequality-for-Axisymmetric-Electrovacuum-Exteriors-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Electromagnetic tails and the Kerr–Newman Penrose inequality","dir":"Electromagnetic-tails-and-the-Kerr-Newman-Penrose-inequality-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"The nonmaximal anti-de Sitter Penrose Inequality and original-data rigidity","dir":"The-nonmaximal-anti-de-Sitter-Penrose-Inequality-and-original-data-rigidity-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"The Penrose inequality for maximal asymptotically hyperbolic initial data","dir":"The-Penrose-inequality-for-maximal-asymptotically-hyperbolic-initial-data-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"A local Penrose inequality for conformal perturbations of Schwarzschild–anti-de Sitter data","dir":"A-local-Penrose-inequality-for-conformal-perturbations-of-Schwarzschild-anti-de-Sitter-data-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"The spacetime Penrose inequality and enclosing area","dir":"The-spacetime-Penrose-inequality-and-enclosing-area-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Conformal flow and the Riemannian Penrose inequality with minimizing frontiers","dir":"Conformal-flow-and-the-Riemannian-Penrose-inequality-with-minimizing-frontiers-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Equality and rigidity in the spacetime Penrose inequality","dir":"Equality-and-rigidity-in-the-spacetime-Penrose-inequality-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Boundary graph deformations for the spacetime Penrose inequality","dir":"Boundary-graph-deformations-for-the-spacetime-Penrose-inequality-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Area-controlled end replacement and the Bondi Penrose inequality in the CKS class","dir":"Area-controlled-end-replacement-and-the-Bondi-Penrose-inequality-in-the-CKS-class-September-27-2026","pdf":"paper.pdf","lean":false}]},{"id":"261","t":"Localization and delocalization in the Anderson model","d":"Resolves the predicted spectral contrast for the lattice Anderson model with independent uniform site potentials. In dimension two, every positive disorder strength gives almost surely pure-point spectrum. In every fixed dimension d≥3, sufficiently weak positive disorder gives purely absolutely continuous spectrum on a fixed open interval with nonzero spectral weight.","disc":11,"tier":"B","effort":"M","widget":"Diagonalize finite Anderson Hamiltonians in 2D/3D and show eigenvector localization vs spreading as disorder varies.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Absolutely Continuous Spectrum for Weak-Disorder Anderson Models in Dimensions at Least Three","dir":"Absolutely-Continuous-Spectrum-for-Weak-Disorder-Anderson-Models-in-Dimensions-at-Least-Three-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Pure-Point Spectrum for the Two-Dimensional Anderson Model at Every Positive Disorder","dir":"Pure-Point-Spectrum-for-the-Two-Dimensional-Anderson-Model-at-Every-Positive-Disorder-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"262","t":"Sharp one-dimensional Lieb–Thirring inequalities","d":"Proves the sharp one-dimensional Lieb–Thirring inequality for 1/2<γ<3/2 and arbitrary finite-matrix potentials W≥0 with ∫tr(W^(γ+1/2))<∞: the optimal constant is the scalar one-bound-state value, independent of matrix size. All equality cases are direct sums, in one constant unitary basis, of scalar sech² solitons with independent scales and centers, and zero channels.","disc":11,"tier":"A","effort":"S","widget":"Pick a potential (sech² soliton or your own bump) and compare the eigenvalue sum against the sharp Lieb-Thirring constant; see equality exactly on sech².","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Equality cases in the sharp one-dimensional matrix Lieb–Thirring inequality","dir":"Equality-cases-in-the-sharp-one-dimensional-matrix-Lieb-Thirring-inequality-October-5-2026","pdf":"sharp-one-dimensional-lieb-thirring-inequalities-matrix-potentials.pdf","lean":false},{"t":"Sharp one-dimensional Lieb–Thirring inequalities for matrix potentials","dir":"Sharp-one-dimensional-Lieb-Thirring-inequalities-for-matrix-potentials-October-5-2026","pdf":"sharp-matrix-lieb-thirring.pdf","lean":false},{"t":"Sharp one-dimensional Lieb–Thirring constants","dir":"Sharp-One-Dimensional-Lieb-Thirring-Constants-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"263","t":"The ionization and generalized ionization conjectures","d":"For the full nonrelativistic Coulomb model with two electron spin states, proves that a molecule with M fixed nuclei of charges at least one and total charge Z strictly binds at most Z+CM electrons. Neutral-atom first ionization energies and radii containing all but an expected half-electron have universal positive upper and lower bounds. The energy cost of removing m electrons has Thomas–Fermi asymptotics as m→∞ and Z/m→∞; neutral-atom outer radii have the corresponding iterated-limit asymptotics, taking Z→∞ first.","disc":11,"tier":"C","effort":"S","widget":"Text card on ionization bounds for Coulomb atoms.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Uniform excess charge for Coulomb molecules and the outer radius of neutral atoms","dir":"Uniform-excess-charge-for-Coulomb-molecules-and-the-outer-radius-of-neutral-atoms-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Generalized ionization energies for full Coulomb atoms","dir":"Generalized-ionization-energies-for-full-Coulomb-atoms-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"Generalized outer-electron radii of neutral Coulomb atoms","dir":"Generalized-outer-electron-radii-of-neutral-Coulomb-atoms-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"264","t":"Strong cosmic censorship near two-ended Kerr data","d":"Proves local strong cosmic censorship near each fixed rotating subextremal Kerr bridge. A dense G_δ subset of a weighted smooth neighborhood of smooth complete two-ended asymptotically flat vacuum data has full maximal globally hyperbolic developments with no future continuous nondegenerate extension whose weak connection is locally square-integrable. No symmetry is imposed; extensions need not satisfy the vacuum equations.","disc":11,"tier":"C","effort":"S","widget":"Text card on strong cosmic censorship near Kerr.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Generic Future Inextendibility with Square-Integrable Connection Near a Fixed Kerr Spacetime","dir":"Generic-Future-Inextendibility-with-Square-Integrable-Connection-Near-a-Fixed-Kerr-Spacetime-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Generic C1 Future Inextendibility Near Rotating Subextremal Kerr Spacetimes","dir":"Generic-C1-Future-Inextendibility-Near-Rotating-Subextremal-Kerr-Spacetimes-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Quantitative Near-Kerr Evolution and Generic C2 Future Inextendibility","dir":"Quantitative-Near-Kerr-Evolution-and-Generic-C2-Future-Inextendibility-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"265","t":"The two-dimensional gapped area law","d":"Proves an entropy area law for unique ground states of finite-range Hamiltonians on arbitrary finite induced square-lattice domains, using only a uniform full-system spectral gap and bounds on the local interactions. On open L× L squares, uniformly gapped nearest-neighbor ground states also admit projected entangled-pair state approximations with polynomial bond dimension and global vector error at most L⁻¹.","disc":11,"tier":"C","effort":"S","widget":"Text card on entanglement area laws for 2D gapped ground states.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A two-dimensional area law from a global spectral gap","dir":"A-two-dimensional-area-law-from-a-global-spectral-gap-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Polynomial PEPS approximation of gapped square-grid ground states","dir":"Polynomial-PEPS-approximation-of-gapped-square-grid-ground-states-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"266","t":"Exactly three mutually unbiased bases in dimension six","d":"Proves N(6)=3, resolving Zauner' s dimension-six mutually unbiased bases conjecture: three such bases exist in ℂ⁶, but four cannot. The exclusion is a complete certified computation under the stated binary64 arithmetic and compiler conditions. An independent companion proves the Matolcsi–Ruzsa–Weiner Fourier-vanishing conjecture for order-six complex Hadamard matrices outside Tao' s cubic equivalence class.","disc":11,"tier":"A","effort":"S","widget":"Inspect three mutually unbiased bases in C⁶ as phase grids, verify |<b,c>|²=1/6 live, and try (and fail) to numerically find a fourth.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The maximum number of mutually unbiased bases in dimension six","dir":"The-maximum-number-of-mutually-unbiased-bases-in-dimension-six-September-24-2026","pdf":"The-maximum-number-of-mutually-unbiased-bases-in-dimension-six-September-24-2026.pdf","lean":false},{"t":"Exact Fourier certificates for complex Hadamard matrices of order six","dir":"Exact-Fourier-certificates-for-complex-Hadamard-matrices-of-order-six-September-24-2026","pdf":"Exact-Fourier-certificates-for-complex-Hadamard-matrices-of-order-six-September-24-2026.pdf","lean":false}]},{"id":"267","t":"Positive-temperature Bose–Einstein condensation and quantum depletion","d":"Proves Bose–Einstein condensation for the exact canonical Gibbs state of the three-dimensional hard-sphere gas: each fixed exclusion distance and sufficiently small fixed density admit a strictly positive temperature, independent of volume, with positive condensate fraction in the thermodynamic limit. At zero temperature, proves the Bogoliubov leading quantum-depletion law for hard spheres and fixed bounded nonnegative radial finite-range potentials of positive scattering length, taking the thermodynamic limit before the dilute limit.","disc":11,"tier":"C","effort":"S","widget":"Card on Bose-Einstein condensation of hard spheres.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Bose–Einstein condensation at positive temperature in the dilute hard-sphere gas","dir":"Bose-Einstein-condensation-at-positive-temperature-in-the-dilute-hard-sphere-gas-October-5-2026","pdf":"positive-temperature-hard-spheres.pdf","lean":false},{"t":"Quantum Depletion and Momentum Distribution in the Dilute Hard-Sphere Bose Gas","dir":"Quantum-Depletion-and-Momentum-Distribution-in-the-Dilute-Hard-Sphere-Bose-Gas-October-5-2026","pdf":"Quantum-Depletion-in-the-Dilute-Hard-Sphere-Bose-Gas.pdf","lean":false},{"t":"Quantum Depletion for Fixed Bounded Repulsive Potentials","dir":"Quantum-Depletion-for-Fixed-Bounded-Repulsive-Potentials-October-5-2026","pdf":"fixed-repulsion-quantum-depletion.pdf","lean":false},{"t":"A density-uniform condensate bound for dilute Bose gases","dir":"A-density-uniform-condensate-bound-for-dilute-Bose-gases-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Ground-state condensation in the dilute hard-sphere gas","dir":"Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"268","t":"The spin-one Haldane gap","d":"Proves the spin-one Haldane gap conjecture for the pure antiferromagnetic Heisenberg chain on even periodic rings: the spectral gap stays uniformly positive as the chain grows. A companion establishes a gap for odd open chains with endpoint field h=3/5 and gives boundary-selected infinite-volume states with topological index -1.","disc":11,"tier":"A","effort":"L","widget":"Diagonalize small spin-1 Heisenberg rings live and watch the gap settle near 0.41 as the chain grows; replay the paper's exact boundary-field certificate.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The periodic spin-one Haldane gap","dir":"The-periodic-spin-one-Haldane-gap-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"A boundary-field gap for the spin-one Heisenberg chain","dir":"A-boundary-field-gap-for-the-spin-one-Heisenberg-chain-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"269","t":"The Laughlin gap and stability under scalar disorder","d":"Proves the fermionic Laughlin spectral-gap conjecture for the full V₁ interaction at filling 1/3 on the round sphere. The unique ground state remains uniformly gapped under sufficiently weak bounded real scalar one-body potentials projected to the lowest Landau level. Both the gap and disorder threshold are uniform over all sufficiently large particle numbers and all normalized potential profiles.","disc":11,"tier":"B","effort":"L","widget":"Exact-diagonalize the V1 pseudopotential for small N on the Haldane sphere, show the Laughlin ground state at zero energy and the gap, and add a random projected potential to see the gap survive.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Uniform Stability of the Spherical Laughlin Gap","dir":"Uniform-Stability-of-the-Spherical-Laughlin-Gap-October-5-2026","pdf":"uniform-stability-spherical-laughlin-gap.pdf","lean":false},{"t":"A Fock-space inequality and the Laughlin spectral gap","dir":"A-Fock-space-inequality-and-the-Laughlin-spectral-gap-September-24-2026","pdf":"A-Fock-space-inequality-and-the-Laughlin-spectral-gap-September-24-2026.pdf","lean":true}]},{"id":"270","t":"Threshold and positive-energy bound states of the BFSS model","d":"Proves that the undeformed relative SU(N) BFSS model has exactly one normalizable zero-energy state for every finite N≥2, resolving the threshold-bound-state conjecture. For SU(2), a companion proves infinitely many normalizable positive-energy eigenstates with unbounded energies, contradicting the original BFSS paper' s exclusion of additional bound states at N=2.","disc":11,"tier":"C","effort":"S","widget":"Text card on the BFSS matrix model bound states.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The unique threshold bound state of the SU(N) BFSS model","dir":"The-unique-threshold-bound-state-of-the-SU-N-BFSS-model-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Positive eigenvalues of the relative SU(2) BFSS Hamiltonian","dir":"Positive-eigenvalues-of-the-relative-SU-2-BFSS-Hamiltonian-October-5-2026","pdf":"positive-eigenvalues-relative-su2-bfss.pdf","lean":false}]},{"id":"271","t":"Bloch's law and spontaneous ferromagnetic order","d":"Proves Bloch's T^(3/2) law with its exact coefficient for three-dimensional quantum Heisenberg ferromagnets at every positive quantum spin, allowing nonnegative symmetric finite-range couplings whose support generates ℤ³. The thermodynamic limit precedes the zero-field derivative and low-temperature limit. The family also proves spontaneous magnetization for nearest-neighbor models in every dimension d≥3 and determines the first lattice correction for three-dimensional nearest-neighbor couplings.","disc":11,"tier":"B","effort":"M","widget":"Plot magnetization vs temperature for a spin-wave (magnon) model with the exact T^(3/2) Bloch coefficient overlaid.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Bloch's Law for Finite-Range Heisenberg Ferromagnets in Three Dimensions","dir":"Blochs-Law-for-Finite-Range-Heisenberg-Ferromagnets-in-Three-Dimensions-October-5-2026","pdf":"bloch-law-heisenberg.pdf","lean":false},{"t":"The first lattice correction to Bloch's law","dir":"The-first-lattice-correction-to-Blochs-law-October-5-2026","pdf":"first-lattice-correction-bloch-law.pdf","lean":false},{"t":"The spherical magnetization law for the three-dimensional quantum Heisenberg ferromagnet","dir":"The-spherical-magnetization-law-for-the-three-dimensional-quantum-Heisenberg-ferromagnet-October-5-2026","pdf":"spherical-magnetization.pdf","lean":false},{"t":"Spontaneous magnetization in the quantum Heisenberg ferromagnet","dir":"Spontaneous-magnetization-in-the-quantum-Heisenberg-ferromagnet-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"272","t":"Entanglement without secret key and the PPT-square conjecture","d":"Constructs an entangled state on ℂ¹⁰⊗ℂ¹⁰ with zero distillable secret key for the specified local-instrument protocols that complete almost surely. These allow joint local processing and authenticated two-way public communication, with no other shared private resource and an eavesdropper holding the input purification and public record. A trace-preserving PPT channel on M₂₁(ℂ) whose square is not entanglement breaking disproves Christandl' s PPT-square conjecture.","disc":11,"tier":"A","effort":"M","widget":"Explore the explicit PPT channel on 21x21 matrices and the 10x10 entangled state, checking positivity of partial transposes and the certificate that the channel's square is not entanglement breaking.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Entanglement with zero distillable secret key in local dimension ten","dir":"Entanglement-with-zero-distillable-secret-key-in-local-dimension-ten-September-27-2026","pdf":"paper.pdf","lean":false}]},{"id":"273","t":"The entropy photon-number inequality","d":"Proves the entropy photon-number inequality for beam-splitter mixing of two independent finite-energy bosonic inputs in any finite number of modes: the output' s entropy photon number is at least the transmissivity-weighted average of the inputs'. Arbitrary entanglement within each input is allowed, and product thermal inputs attain equality even when their entropies differ.","disc":11,"tier":"B","effort":"M","widget":"Mix thermal/coherent states on a beam splitter and plot output entropy photon number against the bound.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The entropy photon-number inequality","dir":"The-entropy-photon-number-inequality-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"274","t":"Moore's parity conjecture for QAC⁰","d":"Resolves Moore's parity conjecture in the measured-output model: constant-depth quantum circuits with arbitrary one-qubit gates, unbounded-arity Toffoli gates and polynomially many total qubits cannot compute parity with any fixed positive worst-case advantage. Ancillas start in zero, one output qubit is measured, and all other registers may be discarded. Xu–Li's reductions give the same bounded-error obstruction for strict majority.","disc":11,"tier":"B","effort":"M","widget":"Build small constant-depth quantum circuits with Toffoli gates and measure how well they compute parity on a few qubits.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Product-projection localization and the QAC0 parity lower bound","dir":"Product-projection-localization-and-the-QAC0-parity-lower-bound-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"Regular trajectories, pruning and quantum parity","dir":"Regular-trajectories-pruning-and-quantum-parity-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"275","t":"QMA-hardness of continuum Coulomb energy","d":"Proves QMA-hardness of approximating the electronic Coulomb energy infimum in three dimensions, minimizing over the full spinful fermionic continuum space. Deterministic polynomial-time reductions work even with only unit-charge nuclei at distinct rational positions, polynomially many electrons and an energy-threshold separation of at least one.","disc":11,"tier":"C","effort":"S","widget":"Text card on QMA-hardness of continuum Coulomb energy.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Continuum Coulomb hardness with binary nuclear charges","dir":"Continuum-Coulomb-hardness-with-binary-nuclear-charges-September-24-2026","pdf":"Continuum-Coulomb-hardness-with-binary-nuclear-charges-September-24-2026.pdf","lean":false},{"t":"QMA-hardness of continuum Coulomb energy with unit nuclear charges","dir":"QMA-hardness-of-continuum-Coulomb-energy-with-unit-nuclear-charges-September-24-2026","pdf":"QMA-hardness-of-continuum-Coulomb-energy-with-unit-nuclear-charges-September-24-2026.pdf","lean":false}]},{"id":"276","t":"The classical capacity of generalized amplitude damping","d":"Determines the unassisted classical capacity of every qubit generalized amplitude-damping channel, including all damping and thermal parameters. An explicit one-variable optimization gives the capacity, attained by independent two-state signal ensembles with collective decoding. Holevo capacity, minimum output entropy and regularized classical capacity are additive when tensoring with any finite-dimensional quantum channel.","disc":11,"tier":"A","effort":"S","widget":"Pick damping gamma and thermal population nu, see the qubit channel squash the Bloch ball, and read off the exact classical capacity from the one-variable optimization.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Classical capacity and entropy inequalities for generalized amplitude damping","dir":"Classical-capacity-and-entropy-inequalities-for-generalized-amplitude-damping-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"277","t":"Threshold repetition for entangled games","d":"Proves exponential threshold repetition for every finite two-player one-round game: if its entangled value is v<1, the probability of winning at least a fraction v+δ of k independent repetitions decays exponentially in k, for 0<δ<1-v. Arbitrary joint finite-dimensional entangled strategies and correlated question distributions are allowed.","disc":11,"tier":"B","effort":"M","widget":"Play repeated nonlocal games (e.g. CHSH) and see the tail probability of beating the entangled value decay exponentially.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Threshold parallel repetition for finite-dimensional entangled games","dir":"Threshold-parallel-repetition-for-finite-dimensional-entangled-games-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"278","t":"Failure of Kohn–Sham ensemble representation","d":"Constructs a three-electron Coulomb molecule with two equal positive-integer-charge nuclei whose absolute ground-state density has no noninteracting ground-state ensemble representation by a single real spin-independent local potential in L^(3/2)(ℝ³)+L^(∞)(ℝ³). This disproves Kohn–Sham ensemble representability for that potential class; the required nuclear charge is specified nonnumerically.","disc":11,"tier":"C","effort":"S","widget":"Text card: a 3-electron molecule whose density no Kohn-Sham potential reproduces.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Coulomb ground-state density without Kohn-Sham ensemble representation","dir":"A-Coulomb-Ground-State-Density-without-Kohn-Sham-Ensemble-Representation-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"279","t":"Exact quantum factoring over a fixed finite gate set","d":"Gives a polynomial-time uniform quantum circuit family that outputs the complete prime factorization of every integer with probability one. Both gate count and qubit count are polynomial in the input length, and one fixed finite gate set suffices.","disc":11,"tier":"B","effort":"L","widget":"Step through a small exact (probability-one) factoring circuit on a toy integer.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Exact quantum factoring over a fixed finite gate set","dir":"Exact-quantum-factoring-over-a-fixed-finite-gate-set-September-25-2026","pdf":"main.pdf","lean":false}]},{"id":"280","t":"Strong locality for strongly rational unitary vertex operator algebras","d":"Proves the strongly rational case of the strong-locality conjecture: every simple unitary strongly rational complex vertex operator algebra generates a completely rational conformal net. Its simple modules are unitarizable, and its representation category agrees with the net’s finite-index sectors as a braided unitary tensor category.","disc":11,"tier":"C","effort":"S","widget":"Card only: strong locality for strongly rational unitary VOAs.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Strongly rational unitary vertex operator algebras and conformal nets","dir":"Strongly-rational-unitary-vertex-operator-algebras-and-conformal-nets-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"281","t":"QAOA optimality for the SK model","d":"Proves that QAOA approaches the ground-state energy of the Gaussian zero-field Sherrington–Kirkpatrick model when system size tends to infinity before circuit depth. For every accuracy, finite depth and deterministic angles independent of size and disorder achieve the required limiting expected energy per spin. This also yields leading-order optimal expected MaxCut values on large-degree random regular graphs, with size tending to infinity before degree.","disc":11,"tier":"B","effort":"M","widget":"Run depth-p QAOA on small SK instances (n<=14 statevector) with fixed angles and watch energy per spin approach the Parisi value.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"QAOA attains the SK ground-state energy in the thermodynamic-first limit","dir":"QAOA-attains-the-SK-ground-state-energy-in-the-thermodynamic-first-limit-September-25-2026","pdf":"QAOA-attains-the-SK-ground-state-energy-in-the-thermodynamic-first-limit-September-25-2026.pdf","lean":false},{"t":"Full support of the zero-temperature Sherrington-Kirkpatrick order parameter","dir":"Full-support-of-the-zero-temperature-Sherrington-Kirkpatrick-order-parameter-September-27-2026","pdf":"main.pdf","lean":false}]},{"id":"282","t":"Scale-to-conformal enhancement in four-dimensional QFT","d":"Under the stated bounded-local-net and field-reconstruction hypotheses, proves that scale symmetry implies local conformal symmetry for four-dimensional unitary positive-energy theories with a discrete bounded-below scaling spectrum of finite multiplicity, finite scaling support and a physical local scale current. The stress tensor has a traceless improvement with unchanged spacetime charges. The conclusion concerns local Ward identities, not a global conformal action on the whole net.","disc":11,"tier":"C","effort":"S","widget":"Text card on scale vs conformal invariance in 4D QFT.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Scale and conformal symmetry in four-dimensional operational quantum field theory","dir":"Scale-and-conformal-symmetry-in-four-dimensional-operational-quantum-field-theory-September-26-2026","pdf":"main.pdf","lean":false}]},{"id":"283","t":"Polynomial-time, constant-error unitary synthesis from a Boolean oracle","d":"Solves the constant-error Aaronson–Kuperberg unitary synthesis problem: a uniform polynomial-size quantum oracle circuit approximates every n-qubit unitary channel within diamond-norm error 1/2, after a suitable Boolean oracle is chosen. Gates, qubits, oracle calls and query length are polynomially bounded. The target-dependent oracle may have an unrestricted truth table; its efficient classical construction is not asserted.","disc":11,"tier":"C","effort":"S","widget":"Text card on unitary synthesis from Boolean oracles.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Polynomial-Time Unitary Synthesis from a Boolean Oracle","dir":"Polynomial-Time-Unitary-Synthesis-from-a-Boolean-Oracle-October-5-2026","pdf":"paper.pdf","lean":false}]},{"id":"284","t":"The optimal randomized–quantum query exponent","d":"Shows that the universal bound R(f)=O((1+Q(f))⁴) for total Boolean functions is sharp in its exponent, ruling out every smaller power and disproving the conjectured cubic relation. Here R and Q are randomized and quantum worst-case bit-query complexities with error at most 1/3; computation between queries is unrestricted.","disc":11,"tier":"C","effort":"S","widget":"Text card on the quartic randomized-quantum query separation.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Nearly Quartic Separation Between Randomized and Quantum Query Complexity","dir":"A-Nearly-Quartic-Separation-Between-Randomized-and-Quantum-Query-Complexity-October-5-2026","pdf":"quartic-query-separation.pdf","lean":false}]},{"id":"285","t":"Counterexamples to Baum–Connes and Kadison–Kaplansky","d":"Disproves the coefficient-free reduced Baum–Connes conjecture through a failure of rational injectivity and a separate failure of surjectivity of assembly. A finitely generated torsion-free example witnesses the injectivity failure. Separately, a torsion-free group has a nontrivial projection in its reduced group C*-algebra, disproving the Kadison–Kaplansky conjecture.","disc":12,"tier":"C","effort":"S","widget":"Card on Baum-Connes and Kadison-Kaplansky counterexamples.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"A torsion-free counterexample to reduced Baum–Connes injectivity","dir":"A-Torsion-Free-Counterexample-to-Reduced-Baum-Connes-Injectivity-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"A torsion-free counterexample to the Kadison–Kaplansky projection conjecture","dir":"A-Torsion-Free-Counterexample-to-the-Kadison-Kaplansky-Projection-Conjecture-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"An irrational-trace counterexample to reduced Baum–Connes","dir":"An-Irrational-Trace-Counterexample-to-Reduced-Baum-Connes-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"286","t":"Arithmetic rigidity of lattice von Neumann algebras","d":"Classifies finite-index bimodules between scalar-twisted group factors of ICC groups commensurable with property-(T) lattices over characteristic-zero local fields and arbitrary ICC group factors. Every such bimodule is a summand of finite sums of models arising from finite-index subgroup isomorphisms and finite-dimensional projective representations. The classification also recovers the group, scalar cocycle and amplification scale up to the stated stable equivalence.","disc":12,"tier":"C","effort":"S","widget":"Card only: arithmetic rigidity of lattice von Neumann algebras.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Arithmeticity of twisted finite correspondences for lattices over local fields","dir":"Arithmeticity-of-twisted-finite-correspondences-for-lattices-over-local-fields-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"The arithmetic category and stable recovery of lattice factors","dir":"The-arithmetic-category-and-stable-recovery-of-lattice-factors-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"287","t":"All nonabelian free group factors are isomorphic","d":"Resolves the free group factor isomorphism problem: L(𝔽₂)≅ L(𝔽₃), and hence all interpolated free group factors, including L(𝔽_∞), are isomorphic. Their common factor has fundamental group ℝ_(>0).","disc":12,"tier":"C","effort":"S","widget":"Text card: L(F2) is isomorphic to L(F3).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An isomorphism of the free group factors","dir":"An-isomorphism-of-the-free-group-factors-September-23-2026","pdf":"An-isomorphism-of-the-free-group-factors-September-23-2026.pdf","lean":false}]},{"id":"288","t":"Kadison's similarity conjecture","d":"Proves Kadison's similarity conjecture: every bounded complex-linear unital algebra homomorphism from a unital complex C*-algebra to operators on a Hilbert space becomes a *-homomorphism after conjugation by a bounded invertible operator.","disc":12,"tier":"C","effort":"S","widget":"Text card on Kadison's similarity problem.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Kadison's similarity theorem through uniform derivation estimates","dir":"Kadisons-similarity-theorem-through-uniform-derivation-estimates-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"289","t":"The strong Kadison–Kastler conjecture","d":"Proves that sufficiently close unital von Neumann algebras on the same Hilbert space are conjugate by a unitary arbitrarily close to the identity, with a universal tolerance in the operator-norm distance between unit balls. Counterexamples show that near-identity conjugacy fails for one-sided near inclusions, and that arbitrarily close norm-separable C*-algebras need not be ambiently unitarily conjugate.","disc":12,"tier":"C","effort":"S","widget":"Text card on Kadison–Kastler stability.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Universal strong Kadison–Kastler stability","dir":"Universal-strong-Kadison-Kastler-stability-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Near Inclusions of von Neumann Algebras Without Small Spatial Embeddings","dir":"Near-Inclusions-of-von-Neumann-Algebras-Without-Small-Spatial-Embeddings-October-5-2026","pdf":"near-inclusions.pdf","lean":false},{"t":"Close Separable C*-Algebras Without Spatial Conjugacy","dir":"Close-Separable-Cstar-Algebras-Without-Spatial-Conjugacy-October-5-2026","pdf":"paper.pdf","lean":false}]},{"id":"290","t":"Connes' bicentralizer conjecture and relative bicentralizers","d":"Proves Connes' bicentralizer conjecture for every type III₁ factor with separable predual and every faithful normal state. More generally, for every inclusion N⊂ M of von Neumann algebras with separable preduals admitting a faithful normal conditional expectation, constructs an amenable expected subalgebra P⊂ N with P'∩ c(M)=N'∩ c(M), resolving the relative bicentralizer conjecture.","disc":12,"tier":"C","effort":"S","widget":"Text card on Connes' bicentralizer conjecture.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Expected amenable subalgebras preserving core commutants","dir":"Expected-amenable-subalgebras-preserving-core-commutants-September-23-2026","pdf":"Expected-amenable-subalgebras-preserving-core-commutants-September-23-2026.pdf","lean":false},{"t":"Bounded recovery for modular spectral averages","dir":"Bounded-recovery-for-modular-spectral-averages-September-23-2026","pdf":"Bounded-recovery-for-modular-spectral-averages-September-23-2026.pdf","lean":true}]},{"id":"291","t":"Toms–Winter and equivariant Jiang–Su stability","d":"Proves equivariant Jiang–Su stability for every countable discrete amenable group action on a simple separable unital infinite-dimensional nuclear stably finite Jiang–Su-stable C*-algebra, resolving this case of Szabó's conjecture without restrictions on trace dynamics. The family also proves the unital Toms–Winter conjecture, equating strict comparison, finite nuclear dimension and Jiang–Su stability in the simple separable unital infinite-dimensional nuclear setting.","disc":12,"tier":"C","effort":"S","widget":"Card on Jiang-Su stability and Toms-Winter.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Equivariant Jiang–Su Stability for Amenable Actions in the Unital Stably Finite Case","dir":"Equivariant-Jiang-Su-Stability-for-Amenable-Actions-in-the-Unital-Stably-Finite-Case-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Cuntz comparison and Jiang–Su absorption","dir":"Cuntz-comparison-and-Jiang-Su-absorption-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Nuclear dimension and Jiang–Su stability without elementary subquotients","dir":"Nuclear-dimension-and-Jiang-Su-stability-without-elementary-subquotients-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Tracial projection methods and uniform property Gamma","dir":"Tracial-projection-methods-and-uniform-property-Gamma-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"292","t":"A counterexample to Kirchberg's norm-ultrapower embedding problem","d":"Constructs an explicit separable unital full group C*-algebra that cannot embed unitally into the norm ultrapower of any fixed nonzero unital nuclear C*-algebra, for any free ultrafilter on the natural numbers. Taking the target to be 𝒪₂ answers Kirchberg's norm-ultrapower embedding problem negatively.","disc":12,"tier":"C","effort":"S","widget":"Card only: Kirchberg's norm-ultrapower embedding problem answered negatively.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An explicit obstruction to nuclear norm-ultrapower embeddings","dir":"An-explicit-obstruction-to-nuclear-norm-ultrapower-embeddings-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"293","t":"A counterexample to the hyperinvariant-subspace problem","d":"Constructs a nonzero norm-quasinilpotent operator on every infinite-dimensional separable complex Hilbert space with no nonzero proper closed subspace invariant under every commuting operator. The construction also gives operators with no nontrivial invariant projection in the hyperfinite type II₁ factor.","disc":12,"tier":"C","effort":"S","widget":"Text card on the hyperinvariant-subspace counterexample.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Invariant-projection counterexamples for every irrational rotation","dir":"Invariant-projection-counterexamples-for-every-irrational-rotation-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"Backward intertwiners and a transitive commutant","dir":"Backward-intertwiners-and-a-transitive-commutant-September-27-2026","pdf":"paper.pdf","lean":true}]},{"id":"294","t":"A counterexample to Kaplansky's quasitrace conjecture","d":"Disproves Kaplansky's quasitrace conjecture by constructing a separable unital complex C*-algebra admitting normalized 2-quasitraces, all of which are nonadditive. As a consequence, two unital simple stably finite C*-algebras can have a properly infinite minimal tensor product, with one factor Cᵣ*(𝔽₂).","disc":12,"tier":"C","effort":"S","widget":"Text card on quasitraces on C*-algebras.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A counterexample to Kaplansky's quasitrace conjecture and failure of tensor-product stable finiteness","dir":"A-counterexample-to-Kaplanskys-quasitrace-conjecture-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"295","t":"The Kadison–Ringrose cohomology conjecture","d":"Proves that every bounded Hochschild cocycle of degree at least two on a complex von Neumann algebra, with coefficients in the algebra itself, has a bounded primitive. Equivalently, all higher bounded Hochschild cohomology groups vanish, resolving the Kadison–Ringrose conjecture.","disc":12,"tier":"C","effort":"S","widget":"Text card on bounded Hochschild cohomology of von Neumann algebras.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Vanishing of higher bounded Hochschild cohomology","dir":"Vanishing-of-higher-bounded-Hochschild-cohomology-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"296","t":"The generator problem for finite factors","d":"Proves that every type II₁ factor with separable predual is generated by a single operator, equivalently by two self-adjoint operators, resolving the generator problem. More strongly, for every irreducible inclusion P⊂ M of such factors, the unitaries u with M=W*(P,u) form a dense G_δ subset in the trace 2-norm topology.","disc":12,"tier":"C","effort":"S","widget":"Text card on single-generator II₁ factors.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Relative generation and the generator problem for finite factors","dir":"Relative-generation-and-the-generator-problem-for-finite-factors-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"297","t":"A ZFC counterexample to Naimark's problem","d":"Gives an alternative to Tanaka's ZFC construction of a unital infinite-dimensional simple complex C*-algebra with a faithful tracial state and exactly one nonzero irreducible representation up to unitary equivalence. Thus the unrestricted compact-operator characterization fails without additional set-theoretic assumptions; the counterexample is nonseparable.","disc":12,"tier":"C","effort":"S","widget":"Card on Naimark's problem.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A counterexample to Naimark's problem in ZFC","dir":"A-counterexample-to-Naimarks-problem-in-ZFC-September-24-2026","pdf":"naimark-counterexample-zfc.pdf","lean":false}]},{"id":"298","t":"A counterexample to Voiculescu’s free-entropy equality conjecture","d":"Constructs a bounded self-adjoint tuple in a tracial von Neumann algebra whose microstates and nonmicrostates free entropies satisfy -∞<χ<χ*<∞. This answers Voiculescu’s finite-entropy equality question negatively: the matrix-approximation and free-Fisher-information definitions differ even when both are finite.","disc":12,"tier":"C","effort":"S","widget":"Card only: microstates and nonmicrostates free entropies differ.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A finite-entropy separation of microstates and nonmicrostates free entropy","dir":"A-finite-entropy-separation-of-microstates-and-nonmicrostates-free-entropy-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"299","t":"The Kirchberg–Rø rdam character criterion","d":"A nonzero unital separable complex C*-algebra is Jiang–Su stable exactly when its norm central-sequence algebra has no characters, for every free ultrafilter. This answers the Kirchberg–Rø rdam character question. Also, the infinite minimal tensor power of every such algebra without characters is Jiang–Su stable, answering the Dadarlat–Toms question.","disc":12,"tier":"C","effort":"S","widget":"Text card on the Kirchberg–Rordam character criterion.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The Kirchberg–Rørdam character criterion","dir":"The-Kirchberg-Rordam-character-criterion-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"300","t":"The Popa–Vaes quadratic strong-operator paving conjecture","d":"Proves that every self-adjoint element of a complex von Neumann algebra admits strong-operator paving relative to any maximal abelian subalgebra with O(ε⁻²) blocks. The norm bound holds after compression by a projection arbitrarily close to the identity in the strong topology, resolving the Popa–Vaes quadratic paving conjecture.","disc":12,"tier":"C","effort":"S","widget":"Text card on paving in von Neumann algebras.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Approximation Paving over Arbitrary Maximal Abelian Subalgebras","dir":"Approximation-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026","pdf":"Approximation-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026.pdf","lean":false},{"t":"Quadratic Strong-Operator Paving over Arbitrary Maximal Abelian Subalgebras","dir":"Quadratic-Strong-Operator-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026","pdf":"Quadratic-Strong-Operator-Paving-over-Arbitrary-Maximal-Abelian-Subalgebras-September-25-2026.pdf","lean":false}]},{"id":"301","t":"Classification by trace cones after Razak–Jacelon stabilization","d":"Classifies separable nuclear complex C*-algebras after tensoring with the Razak–Jacelon algebra and the compact operators, using their full topological cones of extended lower-semicontinuous tracial weights. This answers Robert’s trace-cone question, including algebras with arbitrary ideal structure and both finite and infinite subquotients.","disc":12,"tier":"C","effort":"S","widget":"Text card on classification of C*-algebras by trace cones.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The trace cone classifies Razak–Jacelon stabilizations","dir":"The-trace-cone-classifies-Razak-Jacelon-stabilizations-September-25-2026","pdf":"The-trace-cone-classifies-Razak-Jacelon-stabilizations-September-25-2026.pdf","lean":false}]},{"id":"302","t":"The Phillips–Toms formula for minimal integer actions","d":"For every minimal homeomorphism h of an infinite compact metrizable space X, the radius of comparison of C(X)⋊ₕℤ equals 1/2mdim(X,h), including infinite values. Zero mean dimension is equivalent to the small boundary property, Jiang–Su stability and finite nuclear dimension; in this case nuclear dimension is at most one.","disc":12,"tier":"C","effort":"S","widget":"Text card on radius of comparison = half mean dimension.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Filtered products and boundary-preserving compression in complex cobordism","dir":"Filtered-products-and-boundary-preserving-compression-in-complex-cobordism-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Radius of comparison equals half the mean dimension","dir":"Radius-of-comparison-equals-half-the-mean-dimension-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"303","t":"From ordinary to strong pure infiniteness","d":"Resolves the ordinary-to-strong pure-infiniteness question of Kirchberg and Rørdam for complex C*-algebras. For exact algebras, proper infiniteness of one fixed finite amplification of every positive element also suffices. Consequently, every separable nuclear algebra with this property absorbs 𝒪_∞, without unitality or simplicity assumptions.","disc":12,"tier":"C","effort":"S","widget":"Card on pure infiniteness of C*-algebras.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Weak pure infiniteness and O-infinity absorption","dir":"Weak-pure-infiniteness-and-O-infinity-absorption-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"304","t":"The Hilbert–Smith conjecture in every dimension","d":"Every locally compact second-countable Hausdorff group acting faithfully and jointly continuously on a connected finite-dimensional topological manifold is a Lie group. This proves the Hilbert–Smith conjecture in all finite dimensions, for Hausdorff second-countable manifolds without boundary.","disc":13,"tier":"C","effort":"S","widget":"Card only: Hilbert-Smith conjecture.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Hilbert–Smith conjecture in every finite dimension","dir":"The-Hilbert-Smith-conjecture-in-every-finite-dimension-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"305","t":"Counterexamples to disk embedding and Wall's manifold conjecture","d":"The unrestricted four-dimensional disk-embedding conjecture fails: framed algebraic dual spheres do not suffice to obtain disjoint locally flat spanning disks. In particular, the free group F₂ is not good in the sense of Freedman–Quinn. Also constructs a finitely presented integral Poincaré duality group of dimension four with a finite classifying space but no realization as the fundamental group of a closed aspherical topological four-manifold, disproving Wall's conjecture.","disc":13,"tier":"C","effort":"S","widget":"Text card on disk-embedding failure and PD4 groups.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A boundary-only obstruction to four-dimensional disk embedding","dir":"A-boundary-only-obstruction-to-four-dimensional-disk-embedding-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"A marked tensor obstruction to four-dimensional disk embedding","dir":"A-marked-tensor-obstruction-to-four-dimensional-disk-embedding-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"A PD4 group without an aspherical manifold model","dir":"A-PD4-group-without-an-aspherical-manifold-model-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"306","t":"The purely cosmetic surgery conjecture for knots in S³","d":"Distinct Dehn surgery slopes on a nontrivial smooth knot in S³ never produce orientation-preservingly homeomorphic manifolds, proving the purely cosmetic surgery conjecture. The statement includes the meridional slope.","disc":13,"tier":"C","effort":"S","widget":"Text card on cosmetic Dehn surgery.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Purely cosmetic surgery on knots in the three-sphere","dir":"Purely-Cosmetic-Surgery-on-Knots-in-the-Three-Sphere-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"307","t":"Failure of rational injectivity for maximal coarse assembly","d":"Constructs a uniformly discrete bounded-geometry space whose maximal coarse assembly map is not rationally injective. The example is a coarse disjoint union of finite connected graphs of uniformly bounded degree, with an infinite-order kernel class. A companion gives the analogous failure for reduced coarse assembly, disproving the rational coarse Novikov conjecture.","disc":13,"tier":"C","effort":"S","widget":"Text card on coarse assembly maps and expander-type graph sequences.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Failure of rational injectivity for maximal coarse assembly","dir":"Failure-of-rational-injectivity-for-maximal-coarse-assembly-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"A counterexample to the coarse Novikov conjecture","dir":"A-counterexample-to-the-coarse-Novikov-conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"308","t":"Smith–Toda complexes at every height with varying primes","d":"For every n≥0, constructs a finite Smith–Toda spectrum at a prime p depending on n, with Brown–Peterson homology BP_*/(p,v₁,…,vₙ) and the canonical comodule structure. Thus Smith–Toda complexes exist at every height when the prime may vary; an explicit example realizes V(4) at p=1009.","disc":13,"tier":"C","effort":"S","widget":"Text card on Smith-Toda complexes, including V(4) at p=1009.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Finite Smith–Toda Complexes at Varying Primes","dir":"Finite-Smith-Toda-Complexes-at-Varying-Primes-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"A finite Smith–Toda complex V(4) at the prime 1009","dir":"A-finite-Smith-Toda-complex-V4-at-the-prime-1009-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"309","t":"The Kervaire invariant problem at the prime three","d":"Resolves the odd-primary Kervaire invariant problem at the prime three: exactly the standard classes with indices 0, 2, and 3 survive in the mod-three Adams spectral sequence, in stems 10, 106, and 322. Each surviving detection coset contains an element of exact additive order three.","disc":13,"tier":"C","effort":"S","widget":"Card (optionally a static Adams chart) marking stems 10, 106, 322.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Kervaire invariant problem at the prime three","dir":"The-Kervaire-Invariant-Problem-at-the-Prime-Three-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"310","t":"Quillen's conjecture in rational homology","d":"Proves the rational-homology form of Quillen's conjecture for every finite group and every prime. If the largest normal p-subgroup of G is trivial, the poset of nontrivial elementary abelian p-subgroups has nonzero augmented reduced rational homology and is therefore not contractible.","disc":13,"tier":"B","effort":"M","widget":"Choose a small finite group and prime p, build the poset of elementary abelian p-subgroups, and compute its rational homology.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Rational homology and Quillen's conjecture","dir":"Rational-homology-and-Quillens-conjecture-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"311","t":"Chai's invariant-ideal conjecture","d":"Proves Chai's invariant-ideal conjecture for Lubin–Tate deformation rings over finite residue fields, at every prime and positive height n. Through the implication of Barthel–Heard–Naumann, this proves the Hovey–Strickland conjecture: dualizable K(n)-local spectra have exactly n+2 thick tensor ideals, and their Balmer spectrum is a chain of n+1 points.","disc":13,"tier":"C","effort":"S","widget":"Text card on Chai's conjecture and K(n)-local thick ideals.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Stabilizer orbits and thick tensor ideals of dualizable K(n)-local spectra","dir":"Stabilizer-Orbits-and-Thick-Tensor-Ideals-of-Dualizable-Kn-Local-Spectra-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"312","t":"The Grothendieck homotopy hypothesis","d":"Proves the Grothendieck homotopy hypothesis for ∞-groupoids associated with every Grothendieck coherator in the Ara–Henry convention: these algebraic objects recover the homotopy theory of spaces.","disc":13,"tier":"C","effort":"S","widget":"Text card on Grothendieck's homotopy hypothesis.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The Grothendieck homotopy hypothesis via elementary expansions","dir":"The-Grothendieck-homotopy-hypothesis-via-elementary-expansions-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"313","t":"Finite generation for the K(n)-local sphere","d":"Answers the degreewise finiteness question of Hovey and Hovey–Strickland: every homotopy group of the K(n)-local sphere is a finitely generated ℤₚ-module, for every prime, positive height and integer degree. The same conclusion holds after K(n)-localizing any finite p-local spectrum.","disc":13,"tier":"C","effort":"S","widget":"Text card on the K(n)-local sphere.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Finite generation for the K(n)-local sphere","dir":"Finite-generation-for-the-Kn-local-sphere-September-24-2026","pdf":"Finite-generation-for-the-Kn-local-sphere-September-24-2026.pdf","lean":false}]},{"id":"314","t":"The chromatic Smith fixed-point problem for finite p-groups","d":"Determines the optimal chromatic loss from geometric H-fixed points to geometric G-fixed points for every subgroup H of a finite p-group G. At every nonnegative height, the loss equals the shortest subnormal-chain length from H to G with cyclic quotients. Each quotient counts once regardless of order, and finite spectra witness sharpness.","disc":13,"tier":"C","effort":"S","widget":"Text card on chromatic Smith fixed-point loss for p-groups.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Cyclic length and chromatic fixed-point loss","dir":"Cyclic-Length-and-Chromatic-Fixed-Point-Loss-September-24-2026","pdf":"Cyclic-Length-and-Chromatic-Fixed-Point-Loss-September-24-2026.pdf","lean":false}]},{"id":"315","t":"The four-dimensional Singer conjecture","d":"Proves that the L²-Betti numbers of the universal cover of every closed connected aspherical topological four-manifold vanish outside degree two. More generally, the same conclusion holds for every finite connected aspherical integral Poincaré complex of formal dimension four, proving the four-dimensional Singer conjecture in this wider class.","disc":13,"tier":"C","effort":"S","widget":"Card on L²-Betti numbers of aspherical 4-manifolds.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Singer conjecture in dimension four","dir":"The-Singer-conjecture-in-dimension-four-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"316","t":"Curtis’s conjecture","d":"Proves Curtis’s conjecture: the positive-degree mod-two stable Hurewicz image of the sphere is spanned by the images of the Hopf-invariant-one classes η,ν,σ and the Kervaire-invariant-one classes that exist.","disc":13,"tier":"C","effort":"S","widget":"Card only: Curtis's conjecture on the stable Hurewicz image.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Stable Hurewicz Image of the Sphere at Two","dir":"The-Stable-Hurewicz-Image-of-the-Sphere-at-Two-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"317","t":"Thomason model structures in every strict higher dimension","d":"Resolves the Ara–Maltsiniotis conjecture: for every n≥1 and n=ω, small strict globular n-categories admit proper combinatorial Thomason model structures Quillen equivalent to simplicial sets. Thus strict higher categories model the homotopy theory of spaces in every stated dimension.","disc":13,"tier":"C","effort":"S","widget":"Text card on Thomason model structures on strict n-categories.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Thomason Model Structures in Every Strict Higher Dimension","dir":"Thomason-Model-Structures-in-Every-Strict-Higher-Dimension-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"318","t":"Chromatic splitting: counterexamples and filtrations","d":"Disproves strong chromatic splitting at height three for primes p≥5, and weak splitting for the derived p-completed sphere at heights p (p≥5) and p+1 (p≥7). Nevertheless, for n≥1 and p>n+1, the overlap Lₙ₋₁L_(K(n))Sₚ^(∧) admits a 2ⁿ-stage filtration by the predicted localized-sphere pieces. At height three and prime three, even finite assembly from such pieces fails in the category of E(2)-local modules over the derived completed sphere.","disc":13,"tier":"C","effort":"S","widget":"Text card on chromatic splitting in stable homotopy theory.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Filtered chromatic splitting at generic primes","dir":"Filtered-chromatic-splitting-at-generic-primes-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"The height-three chromatic overlap: an explicit filtration and its attachments","dir":"The-height-three-chromatic-overlap-an-explicit-filtration-and-its-attachments-September-27-2026","pdf":"paper.pdf","lean":false},{"t":"A rational obstruction to strong chromatic splitting at height three","dir":"A-rational-obstruction-to-strong-chromatic-splitting-at-height-three-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Failure of finite assembly for a chromatic overlap at the prime three","dir":"Failure-of-finite-assembly-for-a-chromatic-overlap-at-the-prime-three-September-25-2026","pdf":"paper.pdf","lean":false},{"t":"Counterexamples to weak chromatic splitting: sphere kernels and descent exponents","dir":"Counterexamples-to-weak-chromatic-splitting-sphere-kernels-and-descent-exponents-September-27-2026","pdf":"paper.pdf","lean":false}]},{"id":"319","t":"Counterexamples to the Hahn–Wilson conjecture at height two","d":"Refutes the Hahn–Wilson conjecture at chromatic height two. For every sufficiently large prime p, constructs a connective p-complete spectrum of exact fp-type two that cannot be built from completed BP⟨2⟩ by finitely many sums, shifts, cones and retracts. The examples nevertheless satisfy the finite and telescopic localization comparisons.","disc":13,"tier":"C","effort":"S","widget":"Text card on chromatic height-two spectra.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Counterexamples to the Hahn-Wilson conjecture at height two","dir":"Counterexamples-to-the-Hahn-Wilson-conjecture-at-height-two-September-26-2026","pdf":"paper.pdf","lean":false}]},{"id":"320","t":"A four-dimensional counterexample to Borel rigidity","d":"Constructs closed connected aspherical topological four-manifolds that are homotopy equivalent but not homeomorphic, with a common word-hyperbolic fundamental group. This disproves even the homeomorphism-existence formulation of the Borel conjecture in dimension four.","disc":13,"tier":"C","effort":"S","widget":"Text card on homotopy-equivalent non-homeomorphic aspherical 4-manifolds.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Nonhomeomorphic closed aspherical four-manifolds with the same homotopy type","dir":"Nonhomeomorphic-closed-aspherical-four-manifolds-with-the-same-homotopy-type-October-4-2026","pdf":"paper.pdf","lean":false}]},{"id":"321","t":"A counterexample to Wall's finite D(2) conjecture","d":"Constructs a finite connected three-dimensional CW complex whose universal cover has no integral homology above degree two and whose third cohomology vanishes for every local coefficient module, but which has no finite two-dimensional homotopy model. This disproves Wall's finite D(2) conjecture; the example has infinite fundamental group.","disc":13,"tier":"C","effort":"S","widget":"Card on Wall's D(2) problem with the explicit presentation.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Counterexample to Wall's D(2) Problem","dir":"A-Counterexample-to-Walls-D2-Problem-October-6-2026","pdf":"wall-d2-counterexample.pdf","lean":false}]},{"id":"322","t":"Tingley's sphere-isometry problem","d":"Resolves Tingley's problem: every surjective isometry between the unit spheres of nonzero real Banach spaces extends uniquely to a surjective real-linear isometry of the whole spaces. No dimension restriction is imposed, so the metric geometry of the unit sphere determines the Banach space up to linear isometry.","disc":14,"tier":"C","effort":"S","widget":"Card only: Tingley's sphere-isometry problem.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A positive solution to Tingley’s problem","dir":"A-positive-solution-to-Tingleys-problem-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"323","t":"Relative independence of the separable quotient problem","d":"Establishes, relative to the consistency of a measurable cardinal, that the separable quotient problem is independent of ZFC. The assertion that every infinite-dimensional Banach space has a separable infinite-dimensional quotient can hold for all real and complex Banach spaces, whereas the continuum hypothesis yields counterexamples over both fields.","disc":14,"tier":"C","effort":"S","widget":"Text card on independence of the separable quotient problem.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Relative independence of the separable quotient problem","dir":"Relative-independence-of-the-separable-quotient-problem-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"324","t":"Lipschitz equivalence without linear isomorphism","d":"Constructs separable real Banach spaces that are globally bi-Lipschitz equivalent but not linearly isomorphic, resolving the separable Lipschitz-isomorphism problem negatively. Thus even the complete metric structure up to bi-Lipschitz equivalence does not determine a separable Banach space's linear isomorphism class.","disc":14,"tier":"C","effort":"S","widget":"Text card on Lipschitz vs linear isomorphism of Banach spaces.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Lipschitz Equivalent Separable Banach Spaces Need Not Be Linearly Isomorphic","dir":"Lipschitz-Equivalent-Separable-Banach-Spaces-Need-Not-Be-Linearly-Isomorphic-September-24-2026","pdf":"paper.pdf","lean":true},{"t":"Bi-Lipschitz Absorption of c0 Without a Linear Copy of c0","dir":"Bi-Lipschitz-Absorption-of-c0-Without-a-Linear-Copy-of-c0-September-26-2026","pdf":"paper.pdf","lean":true}]},{"id":"325","t":"The complete Crouzeix conjecture","d":"Resolves the complete Crouzeix conjecture: for every bounded operator A on a complex Hilbert space and every finite matrix-valued polynomial P, one has ‖ P[A]‖≤2sup_(z∈ W(A))‖ P(z)‖, where W(A) is the numerical range. The constant 2 is sharp, independent of the matrix size, and valid in infinite dimensions.","disc":14,"tier":"A","effort":"M","widget":"Type or drag a matrix, see its numerical range, and test random (matrix-valued) polynomials: ||p(A)|| never exceeds 2 sup_(W(A))||p||; the 2x2 Jordan block shows the constant is sharp.","related":[],"conj":true,"page":null,"lean":2,"papers":[{"t":"A direct proof of the complete Crouzeix inequality","dir":"A-direct-proof-of-the-complete-Crouzeix-inequality-September-26-2026","pdf":"paper.pdf","lean":true},{"t":"The complete Crouzeix theorem: optimal similarity and a common positive boundary representation","dir":"The-complete-Crouzeix-theorem-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"326","t":"The cotype–cotype conjecture under the approximation property","d":"Resolves the cotype–cotype conjecture for real Banach spaces with the approximation property. Such a nonzero space is K-convex if and only if both it and its dual have finite Rademacher cotype, with possibly different exponents. Equivalently, these cotype assumptions force nontrivial Rademacher type.","disc":14,"tier":"C","effort":"S","widget":"Text card on the cotype-cotype conjecture.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The cotype–cotype conjecture under the approximation property","dir":"The-cotype-cotype-conjecture-under-the-approximation-property-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"327","t":"Markov type characterizes superreflexivity","d":"Proves that every real Banach space with Markov type p for some p>1 admits an equivalent uniformly convex norm, answering Naor's renorming question. Together with the known converse, this characterizes superreflexivity by nontrivial Markov type.","disc":14,"tier":"C","effort":"S","widget":"Card on Markov type and uniform convexity.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Nontrivial Markov Type Forces Superreflexivity","dir":"Nontrivial-Markov-Type-Forces-Superreflexivity-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"328","t":"Fixed points of nonexpansive maps in reflexive Banach spaces","d":"Resolves Kirk's reflexive-space fixed-point problem: every nonexpansive selfmap of a nonempty closed bounded convex subset of a real reflexive Banach space has a fixed point. The result uses the original norm, without assuming uniform convexity.","disc":14,"tier":"C","effort":"S","widget":"Card only: fixed points of nonexpansive maps in reflexive Banach spaces.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Fixed Points of Nonexpansive Maps in Reflexive Banach Spaces","dir":"Fixed-Points-of-Nonexpansive-Maps-in-Reflexive-Banach-Spaces-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"329","t":"A counterexample to Pietsch's metric-entropy duality conjecture","d":"Disproves Pietsch's dimension-free duality conjecture for metric entropy. Origin-symmetric convex bodies violate every proposed choice of universal constants in the conjectured comparison between covering numbers and those of the polar bodies, even when the covering body is a cube.","disc":14,"tier":"C","effort":"S","widget":"Text card on Pietsch's metric-entropy duality counterexample.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Counterexamples to the duality conjecture for metric entropy","dir":"Counterexamples-to-the-duality-conjecture-for-metric-entropy-September-24-2026","pdf":"main.pdf","lean":true}]},{"id":"330","t":"A negative answer to Kalton's Lipschitz-free approximation question","d":"Constructs a countable uniformly discrete metric space whose real Lipschitz-free Banach space has the approximation property but not the bounded approximation property, answering Kalton's question negatively. Finite-rank operators approximate the identity on every compact set, but their norms cannot share a finite bound.","disc":14,"tier":"C","effort":"S","widget":"Text card on Lipschitz-free spaces and the bounded approximation property.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A uniformly discrete counterexample to bounded approximation in Lipschitz-free spaces","dir":"Failure-of-Bounded-Approximation-in-a-Lipschitz-Free-Space-over-a-Uniformly-Discrete-Metric-Space-September-26-2026","pdf":"main.pdf","lean":false}]},{"id":"331","t":"Asymptotic midpoint uniform convexity without asymptotically uniformly convex renorming","d":"Constructs a real reflexive Banach space with an asymptotically midpoint uniformly convex norm but no equivalent asymptotically uniformly convex norm, extending Baudier's separation to reflexive spaces. In the same space, depth-k countably branching diamonds require distortion at least √(1+k/12), so midpoint uniform convexity does not force uniformly bounded diamond distortion even under reflexivity.","disc":14,"tier":"C","effort":"S","widget":"Text card on asymptotic uniform convexity and diamond distortion.","related":[],"conj":false,"page":null,"lean":7,"papers":[{"t":"Asymptotic midpoint uniform convexity and unbounded diamond distortion in a reflexive tree space","dir":"Asymptotic-midpoint-uniform-convexity-and-unbounded-diamond-distortion-in-a-reflexive-tree-space-September-27-2026","pdf":"manuscript.pdf","lean":true},{"t":"Midpoint lenses in segment spaces","dir":"Midpoint-lenses-in-segment-spaces-September-27-2026","pdf":"manuscript.pdf","lean":true},{"t":"Distortion of countably branching diamonds from midpoint and tree energies","dir":"Diamond-distortion-from-midpoint-and-tree-energies-September-27-2026","pdf":"manuscript.pdf","lean":true},{"t":"Exact asymptotic moduli in a Daugavet subspace of L1","dir":"Exact-asymptotic-moduli-in-a-Daugavet-subspace-of-L1-September-27-2026","pdf":"manuscript.pdf","lean":true},{"t":"Midpoint convexity from bounded tree potentials and path costs","dir":"Midpoint-convexity-from-bounded-tree-potentials-and-path-costs-September-27-2026","pdf":"manuscript.pdf","lean":true},{"t":"Independent products in real L1: asymptotic midpoint convexity without AUC renormings","dir":"Independent-products-in-real-L1-asymptotic-midpoint-convexity-without-AUC-renormings-September-27-2026","pdf":"manuscript.pdf","lean":true},{"t":"Midpoint convexity from two recursive potentials","dir":"Midpoint-convexity-from-two-recursive-potentials-September-27-2026","pdf":"manuscript.pdf","lean":true}]},{"id":"332","t":"Metric Markov cotype two for ℓ₁","d":"Proves that real ℓ₁ has metric Markov cotype two, answering Mendel and Naor's question. Consequently, every Lipschitz map from an arbitrary subset of a real Hilbert space into ℓ₁ extends to the whole space with a universal multiplicative loss in its Lipschitz constant, resolving Ball's extension problem for this target.","disc":14,"tier":"C","effort":"S","widget":"Text card on metric Markov cotype two for l₁ and Lipschitz extension.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Metric Markov Cotype Two of ℓ₁ ","dir":"Metric-Markov-Cotype-Two-of-l1-October-5-2026","pdf":"l1-markov-cotype.pdf","lean":false}]},{"id":"333","t":"Smooth isometric immersions of surfaces into ℝ⁴","d":"Every closed smooth Riemannian surface admits a smooth isometric immersion into ℝ⁴, resolving the closed-surface form of the four-dimensional isometric-immersion problem. This includes nonorientable surfaces and metrics of arbitrary Gaussian curvature.","disc":15,"tier":"B","effort":"M","widget":"Show isometric immersions of flat tori/Klein bottles into R⁴ via rotating 3D projections.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Smooth isometric immersions of closed surfaces into Euclidean four-space","dir":"Smooth-isometric-immersions-of-closed-surfaces-into-Euclidean-four-space-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"334","t":"A smooth surface metric with no local immersion in ℝ³","d":"Constructs a smooth positive-definite metric on (-1,1)² for which no neighborhood of the origin admits a smooth isometric immersion into ℝ³. This answers the unrestricted smooth local isometric realization problem for surfaces negatively, even after shrinking the neighborhood.","disc":15,"tier":"C","effort":"S","widget":"Card only: a smooth surface metric with no local isometric immersion in R³.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A Smooth Metric with No Local Isometric Immersion into Three-Space","dir":"A-Smooth-Metric-with-No-Local-Isometric-Immersion-into-Three-Space-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"335","t":"Gromov's integral scalar-curvature inequality","d":"Proves ∫_(M)(Scal_(g)⁻)^(n/2) dV_(g)≥ aₙ‖ M‖ for every closed connected oriented smooth n-manifold, n≥3, and every smooth metric, with aₙ>0 depending only on dimension. Here Scal_(g)⁻=max{0,-Scal_(g)} and ‖ M‖ is real simplicial volume. Also proves rational inessentiality under positive scalar curvature, resolving the Gromov–Lawson conjecture; every nonnegative-scalar-curvature metric on a closed aspherical manifold is flat.","disc":15,"tier":"C","effort":"S","widget":"Text card on integral scalar curvature vs simplicial volume.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"An integral scalar curvature bound for real simplicial volume","dir":"An-integral-scalar-curvature-bound-for-real-simplicial-volume-October-5-2026","pdf":"v126-proof.pdf","lean":false},{"t":"Positive scalar curvature forces rational inessentiality","dir":"Positive-scalar-curvature-forces-rational-inessentiality-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"336","t":"Spectral scalar curvature and codimension-two width","d":"Every complete connected smooth boundaryless n-manifold, n≥3, satisfying -4Δ+Scal≥1 as a quadratic-form inequality admits a continuous map to a simplicial complex of dimension at most n-2 whose entire fibers have diameter bounded only by n in the original metric. This strengthens Gromov's width conclusion to spectral scalar curvature. Universal covers of closed positive-scalar-curvature manifolds also have continuous macroscopic dimension at most n-2 for every n≥2.","disc":15,"tier":"C","effort":"S","widget":"Text card on scalar curvature and Urysohn width.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Spectral scalar curvature and uniform Urysohn width","dir":"Spectral-scalar-curvature-and-uniform-Urysohn-width-October-5-2026","pdf":"main.pdf","lean":false},{"t":"Spectral scalar curvature and Urysohn width in dimension three","dir":"Spectral-scalar-curvature-and-Urysohn-width-in-dimension-three-October-5-2026","pdf":"spectral-urysohn-three-manifolds.pdf","lean":false},{"t":"Positive scalar curvature and uniform codimension-two width","dir":"Positive-scalar-curvature-and-uniform-codimension-two-width-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"337","t":"Cartan–Hadamard isoperimetry and CAT(0) fillings","d":"Proves generalized Cartan–Hadamard isoperimetry in every dimension: in a complete simply connected manifold with sectional curvature at most κ≤0, every finite-volume finite-perimeter set satisfies the sharp comparison with the equal-volume model ball. Bounded positive-volume equality regions for κ=0 are Euclidean balls. Also proves sharp Euclidean filling bounds for compactly supported integral n-cycles, n≥2, in arbitrary proper CAT(0) spaces.","disc":15,"tier":"B","effort":"M","widget":"Show geodesic balls vs arbitrary regions in negatively curved models (hyperbolic plane/space) and compare perimeters at equal volume.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Generalized Cartan–Hadamard isoperimetry and Euclidean equality rigidity","dir":"Generalized-Cartan-Hadamard-isoperimetry-and-Euclidean-equality-rigidity-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Sharp integral fillings in CAT(0) spaces September 23 2026","dir":"Sharp-integral-fillings-in-CAT(0)-spaces-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"338","t":"Yau's uniformization conjecture","d":"Proves Yau's uniformization conjecture: every complete connected noncompact Kähler manifold with strictly positive holomorphic bisectional curvature is biholomorphic to ℂⁿ.","disc":15,"tier":"C","effort":"S","widget":"Text card on Yau's uniformization conjecture for positive bisectional curvature.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Uniformization of complete Kähler manifolds with positive bisectional curvature","dir":"Uniformization-of-complete-Kahler-manifolds-with-positive-bisectional-curvature-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"339","t":"Katok's entropy rigidity conjecture","d":"Proves Katok's entropy rigidity conjecture for closed connected Riemannian manifolds of dimension at least three with strictly negative sectional curvature: normalized Liouville measure maximizes entropy for the geodesic flow if and only if the metric is locally symmetric.","disc":15,"tier":"C","effort":"S","widget":"Card on entropy rigidity of geodesic flows.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Entropy equality and local symmetry in negative curvature","dir":"Entropy-equality-and-local-symmetry-in-negative-curvature-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"340","t":"A counterexample to the nearby Lagrangian conjecture","d":"Disproves the unrestricted nearby Lagrangian conjecture. For some sufficiently large even N, constructs a closed exact embedded Lagrangian in T*(S⁹× S^(N-1)) that is diffeomorphic to the base but not Hamiltonian isotopic to its zero section.","disc":15,"tier":"C","effort":"S","widget":"Card only: counterexample to the nearby Lagrangian conjecture.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A counterexample to the nearby Lagrangian conjecture","dir":"A-counterexample-to-the-nearby-Lagrangian-conjecture-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"341","t":"Donaldson's hypersymplectic deformation conjecture","d":"Proves Donaldson's hypersymplectic deformation conjecture in a cohomology-preserving form. Every positive triple of smooth closed two-forms on a closed connected oriented four-manifold, normalized by ∫ωᵢ∧ωⱼ=δᵢⱼ, deforms through positive closed triples to a hyperkähler triple while preserving all three cohomology classes. Any positive triple can first be normalized by a constant linear change.","disc":15,"tier":"C","effort":"S","widget":"Text card on hypersymplectic deformation to hyperkahler.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Deforming hypersymplectic four-manifolds to hyperkähler triples","dir":"Deforming-hypersymplectic-four-manifolds-to-hyperkahler-triples-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"342","t":"Donaldson's tamed-to-compatible conjecture","d":"Proves Donaldson's tamed-to-compatible conjecture: every smooth almost complex structure on a closed four-manifold that is tamed by a symplectic form admits a compatible symplectic form. The almost complex structure stays fixed; the form's cohomology class may change.","disc":15,"tier":"C","effort":"S","widget":"Text card on tamed vs compatible almost complex structures on 4-manifolds.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Taming implies compatibility on four-manifolds","dir":"Taming-implies-compatibility-on-four-manifolds-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"343","t":"Sharp symplectic ball-packing criteria in higher dimensions","d":"Resolves the Siegel–Yao conjecture for arbitrary capacities in every dimension 2n≥6. Finitely many closed symplectic balls of capacities R₁,…,Rₖ embed disjointly into an open ball of capacity R exactly when ∑ᵢRᵢⁿ<Rⁿ and Rᵢ+Rⱼ<R for every distinct pair i,j.","disc":15,"tier":"A","effort":"S","widget":"Choose a target ball capacity and up to k ball capacities with sliders; the page decides instantly whether they pack symplectically (sum Rᵢⁿ < Rⁿ and pairwise Rᵢ+Rⱼ<R) and contrasts with volume packing.","related":["viazovska"],"conj":false,"page":null,"lean":0,"papers":[{"t":"Symplectic Ball Packings in Higher Dimensions","dir":"Symplectic-Ball-Packings-in-Higher-Dimensions-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"344","t":"The metric Blaschke conjecture","d":"Proves the metric Blaschke conjecture: every closed connected Riemannian manifold of positive dimension whose injectivity radius equals its diameter is, up to scaling, a standard compact rank-one symmetric space.","disc":15,"tier":"C","effort":"S","widget":"Text card on the metric Blaschke conjecture (injectivity radius = diameter forces round spheres/projective spaces).","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"The metric Blaschke theorem","dir":"The-metric-Blaschke-theorem-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"345","t":"Infinitely many closed geodesics on spheres and three-manifolds","d":"Proves that every smooth Riemannian metric on Sⁿ, n≥2, has infinitely many prime closed geodesics with pairwise distinct images. The same conclusion holds on every closed manifold admitting a finite smooth spherical cover and on every closed three-manifold, without orientability or nondegeneracy restrictions.","disc":15,"tier":"B","effort":"M","widget":"Compute and draw closed geodesics on ellipsoids and bumpy spheres by shooting.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Infinitely many closed geodesic images on every Riemannian sphere","dir":"Infinitely-many-closed-geodesic-images-on-every-Riemannian-sphere-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"346","t":"Sharp singular-set bounds for stationary integral varifolds","d":"Proves that every stationary integral m-varifold in a Euclidean open set has singular set of Hausdorff dimension at most m-1, a sharp bound in every positive dimension and codimension. On round spheres, the family also proves almost-everywhere regularity: the singular set has zero m-dimensional Hausdorff measure.","disc":15,"tier":"C","effort":"S","widget":"Card only: singular sets of stationary varifolds.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Codimension-One Bound for the Singular Set of a Stationary Integral Varifold","dir":"A-Codimension-One-Bound-for-the-Singular-Set-of-a-Stationary-Integral-Varifold-October-5-2026","pdf":"varifold-singular-dimension.pdf","lean":false},{"t":"Almost-everywhere regularity of stationary integral varifolds","dir":"Almost-everywhere-regularity-of-stationary-integral-varifolds-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"347","t":"Counterexamples to strong forms of Arnold's fixed-point conjecture","d":"Disproves stable-Morse lower bounds for nondegenerate Hamiltonian fixed points: on simply connected closed Kähler manifolds of real dimension 22, the deficit below the stable Morse number is unbounded. A separate Hamiltonian diffeomorphism of the complex quadric threefold has exactly three fixed points, fewer than the four critical points required of every smooth function.","disc":15,"tier":"C","effort":"S","widget":"Text card on Hamiltonian maps with fewer fixed points than Morse critical points.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Hamiltonian Fixed Points Below the Stable Morse Number in Dimension Twenty-Two","dir":"Hamiltonian-Fixed-Points-Below-the-Stable-Morse-Number-in-Dimension-Twenty-Two-October-5-2026","pdf":"hamiltonian-fixed-points-below-stable-morse-number.pdf","lean":false},{"t":"Sharpness of the Cyclic Integral Floer Bound Below the Stable Morse Number","dir":"Sharpness-of-the-Cyclic-Integral-Floer-Bound-Below-the-Stable-Morse-Number-October-5-2026","pdf":"sharp-cyclic-integral-floer-bound-below-stable-morse-number.pdf","lean":false},{"t":"Hamiltonian Fixed Points Below the Stable Morse Number","dir":"Hamiltonian-Fixed-Points-Below-the-Stable-Morse-Number-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"A nondegenerate counterexample to the Morse-number Arnold bound","dir":"A-nondegenerate-counterexample-to-the-Morse-number-Arnold-bound-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Three fixed points on the symplectic quadric threefold","dir":"A-degenerate-counterexample-to-the-critical-number-Arnold-bound-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"348","t":"Nonnegatively curved Einstein four-manifolds and a topological gap","d":"Classifies closed connected Einstein four-manifolds with positive Einstein constant and nonnegative sectional curvature: up to scaling, their universal Riemannian covers are the round S⁴, Fubini–Study mathbbCP², or a product of equal round two-spheres. A closed simply connected nonnegatively curved four-manifold is diffeomorphic to one of these whenever the scale-invariant L² norm of its trace-free Ricci curvature lies below a universal positive constant.","disc":15,"tier":"C","effort":"S","widget":"Text card on Einstein 4-manifolds with nonnegative curvature.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Zero-Plane Rigidity for Einstein Four-Manifolds","dir":"Zero-Plane-Rigidity-for-Einstein-Four-Manifolds-October-4-2026","pdf":"einstein-boundary.pdf","lean":false},{"t":"An L² Einstein Gap for Nonnegatively Curved Four-Manifolds","dir":"An-L2-Einstein-Gap-for-Nonnegatively-Curved-Four-Manifolds-October-5-2026","pdf":"einstein-gap.pdf","lean":false},{"t":"Positively curved Einstein four-manifolds","dir":"Positively-curved-Einstein-four-manifolds-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"349","t":"The Solomon–Yau least-volume conjecture","d":"Proves the Solomon–Yau least-volume conjecture for minimal hypersurfaces of round spheres. For every m≥2, a closed connected minimal immersion into the unit sphere Sᵐ⁺¹ with non-totally-geodesic image has volume at least that of the smallest minimal Clifford product, counting covering multiplicity.","disc":15,"tier":"B","effort":"M","widget":"Render Clifford tori/products in Sᵐ⁺¹ (stereographically) with their volumes and compare to other minimal hypersurfaces.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Solomon–Yau least-volume theorem","dir":"The-Solomon-Yau-least-volume-theorem-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"350","t":"Yau's nodal conjecture: surfaces and counterexamples","d":"Proves the sharp C√λ upper bound for nodal length on every fixed smooth closed surface, completing Yau's conjecture there. The upper bound fails for fixed smooth metrics in dimensions three and four, including metrics on S³ arbitrarily close to round. In dimension five, nodal measure can grow faster than λ^(1/2+ε₀) for some fixed ε₀>0, ruling out even arbitrarily small power losses.","disc":15,"tier":"B","effort":"M","widget":"Draw Laplace eigenfunctions on a torus/sphere/flat surface, highlight nodal lines, and plot nodal length against sqrt(lambda).","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Sharp nodal length on smooth surfaces","dir":"Sharp-nodal-length-on-smooth-surfaces-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Smooth counterexamples to Yau's nodal upper bound in dimensions three and four","dir":"Smooth-counterexamples-to-Yaus-nodal-upper-bound-in-dimensions-three-and-four-September-23-2026","pdf":"paper.pdf","lean":true},{"t":"Power-law violations of Yau's nodal upper bound","dir":"Power-law-violations-of-Yaus-nodal-upper-bound-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"351","t":"Scalar curvature detects four-dimensional Ricci-flow singularities","d":"Proves that a smooth Ricci flow on a closed four-manifold extends past any finite time at which scalar curvature remains uniformly bounded. A higher-dimensional counterexample has bounded scalar curvature but unbounded full curvature at its finite maximal time, disproving the unrestricted scalar-curvature extension conjecture.","disc":15,"tier":"C","effort":"S","widget":"Card on Ricci flow singularities and scalar curvature.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A closed Ricci flow with bounded scalar curvature and finite-time curvature blowup","dir":"A-closed-Ricci-flow-with-bounded-scalar-curvature-and-finite-time-curvature-blowup-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Bounded scalar curvature and smooth extension of four-dimensional Ricci flow","dir":"Bounded-scalar-curvature-and-smooth-extension-of-four-dimensional-Ricci-flow-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Path selection and an elliptic inequality on degenerating Ricci-flat trees","dir":"Path-selection-and-an-elliptic-inequality-on-degenerating-Ricci-flat-trees-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"352","t":"Finite-time singularity of Calabi flow","d":"Disproves Chen's smooth long-time existence conjecture for Calabi flow by constructing a smooth U(10)-invariant Kähler metric on mathbbCP¹⁰ whose flow develops a finite-time singularity. The metric lies in the Fubini–Study class, so the failure occurs even in a class containing a constant-scalar-curvature metric.","disc":15,"tier":"A","effort":"L","widget":"Shoot the self-similar ODE profile behind the Calabi-flow blow-up on CP¹0 and watch the certified matching; animate the curvature blowing up.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A finite-time singularity of Calabi flow on projective space","dir":"A-finite-time-singularity-of-Calabi-flow-on-projective-space-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"353","t":"The sharp dimension threshold for affine Bernstein rigidity","d":"Proves that every smooth locally uniformly convex affine-maximal graph of dimension three through nine, complete for its induced Euclidean metric, is an elliptic paraboloid. A smooth entire nonquadratic example in dimension ten makes this range sharp. In dimensions three through nine, the paraboloid classification also holds for connected open locally uniformly convex affine-maximal hypersurfaces complete for the affine Berwald–Blaschke metric.","disc":15,"tier":"B","effort":"M","widget":"Numerically integrate the paper's radial ODE system and plot the entire non-quadratic affine-maximal graph profile in dimension 10 versus the forced paraboloid in dims 3–9.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A Smooth Nonquadratic Entire Affine Maximal Graph in Dimension Ten","dir":"Smooth-Nonquadratic-Affine-Maximal-Graph-in-Dimension-Ten-October-5-2026","pdf":"affine-maximal-dimension-ten.pdf","lean":false},{"t":"The affine Bernstein theorem in dimensions three through nine","dir":"The-affine-Bernstein-theorem-in-dimensions-three-through-nine-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"354","t":"Isoperimetric regions in the cubic three-torus","d":"Determines the isoperimetric profile of the unit cubic flat three-torus and classifies every finite-perimeter minimizer: balls, circular tubes around shortest closed geodesics, coordinate slabs, and their complements. The transition volumes are 4π/81 and 1/π, with exactly the adjacent two types minimizing at each transition.","disc":15,"tier":"A","effort":"S","widget":"Slide the enclosed volume in the unit cubic 3-torus and watch the optimal shape switch ball -> tube -> slab (and complements), rendered in WebGL with the area profile alongside.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Isoperimetric Conjecture for the Cubic Flat Three-Torus","dir":"The-Isoperimetric-Conjecture-for-the-Cubic-Flat-Three-Torus-September-24-2026","pdf":"article.pdf","lean":false}]},{"id":"355","t":"Unique tangent flows at the first surface singularity","d":"Proves the first-singular-time case of tangent-flow uniqueness for smooth compact connected embedded surfaces without boundary in ℝ³. At every singular point, all fixed-center backward tangent flows agree as area measures at every negative time in the original ambient coordinates, without mean-convexity or a prescribed tangent model.","disc":15,"tier":"B","effort":"L","widget":"Run mean curvature flow on a surface mesh (dumbbell neck pinch) and zoom into the singularity to see the cylinder tangent flow.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Uniqueness of tangent flows at the first singular time of embedded surface mean-curvature flow","dir":"Tangent-flow-uniqueness-2026-09-24","pdf":"paper.pdf","lean":false}]},{"id":"356","t":"Gigli's characterization of Alexandrov curvature","d":"Proves Gigli's conjecture: in every integer dimension n≥2, Alexandrov curvature at least κ is characterized by the full-support RCD((n-1)κ,n) condition with reference measure ℋⁿ and distributional sectional curvature at least κ in the original global test classes. The RCD condition is unreduced.","disc":15,"tier":"C","effort":"S","widget":"Text card on Gigli's characterization of Alexandrov curvature via RCD.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Gigli’s distributional curvature characterization of Alexandrov spaces","dir":"Giglis-distributional-curvature-characterization-of-Alexandrov-spaces-September-24-2026","pdf":"main.pdf","lean":false},{"t":"Weak Hessian bounds along every geodesic in RCD spaces","dir":"Weak-Hessian-bounds-along-every-geodesic-in-RCD-spaces-September-24-2026","pdf":"weak-hessian-geodesics.pdf","lean":true}]},{"id":"357","t":"Bi-Lipschitz coordinates at every regular RCD point","d":"Proves that every regular point of a noncollapsed RCD(K,n) space, for K∈ℝ and integer n≥2, has an open neighborhood bi-Lipschitz to an open subset of ℝⁿ. Regularity requires all pointed tangents to be Euclidean, the reference measure is exactly ℋⁿ, and the chart compares ambient distances with a point-dependent finite constant.","disc":15,"tier":"C","effort":"S","widget":"Card on RCD spaces.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Bi-Lipschitz Coordinates at Regular Points of Noncollapsed RCD Spaces","dir":"Bi-Lipschitz-Coordinates-at-Regular-Points-of-Noncollapsed-RCD-Spaces-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"358","t":"A three-manifold with no conjugate points and no nonpositively curved metric","d":"Constructs a closed connected orientable smooth three-manifold that admits a metric without conjugate points but no metric of nonpositive sectional curvature. This answers negatively, already in dimension three, whether the first metric-existence property implies the second.","disc":15,"tier":"C","effort":"S","widget":"Card only: a 3-manifold with no conjugate points but no nonpositively curved metric.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A Three-Manifold Without Conjugate Points and Without a Nonpositively Curved Metric","dir":"A-Three-Manifold-Without-Conjugate-Points-and-Without-a-Nonpositively-Curved-Metric-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"359","t":"Negative Kähler curvature without bounded holomorphic coordinates","d":"Constructs a contractible domain in ℂ³ with a complete negatively pinched Kähler metric but no bounded holomorphic coordinates, disproving bounded-domain uniformization in this setting. A higher-dimensional example has sectional curvature at most -1 and only constant bounded holomorphic functions; its curvature is not bounded below.","disc":15,"tier":"C","effort":"S","widget":"Text card on negatively curved Kahler domains without bounded coordinates.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A negatively pinched Kähler threefold without bounded holomorphic coordinates","dir":"A-negatively-pinched-Kahler-threefold-without-bounded-holomorphic-coordinates-September-25-2026","pdf":"paper.pdf","lean":true},{"t":"One-sided negative sectional curvature and the holomorphic Liouville property","dir":"One-sided-negative-sectional-curvature-and-the-holomorphic-Liouville-property-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"360","t":"Villani’s convexity conjecture and regular optimal transport","d":"On every closed connected Riemannian manifold of dimension at least two satisfying weak Ma–Trudinger–Wang curvature, all tangent injectivity domains are convex, resolving Villani’s conjecture in this setting. For squared-distance transport between measurable probability densities bounded above and away from zero, the optimal map and its inverse are Hölder continuous.","disc":15,"tier":"C","effort":"S","widget":"Text card on Ma-Trudinger-Wang curvature and regularity of optimal transport on manifolds.","related":[],"conj":false,"page":null,"lean":2,"papers":[{"t":"Global Support and Convex Injectivity Domains under Weak MTW","dir":"Global-Support-and-Convex-Injectivity-Domains-under-Weak-MTW-September-25-2026","pdf":"paper.pdf","lean":true},{"t":"Uniform Bi-Holder Transport from Weak MTW","dir":"Uniform-Bi-Holder-Transport-from-Weak-MTW-September-25-2026","pdf":"paper.pdf","lean":true}]},{"id":"361","t":"Counterexamples to Yau's harmonic dimension bound","d":"Disproves Yau's proposed Euclidean dimension bound for harmonic functions of integer growth on manifolds with nonnegative Ricci curvature. For every sufficiently large integer k, a complete smooth metric on ℝ³ has at least (k+2)² independent harmonic functions of growth at most k, exceeding the Euclidean count (k+1)². The metric may depend on k.","disc":15,"tier":"B","effort":"M","widget":"Count harmonic polynomials of growth k on R³ ((k+1)²) and explain how a non-Euclidean metric can host more.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"A counterexample to integer-degree harmonic dimension comparison","dir":"A-counterexample-to-integer-degree-harmonic-dimension-comparison-September-25-2026","pdf":"paper.pdf","lean":true},{"t":"A Three-Dimensional Counterexample to Integer-Degree Harmonic Dimension Comparison","dir":"A-Three-Dimensional-Counterexample-to-Integer-Degree-Harmonic-Dimension-Comparison-September-26-2026","pdf":"paper.pdf","lean":false}]},{"id":"362","t":"Global smoothness for relativistic Vlasov–Maxwell","d":"Proves large-data global existence and uniqueness for the three-dimensional, one-species relativistic Vlasov–Maxwell system. Smooth admissible initial data may be arbitrary provided the particle density is compactly supported and the electromagnetic fields have finite energy and bounded derivatives of every order; the solution remains smooth on every finite time interval.","disc":16,"tier":"B","effort":"L","widget":"Run a reduced (1D/2D) relativistic Vlasov-Maxwell particle-in-cell simulation showing plasma evolving without blow-up.","related":["grad"],"conj":false,"page":null,"lean":1,"papers":[{"t":"Global classical solutions of the three-dimensional relativistic Vlasov–Maxwell system","dir":"Global-classical-solutions-of-the-three-dimensional-relativistic-Vlasov-Maxwell-system-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"363","t":"Boltzmann nonuniqueness with exact local conservation","d":"Constructs two distinct global entropy solutions of the three-dimensional periodic hard-sphere Boltzmann equation from the same nonnegative initial density, with bounded velocity support and finite mass, energy and absolute entropy. Both are strongly continuous in L¹ and satisfy exact local conservation of mass, momentum and kinetic energy.","disc":16,"tier":"C","effort":"S","widget":"Card on nonuniqueness for the Boltzmann equation.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Nonuniqueness with local conservation for the hard-sphere Boltzmann equation","dir":"Nonuniqueness-with-local-conservation-for-the-hard-sphere-Boltzmann-equation-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Nonuniqueness for the periodic hard-sphere Boltzmann equation","dir":"Nonuniqueness-for-the-periodic-hard-sphere-Boltzmann-equation-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"364","t":"Kinetic limits and fluctuations over the Boltzmann lifespan","d":"Derives the nonlinear Boltzmann equation from three-dimensional grand-canonical Newtonian gases throughout every regular kinetic interval with uniform Gaussian decay. Stable finite-range radial potentials may have attractive wells and a singular repulsive core; initial pair exclusion and spatially summable Gaussian density and gradient bounds are assumed. A companion gives finite-dimensional hard-sphere Gaussian fluctuations, centered at the exact microscopic expectation and governed by the linear fluctuating Boltzmann equation.","disc":16,"tier":"B","effort":"M","widget":"Simulate a dilute hard-sphere gas and compare the empirical velocity distribution's evolution with the Boltzmann equation.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The Boltzmann–Grad limit for stable radial potentials on regular kinetic intervals","dir":"The-Boltzmann-Grad-limit-for-stable-radial-potentials-on-regular-kinetic-intervals-September-23-2026","pdf":"paper.pdf","lean":false},{"t":"Hard-sphere fluctuations on the regular Boltzmann lifespan","dir":"Hard-sphere-fluctuations-on-the-regular-Boltzmann-lifespan-September-23-2026","pdf":"paper.pdf","lean":false}]},{"id":"365","t":"Joint metric and connection recovery from one boundary patch","d":"Zero-frequency measurements on any nonempty open boundary patch determine a smooth metric and smooth unitary connection on a trivial Hermitian rank-two bundle over a compact connected manifold of dimension at least three, up to diffeomorphism and gauge fixed on that patch. Inputs and observations use the same patch. In contrast, distinct uniformly positive bounded measurable scalar conductivities on a three-dimensional ball can have identical full-boundary data.","disc":16,"tier":"C","effort":"S","widget":"Text card on the Calderon problem from one boundary patch.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"Determination of a metric and a unitary connection from one boundary patch","dir":"Determination-of-a-metric-and-a-unitary-connection-from-one-boundary-patch-October-5-2026","pdf":"paper.pdf","lean":false},{"t":"Smooth anisotropic uniqueness in the Calderón problem from one boundary patch","dir":"Smooth-Anisotropic-Uniqueness-in-the-Calderon-Problem-from-One-Boundary-Patch-September-24-2026","pdf":"paper.pdf","lean":false},{"t":"Nonuniqueness for bounded measurable scalar conductivities in three dimensions","dir":"Nonuniqueness-for-Bounded-Measurable-Scalar-Conductivities-in-Three-Dimensions-September-23-2026","pdf":"paper.pdf","lean":true}]},{"id":"366","t":"The planar Mumford–Shah regularity conjecture","d":"Resolves the interior regularity conjecture for reduced absolute planar Mumford–Shah minimizers with bounded fidelity data. Locally, the closed discontinuity set is a C^(1,α) arc, a regular crack tip, or three arcs meeting at 120^(∘); only finitely many global connected components meet any compact interior region.","disc":16,"tier":"B","effort":"M","widget":"Draw/upload an image and run a Mumford-Shah (Ambrosio-Tortorelli) segmentation, highlighting crack tips and 120-degree triple junctions.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Interior regularity of planar Mumford–Shah minimizers","dir":"Interior-regularity-of-planar-Mumford-Shah-minimizers-September-24-2026","pdf":"Interior-regularity-of-planar-Mumford-Shah-minimizers-September-24-2026.pdf","lean":false}]},{"id":"367","t":"The critical dimension for the one-phase Bernoulli problem","d":"Establishes seven as the first dimension admitting a nonflat, one-homogeneous global minimizer of the one-phase Bernoulli energy. Consequently, minimizing free boundaries are smooth through dimension six, and their singular sets have dimension at most n-7 in higher dimensions.","disc":16,"tier":"B","effort":"L","widget":"Show axisymmetric free-boundary cones and their energy, with the dimension slider indicating stability up to 6 and failure at 7.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"The critical dimension for one-phase Bernoulli minimizers","dir":"The-critical-dimension-for-one-phase-Bernoulli-minimizers-September-24-2026","pdf":"The-critical-dimension-for-one-phase-Bernoulli-minimizers-September-24-2026.pdf","lean":false}]},{"id":"368","t":"The three-dimensional Ball–Evans approximation problem","d":"Resolves the three-dimensional Ball–Evans approximation problem: every W^(1,p) homeomorphism between arbitrary bounded domains in ℝ³, for 1≤ p<∞, is a strong W^(1,p) limit of smooth diffeomorphisms onto the same target.","disc":16,"tier":"C","effort":"S","widget":"Text card on approximating Sobolev homeomorphisms by diffeomorphisms in 3D.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Strong diffeomorphic approximation in three dimensions for 1≤p≤2","dir":"Strong-diffeomorphic-approximation-in-three-dimensions-for-1-le-p-le-2-September-24-2026","pdf":"main.pdf","lean":false},{"t":"Strong diffeomorphic approximation in three dimensions for p>2","dir":"Strong-diffeomorphic-approximation-in-three-dimensions-for-p-gt-2-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"369","t":"The hot spots conjecture for simply connected planar domains","d":"Proves a strict form of Burdzy's simply connected hot spots conjecture. On every smooth bounded simply connected planar domain, each nonzero eigenfunction for the first positive Neumann eigenvalue has no interior critical point, so all global extrema lie on the boundary. Eigenvalue multiplicity is allowed.","disc":16,"tier":"B","effort":"M","widget":"Draw a simply connected domain, compute its first Neumann eigenfunction by finite elements, and see the hottest and coldest points sit on the boundary.","related":[],"conj":true,"page":null,"lean":0,"papers":[{"t":"Strict hot spots and absence of interior critical points on smooth simply connected planar domains","dir":"Strict-hot-spots-and-absence-of-interior-critical-points-on-smooth-simply-connected-planar-domains-September-24-2026","pdf":"main.pdf","lean":false}]},{"id":"370","t":"The subcritical Lane–Emden and Hénon–Lane–Emden conjectures","d":"Resolves the subcritical Lane–Emden conjecture and its weighted Hénon extension. For n≥2, p,q>0 and real A,B, the system -Δ u=|x|^(A) vᵖ, -Δ v=|x|^(B) u^(q) has no positive entire solution when (n+A)/(p+1)+(n+B)/(q+1)>n-2, with solutions continuous at the origin and classical elsewhere. No symmetry or growth assumption is needed. Known radial existence gives the exact existence criterion for n≥3 and A,B>-2.","disc":16,"tier":"B","effort":"S","widget":"Shoot radial solutions of the Lane-Emden/Henon system and see the critical hyperbola separating existence from nonexistence in the (p,q) plane.","related":[],"conj":false,"page":null,"lean":1,"papers":[{"t":"The Subcritical Hénon–Lane–Emden Conjecture","dir":"The-Subcritical-Henon-Lane-Emden-Conjecture-September-24-2026","pdf":"paper.pdf","lean":true}]},{"id":"371","t":"Stable blowup for a defocusing Schrödinger equation","d":"For a sufficiently large odd nonlinearity power, constructs a nonempty open set of initial data in Hᵏ(𝕋¹²), with k>8, whose solutions of the scalar defocusing nonlinear Schrödinger equation blow up in finite time. Thus finite-time blowup is stable under Sobolev perturbations in this supercritical regime.","disc":16,"tier":"C","effort":"S","widget":"Text card on stable blowup for defocusing NLS on T¹2.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Stable self-similar blowup for a supercritical defocusing Schrödinger equation on the torus","dir":"Stable-Self-Similar-Blowup-for-a-Supercritical-Defocusing-Schrodinger-Equation-on-the-Torus-September-24-2026","pdf":"paper.pdf","lean":false}]},{"id":"372","t":"Global uniqueness in smooth isotropic elasticity","d":"Proves that full static boundary displacement-to-traction data determine both smooth real Lamé moduli on every bounded connected smooth domain in ℝ³, provided μ>0 and 3λ+2μ>0 on the closure. Neither analyticity, proximity to constant coefficients nor prior knowledge near the boundary is required.","disc":16,"tier":"C","effort":"S","widget":"Text card on the elasticity inverse problem (determining Lame moduli from boundary data).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Global Uniqueness for the Smooth Isotropic Elasticity Inverse Problem","dir":"Global-Uniqueness-for-the-Smooth-Isotropic-Elasticity-Inverse-Problem-September-24-2026","pdf":"article.pdf","lean":false}]},{"id":"373","t":"Nonattainment in three-marginal Coulomb transport","d":"An optimal three-particle Coulomb configuration need not be a deterministic function of the first particle, even for smooth identical spatial densities. The Monge and Kantorovich infima agree, but the Monge infimum is not attained. The same phenomenon occurs for every inverse-power Riesz exponent in each dimension at least two, with a suitable density in each case.","disc":16,"tier":"B","effort":"M","widget":"Place three charges on a line with a smooth density and see optimal transport plans that split mass rather than follow a map.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A counterexample to the Monge ansatz for the three-marginal Coulomb cost","dir":"A-counterexample-to-the-Monge-ansatz-for-the-three-marginal-Coulomb-cost-September-25-2026","pdf":"paper.pdf","lean":false}]},{"id":"374","t":"Sharp one-third stability of optimal transport maps","d":"For uniform source measure ρ on a compact convex body with interior in dimension at least two, quadratic optimal transport maps satisfy ‖T_μ-T_ν‖_(L²(ρ))≤ C W₂(μ,ν)^(1/3) uniformly over targets in a fixed compact set. The exponent is sharp, even for three-atom targets, disproving Letrouit's conjectured square-root bound.","disc":16,"tier":"A","effort":"S","widget":"Tilt the central strip of a cube partition and watch two three-atom target measures barely move in W₂ while the optimal transport maps change a lot, giving the sharp exponent 1/3.","related":["voronoi"],"conj":false,"page":null,"lean":0,"papers":[{"t":"Sharp One-Third Stability of Brenier Maps","dir":"Sharp-One-Third-Stability-of-Brenier-Maps-September-25-2026","pdf":"article.pdf","lean":false}]},{"id":"375","t":"De Giorgi's conjecture in dimension eight","d":"Proves De Giorgi's conjecture at its sharp dimension-eight endpoint: every entire C² solution u:ℝ⁸→(-1,1) of Δ u=u³-u that is strictly increasing in one direction depends on only one linear coordinate. A stronger theorem classifies all stable entire solutions v:ℝ⁷→[-1,1] as constant wells or planar transitions, without an energy-growth assumption.","disc":16,"tier":"B","effort":"M","widget":"Show the planar tanh heteroclinic of Allen-Cahn and relax random initial data toward it in a 2D slice.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"A positive resolution of De Giorgi's conjecture in dimension eight","dir":"De-Giorgis-conjecture-in-dimension-eight-September-26-2026","pdf":"article.pdf","lean":false}]},{"id":"376","t":"Universal computation in forced Navier–Stokes flows","d":"Constructs viscous incompressible flows starting from rest on a fixed flat three-dimensional domain that perform universal computation under smooth external forcing. A terminating compiler turns a Turing machine and input into a finite program for the force, so a designated particle reaches a fixed region exactly when the machine halts. The viscosity is fixed, positive and computable.","disc":16,"tier":"B","effort":"L","widget":"Follow a fluid particle through programmed shear flows on a torus that execute a small reversible machine step by step.","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Finite Instructions and Solenoidal Shear Flows","dir":"Finite-Instructions-and-Solenoidal-Shear-Flows-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"A Fixed Particle Test for Computation in a Forced Viscous Flow","dir":"A-Fixed-Particle-Test-for-Computation-in-a-Forced-Viscous-Flow-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"Universal Computation with Eventually Stationary Navier–Stokes Forcing","dir":"Universal-Computation-with-Eventually-Stationary-Navier-Stokes-Forcing-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"Geometric Programs for Solenoidal Forcing","dir":"Geometric-Programs-for-Solenoidal-Forcing-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"Prefix Instructions and Incompressible Flows","dir":"Prefix-Instructions-and-Incompressible-Flows-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"Computation under Rapidly Vanishing Navier–Stokes Forcing","dir":"Computation-under-Rapidly-Vanishing-Navier-Stokes-Forcing-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"Velocity-Field Detection of Computation in Forced Navier–Stokes Flows","dir":"Velocity-Field-Detection-of-Computation-in-Forced-Navier-Stokes-Flows-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"Scalar Potentials and Slow Clocks for Forced Fluid Computation","dir":"Scalar-Potentials-and-Slow-Clocks-for-Forced-Fluid-Computation-September-27-2026","pdf":"manuscript.pdf","lean":false},{"t":"Incompressible Box Transport and Finite Computation","dir":"Incompressible-Box-Transport-and-Finite-Computation-September-27-2026","pdf":"manuscript.pdf","lean":false}]},{"id":"377","t":"Interior C^(1,α) regularity for infinity-harmonic functions","d":"Proves uniform interior C^(1,α_(d)) regularity for bounded infinity-harmonic functions in every dimension d≥3, for a positive exponent depending only on dimension. The gradient's supremum norm and Hölder seminorm on the half unit ball are bounded by a dimension-dependent constant times the oscillation on the unit ball. The exponent is not explicit.","disc":16,"tier":"B","effort":"M","widget":"Solve the infinity-Laplacian on a grid (AMLE / tug-of-war) for user-drawn boundary data, and show gradient regularity, e.g. Aronsson's x^(4/3)-y^(4/3).","related":[],"conj":false,"page":null,"lean":0,"papers":[{"t":"Uniform Interior C^(1,α) Estimates for Infinity-Harmonic Functions","dir":"Uniform-Interior-C1alpha-Estimates-for-Infinity-Harmonic-Functions-October-4-2026","pdf":"interior-c1-infinity-harmonic.pdf","lean":false}]}]};
